# Inisialisasi logger
logger = logging.getLogger(__name__)

# Nama database (sesuaikan dengan kode asli kamu)
DB_NAME = "coins.db"

# Fungsi untuk memeriksa akses pengguna (placeholder, sesuaikan dengan kode asli kamu)
async def check_user_access(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    # Placeholder untuk logika pengecekan akses pengguna
    # Misalnya, cek apakah pengguna memiliki langganan aktif
    return True  # Untuk saat ini, selalu kembalikan True

# Fungsi untuk menampilkan menu utama
async def show_main_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        # Definisikan tombol untuk menu utama
        main_keyboard = [
            ["📊 Dashboard", "👤 Setting"],
            ["🏢 About BJB Sekuritas", "❓ Help"],
            ["💳 Langganan"],
            ["👥 Join Group"]
        ]
        main_reply_markup = ReplyKeyboardMarkup(
            main_keyboard,
            resize_keyboard=True,
            one_time_keyboard=False,
            input_field_placeholder="Pilih opsi:"
        )

        # Set state pengguna ke menu utama
        context.user_data["menu_state"] = "main_menu"

        # Kirim pesan dengan menu utama
        await update.message.reply_text(
            "Selamat datang kembali di menu utama! Pilih opsi di bawah untuk melanjutkan:",
            reply_markup=main_reply_markup,
            parse_mode="Markdown"
        )
    except Exception as e:
        logger.error(f"Error di show_main_menu: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat menampilkan menu utama. Silakan coba lagi.",
            parse_mode="Markdown"
        )

# Fungsi untuk menangani perintah /start
async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    logger.info("Fungsi start dipanggil")
    try:
        # Ambil nama pengguna dengan pengecekan tambahan
        user = update.effective_user
        user_name = user.first_name if user and user.first_name else "Sobat Trader"

        # Tentukan waktu saat ini dalam zona waktu WIB
        wib_timezone = pytz.timezone('Asia/Jakarta')
        current_time = datetime.now(wib_timezone)
        hour = current_time.hour
        time_str = current_time.strftime('%d %B %Y, %H:%M WIB')

        # Tentukan salam berdasarkan waktu
        if 0 <= hour < 12:
            greeting = "Selamat Pagi"
        elif 12 <= hour < 15:
            greeting = "Selamat Siang"
        elif 15 <= hour < 18:
            greeting = "Selamat Sore"
        else:
            greeting = "Selamat Malam"

        # Pilih pesan motivasi secara acak
        motivations = [
            "Hari ini adalah kesempatan baru untuk belajar strategi trading dan meraih profit! 💪",
            "Investasi cerdas dimulai dari langkah kecil. Yuk, pelajari pasar dan wujudkan tujuan finansialmu! 📈",
            "Jangan takut mencoba! Setiap praktik trading membawamu lebih dekat ke kesuksesan. 🚀",
            "Pasar selalu penuh peluang. Asah ilmu investasimu dan raih potensi maksimal! 🌟"
        ]
        motivation = random.choice(motivations)

        # Buat menu utama
        main_keyboard = [
            ["📊 Dashboard", "👤 Setting"],
            ["🏢 About BJB Sekuritas", "❓ Help"],
            ["💳 Langganan"],
            ["👥 Join Group"]
        ]
        main_reply_markup = ReplyKeyboardMarkup(
            main_keyboard,
            resize_keyboard=True,
            one_time_keyboard=False,
            input_field_placeholder="Pilih opsi:"
        )

        # Inisialisasi state pengguna
        context.user_data["menu_state"] = "main_menu"

        # Buat pesan sambutan
        welcome_message = (
            f"👋 *{greeting}, {user_name}!* Hari ini tanggal {time_str}\n\n"
            "Selamat datang di BJB Sekuritas Bot, asisten setia untuk petualangan investasi dan tradingmu! 🎯\n"
            f"{motivation}\n\n"
            "Pilih opsi di bawah untuk memulai, atau ketik /h untuk lihat semua fitur keren kami!\n"
            "💡 *Tips*: Coba fitur 'Dashboard' untuk update pasar terkini!"
        )

        # Kirim pesan sambutan dengan menu utama
        await update.message.reply_text(
            welcome_message,
            reply_markup=main_reply_markup,
            parse_mode="Markdown"
        )

    except pytz.exceptions.PytzError as e:
        logger.error(f"Error dengan zona waktu: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan dengan pengaturan waktu. Silakan coba lagi.",
            parse_mode="Markdown"
        )
    except Exception as e:
        logger.error(f"Error di start function: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat memulai bot. Silakan coba lagi nanti.",
            parse_mode="Markdown"
        )

