async def help_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await context.bot.send_message(
        chat_id=update.effective_chat.id,
        text="Berikut adalah perintah yang tersedia:\n"
             "/start - Memulai bot\n"
             "/h - Daftar perintah\n"
             "/edu - Menu Education interaktif\n"
             "/c <kode_saham> - Cek data saham (contoh: /c BJBR)\n"
             "/s <kode_saham> - Screening saham\n"
             "/p <kode_saham> <periode> - Persentase perubahan saham (contoh: /p BJBR 10)\n"
             "/pg <kode_saham> <periode> - Persentase perubahan saham dalam grafik (contoh: /pg BJBR 10)\n"
             "/ch <kode_saham> - Candlestick chart saham (contoh: /ch BJBR)\n"
             "/cb <hari> - Cari saham dengan candlestick hijau berturut-turut (contoh: /cb 3)\n"
             "/cm <hari> - Cari saham dengan candlestick merah berturut-turut (contoh: /cm 2)\n"
             "/bar <kode_saham> - Diagram batang volume saham (contoh: /bar BJBR)\n"
             "/b - Cek aktivitas broker\n"
             "/at <kode_saham> - Analisis teknikal (contoh: /at BJBR)\n"
             "/af <kode_saham> - Analisis fundamental (contoh: /af BJBR)\n"
             "/signal <kode_saham> - Sinyal trading (contoh: /signal BJBR)\n"
             "/heatmap <kode_saham> - Heatmap (contoh: /heatmap BJBR BBRI BJBR)\n"
             "/ih <indeks> [periode] - Heatmap perubahan harga indeks (contoh: /ih kompas100 harian atau /ih lq45 2025-03-05)\n"
             "/ih2 lq45 [periode] - Heatmap perubahan harga LQ45 (format khusus) (contoh: /ih2 lq45 harian atau /ih2 lq45 2025-03-05)\n"
             "/volatility <kode_saham> - Volatility saham (contoh: /signal BJBR)\n"
             "/predict <kode_saham> - Prediksi teknikal saham (contoh: /predict BJBR)\n"
             "/lx <index> - List Index Saham (contoh: /lx IDX30)\n"
             "/value [kode_saham] - Analisis value investing (contoh: /value atau /value BJBR)\n"
             "/watch <kode_saham> - Tambah saham ke daftar pantauan (contoh: /watch BJBR)\n"
             "/unwwatch <kode_saham> - Hapus saham dari daftar pantauan (contoh: /unwatch BJBR)\n"
             "/listwatch - Lihat daftar saham yang sedang dipantau\n"
             "/tg [periode] - Top Gainers (contoh: /tg harian, /tg mingguan, /tg 3)\n"
             "/tl [periode] - Top Losers (contoh: /tl harian, /tl mingguan, /tl 3)\n"
             "/tg100 [periode] - Top Gainers KOMPAS100 (contoh: /tg100 harian, /tg100 3)\n"
             "/tl100 [periode] - Top Losers KOMPAS100 (contoh: /tl100 harian, /tl100 3)\n"
             "/lq45 - Daftar saham LQ45 dengan opsi analisis\n"
             "/tg45 [periode] - Top Gainers LQ45 (contoh: /tg45 harian, /tg45 3)\n"
             "/tl45 [periode] - Top Losers LQ45 (contoh: /tl45 harian, /tl45 3)\n"
             "/jii70 - Daftar saham JII70 dengan opsi analisis\n"
             "/tg70 [periode] - Top Gainers JII70 (contoh: /tg70 harian, /tg70 3)\n"
             "/tl70 [periode] - Top Losers JII70 (contoh: /tl70 harian, /tl70 3)\n"
             "/list_sectors - Daftar sektor dan saham di dalamnya\n"
             "/tg_sector <sektor> [periode] - Top Gainers per sektor (contoh: /tg_sector Energy harian)\n"
             "/tl_sector <sektor> [periode] - Top Losers per sektor (contoh: /tl_sector Energy harian)\n"
             "/tg_mbx  [periode] - Top Gainers Saham MBX (contoh: /tg_mbx  harian)\n"
             "/tl_mbx  [periode] - Top Losers Saham MBX (contoh: /tl_mbx  harian)\n"
             "/tg_issi  [periode] - Top Gainers ISSI (contoh: /tg_issi Energy harian)\n"
             "/tl_issi  [periode] - Top Losers ISSI (contoh: /tl_issi Energy harian)\n"
             "/askbjbsekuritas - Analisis saham dengan simulasi xAI (contoh: /askbjbsekuritas Analisis saham BJBR.JK)\n"
             # Tambahan perintah baru yang kita buat
             "/tp <ticker> <qty> <buy_price> - Tambah saham ke portofolio (contoh: /tp BJBR 100 9000)\n"
             "/vp - Lihat portofolio\n"
             "/rp <ticker> - Hapus saham dari portofolio (contoh: /rp BJBR)\n"
             "/sa <ticker> <target> <above/below> - Set notifikasi harga (contoh: /sa BJBR 10000 above)\n"
             "/va - Lihat notifikasi aktif\n"
             "/as <ticker> - Analisis sentimen saham (contoh: /as BJBR)\n"
             "- /ic: Melihat harga Cryptocurrency di Indodax\n"
             "/feedback - Berikan rating (1-5 bintang) dan masukan (maks. 100 karakter)"
    )

import logging
import io
import os
import pandas as pd
import matplotlib.pyplot as plt
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes
import numpy as np
from scipy.stats import linregress
import pandas_ta as ta
import matplotlib.pyplot as plt
import mplfinance as mpf

# Konfigurasi logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("bot.log", encoding="utf-8"),
        logging.StreamHandler(),
    ],
)
logger = logging.getLogger(__name__)

# Fungsi untuk logging aman (menghindari UnicodeEncodeError)
def safe_log(message):
    return message.encode("utf-8", errors="ignore").decode("utf-8")

async def button_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    
    try:
        logger.info(safe_log(f"Callback diterima: {query.data} dari user {query.from_user.id}"))

        # Handler untuk Top Gainers (format top_gainers_)
        if query.data.startswith('top_gainers_'):
            index = query.data.split('_')[-1]
            logger.info(safe_log(f"Top Gainers dipilih: {index} oleh user {query.from_user.id}"))
            if index == 'lq45':
                await top_gainers_lq45(update, context)
            elif index == 'kompas100':
                await top_gainers_kompas100(update, context)
            elif index == 'jii70':
                await top_gainers_jii70(update, context)
            elif index == 'mbx':
                await top_gainers_mbx(update, context)
            elif index == 'issi':
                await top_gainers_issi(update, context)
            else:
                await query.message.reply_text(f"Indeks {index} tidak dikenali.")
            return

        # Handler untuk Top Losers (format top_losers_)
        elif query.data.startswith('top_losers_'):
            index = query.data.split('_')[-1]
            logger.info(safe_log(f"Top Losers dipilih: {index} oleh user {query.from_user.id}"))
            if index == 'lq45':
                await top_losers_lq45(update, context)
            elif index == 'kompas100':
                await top_losers_kompas100(update, context)
            elif index == 'jii70':
                await top_losers_jii70(update, context)
            elif index == 'mbx':
                await top_losers_mbx(update, context)
            elif index == 'issi':
                await top_losers_issi(update, context)
            else:
                await query.message.reply_text(f"Indeks {index} tidak dikenali.")
            return

        # Handler untuk format alternatif (misalnya, tg_lq45, tl_lq45)
        elif query.data.startswith('tg_'):
            index = query.data.split('_')[1]
            logger.info(safe_log(f"Top Gainers (format alternatif) dipilih: {index} oleh user {query.from_user.id}"))
            if index == 'lq45':
                await top_gainers_lq45(update, context)
            elif index == 'kompas100':
                await top_gainers_kompas100(update, context)
            elif index == 'jii70':
                await top_gainers_jii70(update, context)
            elif index == 'mbx':
                await top_gainers_mbx(update, context)
            elif index == 'issi':
                await top_gainers_issi(update, context)
            else:
                await query.message.reply_text(f"Indeks {index} tidak dikenali.")
            return
        elif query.data.startswith('tl_'):
            index = query.data.split('_')[1]
            logger.info(safe_log(f"Top Losers (format alternatif) dipilih: {index} oleh user {query.from_user.id}"))
            if index == 'lq45':
                await top_losers_lq45(update, context)
            elif index == 'kompas100':
                await top_losers_kompas100(update, context)
            elif index == 'jii70':
                await top_losers_jii70(update, context)
            elif index == 'mbx':
                await top_losers_mbx(update, context)
            elif index == 'issi':
                await top_losers_issi(update, context)
            else:
                await query.message.reply_text(f"Indeks {index} tidak dikenali.")
            return

        # Handler untuk saham spesifik (misalnya, lq45_BBCA, BBCA)
        elif query.data.startswith(('lq45_', 'kompas100_', 'jii70_', 'mbx_', 'issi_')):
            parts = query.data.split('_')
            index = parts[0]
            ticker = parts[1]
            logger.info(safe_log(f"Saham dipilih: {ticker} dari indeks {index} oleh user {query.from_user.id}"))
            submenu_keyboard = [
                [InlineKeyboardButton("Cek Data Saham", callback_data=f"c_{ticker}")],
                [InlineKeyboardButton("Analisis Teknikal", callback_data=f"at_{ticker}")],
                [InlineKeyboardButton("Candlestick Chart", callback_data=f"ch_{ticker}")],
                [InlineKeyboardButton("Sinyal Trading", callback_data=f"signal_{ticker}")],
                [InlineKeyboardButton("Prediksi Harga", callback_data=f"predict_{ticker}")],
                [InlineKeyboardButton("Analisis Fundamental", callback_data=f"af_{ticker}")],
                [InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")]
            ]
            reply_markup = InlineKeyboardMarkup(submenu_keyboard)
            stock_dict = {
                'lq45': LQ45_STOCKS,
                'kompas100': KOMPAS100_STOCKS,
                'jii70': JII70_STOCKS,
                'mbx': MBX_STOCKS,
                'issi': ISSI_STOCKS
            }.get(index, {})
            company_name = stock_dict.get(ticker, "Nama tidak tersedia")
            await query.message.reply_text(
                f"Pilih analisis untuk {ticker} - {company_name}:",
                reply_markup=reply_markup
            )
            return
        elif query.data in LQ45_STOCKS or query.data in KOMPAS100_STOCKS or query.data in JII70_STOCKS or query.data in MBX_STOCKS or query.data in ISSI_STOCKS:
            ticker = query.data
            logger.info(safe_log(f"Saham dipilih: {ticker} (format langsung) oleh user {query.from_user.id}"))
            submenu_keyboard = [
                [InlineKeyboardButton("Cek Data Saham", callback_data=f"c_{ticker}")],
                [InlineKeyboardButton("Analisis Teknikal", callback_data=f"at_{ticker}")],
                [InlineKeyboardButton("Candlestick Chart", callback_data=f"ch_{ticker}")],
                [InlineKeyboardButton("Sinyal Trading", callback_data=f"signal_{ticker}")],
                [InlineKeyboardButton("Prediksi Harga", callback_data=f"predict_{ticker}")],
                [InlineKeyboardButton("Analisis Fundamental", callback_data=f"af_{ticker}")],
                [InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")]
            ]
            reply_markup = InlineKeyboardMarkup(submenu_keyboard)
            company_name = LQ45_STOCKS.get(ticker, KOMPAS100_STOCKS.get(ticker, JII70_STOCKS.get(ticker, MBX_STOCKS.get(ticker, ISSI_STOCKS.get(ticker, "Nama tidak tersedia")))))
            await query.message.reply_text(
                f"Pilih analisis untuk {ticker} - {company_name}:",
                reply_markup=reply_markup
            )
            return

        # Handler existing lainnya
        if query.data == 'subscription':
            await subscription(update, context)
        
        # ... (semua handler lain dari kode sebelumnya tetap sama) ...

        # Handler untuk indikator teknikal
        elif query.data.startswith(('ma5_', 'ma20_', 'ma50_', 'ma100_', 'ma200_', 'psar_', 'ichimoku_', 'rsi_', 'stochastic_', 'macd_', 'willr_', 'obv_', 'vwap_', 'cmf_', 'atr_', 'stddev_', 'bollinger_', 'headshoulders_', 'doubletopbottom_', 'triangle_', 'cuphandle_', 'doji_', 'hammerhanging_', 'engulfing_', 'morningevening_', 'pivot_', 'fib_', 'trendline_', 'breakout_', 'reversal_', 'meanreversion_', 'momentum_')):
            parts = query.data.split('_')
            indicator = parts[0]
            ticker = parts[1]
            logger.info(safe_log(f"Indikator teknikal {indicator} dipilih untuk {ticker} oleh user {query.from_user.id}"))
            # ... (logika indikator teknikal tetap sama) ...

        # Tangkap callback_data yang tidak dikenali
        else:
            logger.warning(safe_log(f"Callback tidak dikenali: {query.data} dari user {query.from_user.id}"))
            await query.message.reply_text(f"Aksi {query.data} tidak dikenali.")

    except Exception as e:
        logger.error(safe_log(f"Error in button_callback: {str(e)}"))
        await query.message.reply_text(f"Terjadi kesalahan: {str(e)}")

        # Handler existing lainnya
        if query.data == 'subscription':
            await subscription(update, context)
        
        elif query.data.startswith('cb_') or query.data.startswith('cm_'):
            ticker = query.data.split('_')[1]
            new_update = Update(update_id=update.update_id, message=query.message, callback_query=None)
            context.args = [ticker]
            logger.info(safe_log(f"Tombol inline {query.data} diklik oleh user {query.from_user.id}, membuka chart"))
            await chart_stock_with_patterns(new_update, context, ticker)

        elif query.data == 'edu_start' or query.data.startswith('edu_'):
            await education_menu(update, context)
        
        elif query.data == 'back_to_menu':
            await show_main_menu(update, context)
        
        elif query.data in ['menu_utama', 'about', 'help', 'join_group']:
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text="Fitur ini sedang dikembangkan."
            )

        # Handler untuk grafik MA5 crossover dari ma5_cross
        elif query.data.startswith("show_ma5_chart_"):
            _, _, ticker, date = query.data.split("_", 3)
            logger.info(safe_log(f"Menampilkan grafik MA5/MA20 untuk {ticker} pada {date}"))
            conn = DB_CONNECTION
            query_sql = """
                SELECT Date, Close 
                FROM stocks 
                WHERE Ticker = ? 
                AND Date <= ? 
                ORDER BY Date DESC 
                LIMIT 60
            """
            df = pd.read_sql_query(query_sql, conn, params=(ticker, date))
            if len(df) < 20:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=f"Tidak cukup data untuk membuat grafik {ticker}."
                )
                return

            df = df.sort_values('Date')
            df['MA5'] = df['Close'].rolling(window=5, min_periods=5).mean()
            df['MA20'] = df['Close'].rolling(window=20, min_periods=20).mean()

            # Buat grafik
            plt.figure(figsize=(10, 6))
            plt.plot(df['Date'], df['Close'], label='Close Price')
            plt.plot(df['Date'], df['MA5'], label='MA5', linestyle='--')
            plt.plot(df['Date'], df['MA20'], label='MA20', linestyle='--')
            plt.axvline(x=date, color='r', linestyle='--', label=f'Crossover {date}')
            plt.title(f"{ticker} - MA5/MA20 Crossover")
            plt.xlabel("Tanggal")
            plt.ylabel("Harga")
            plt.legend()
            plt.xticks(rotation=45)
            plt.tight_layout()

            # Simpan ke buffer
            buf = io.BytesIO()
            plt.savefig(buf, format='png')
            buf.seek(0)
            plt.close()

            # Kirim grafik
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                photo=buf,
                caption=f"Grafik MA5/MA20 Crossover untuk {ticker} pada {date}"
            )
            buf.close()
            logger.info(safe_log(f"Grafik MA5/MA20 untuk {ticker} pada {date} berhasil dikirim"))

        # Handler untuk grafik MA umum
        elif query.data.startswith("show_ma_chart_"):
            _, _, ticker, date = query.data.split("_", 3)
            conn = DB_CONNECTION
            query_sql = """
                SELECT Date, Close 
                FROM stocks 
                WHERE Ticker = ? 
                AND Date <= ? 
                ORDER BY Date DESC 
                LIMIT 60
            """
            df = pd.read_sql_query(query_sql, conn, params=(ticker, date))
            df = df.sort_values('Date')
            
            # Hitung MA
            df['MA5'] = df['Close'].rolling(window=5, min_periods=5).mean()
            df['MA20'] = df['Close'].rolling(window=20, min_periods=20).mean()
            df['MA60'] = df['Close'].rolling(window=60, min_periods=60).mean()
            df['MA200'] = df['Close'].rolling(window=200, min_periods=60).mean()

            # Buat grafik
            plt.figure(figsize=(10, 6))
            plt.plot(df['Date'], df['Close'], label='Close Price')
            plt.plot(df['Date'], df['MA5'], label='MA5', linestyle='--')
            plt.plot(df['Date'], df['MA20'], label='MA20', linestyle='--')
            plt.plot(df['Date'], df['MA60'], label='MA60', linestyle='--')
            plt.plot(df['Date'], df['MA200'], label='MA200', linestyle='--')
            plt.title(f"{ticker} - MA Crossover")
            plt.xlabel("Tanggal")
            plt.ylabel("Harga")
            plt.legend()
            plt.xticks(rotation=45)
            chart_path = f"ma_chart_{ticker}.png"
            plt.savefig(chart_path)
            plt.close()

            # Kirim grafik
            with open(chart_path, 'rb') as chart:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    photo=chart,
                    caption=f"Grafik MA untuk {ticker} hingga {date}"
                )
            os.remove(chart_path)

        # Handler lainnya
        elif query.data == 'c':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan kode saham, contoh: /c BJBR")
        elif query.data == 'a':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan kode saham, contoh: /bar BJBR")
        elif query.data == 'signal':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan kode saham, contoh: /signal BJBR")
        elif query.data == 'predict':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan kode saham, contoh: /predict BJBR")
        elif query.data == 'fundamental':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan kode saham, contoh: /af BJBR")
        elif query.data == 'tg':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan periode, contoh: /tg harian")
        elif query.data == 'tl':
            await context.bot.send_message(chat_id=query.message.chat_id, text="Masukkan periode, contoh: /tl harian")
