                [InlineKeyboardButton("Ichimoku", callback_data=f"ichimoku_{ticker}"), InlineKeyboardButton("RSI", callback_data=f"rsi_{ticker}")],
                [InlineKeyboardButton("Stochastic", callback_data=f"stochastic_{ticker}"), InlineKeyboardButton("MACD", callback_data=f"macd_{ticker}")],
                [InlineKeyboardButton("Williams %R", callback_data=f"willr_{ticker}"), InlineKeyboardButton("OBV", callback_data=f"obv_{ticker}")],
                [InlineKeyboardButton("VWAP", callback_data=f"vwap_{ticker}"), InlineKeyboardButton("CMF", callback_data=f"cmf_{ticker}")],
