async def chart_stock_with_patterns(update: Update, context: ContextTypes.DEFAULT_TYPE, ticker):
    try:
        conn = DB_CONNECTION
        
        # Ambil days dan end_date dari context jika ada (dari perintah /candle sebelumnya)
        # Catatan: Ini asumsi bahwa context.user_data menyimpan informasi dari /candle
        days = context.user_data.get('days', 4)  # Default ke 4 jika tidak ada
        end_date_str = context.user_data.get('end_date_str', None)
        end_date = datetime.strptime(end_date_str, '%Y-%m-%d') if end_date_str else datetime.now()
        
        # Tentukan rentang chart: days yang diminta + 30 hari sebelumnya untuk konteks
        start_date = end_date - timedelta(days=days + 30)
        
        query = """
            SELECT Date, Open, Close, High, Low
            FROM stocks 
            WHERE Ticker = ? AND Date BETWEEN ? AND ? 
            ORDER BY Date ASC
        """
        df = pd.read_sql_query(query, conn, params=(ticker, start_date.strftime('%Y-%m-%d'), end_date.strftime('%Y-%m-%d')))
        

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data untuk {ticker} dalam rentang yang diminta."
            )
            return

        # Deteksi jenis candlestick
        df['Candle_Type'] = [detect_candle_type(df, i) for i in range(len(df))]

        # Buat chart dengan Plotly
        fig = go.Figure(data=[go.Candlestick(
            x=df['Date'],
            open=df['Open'],
            high=df['High'],
            low=df['Low'],
            close=df['Close'],
            name=ticker
        )])

        # Tambahkan anotasi untuk jenis candlestick
        for i, row in df.iterrows():
            if row['Candle_Type'] not in ["Bullish", "Bearish", "Unknown"]:
                fig.add_annotation(
                    x=row['Date'],
                    y=row['High'] if row['Candle_Type'] in ["Shooting Star", "Bearish Engulfing", "Evening Star"] else row['Low'],
                    text=row['Candle_Type'],
                    showarrow=True,
                    arrowhead=1,
                    ax=20 if row['Candle_Type'] in ["Shooting Star", "Bearish Engulfing", "Evening Star"] else -20,
                    ay=-20 if row['Candle_Type'] in ["Shooting Star", "Bearish Engulfing", "Evening Star"] else 20,
                    font=dict(size=10, color="black"),
                    bgcolor="yellow" if row['Candle_Type'] == "Doji" else "green" if row['Candle_Type'] in ["Hammer", "Bullish Engulfing", "Bullish Harami", "Morning Star"] else "red"
                )

        fig.update_layout(
            title=f"Candlestick Chart {ticker} (Hingga {end_date.strftime('%Y-%m-%d')})",
            yaxis_title="Harga",
            xaxis_rangeslider_visible=False
        )

        fig.write_image(f"{ticker}_chart.png")
        with open(f"{ticker}_chart.png", 'rb') as photo:
            await context.bot.send_photo(
                chat_id=update.effective_chat.id,
                photo=photo,
                caption=f"Chart {ticker} dengan pola candlestick terdeteksi hingga {end_date.strftime('%Y-%m-%d')}."
            )

    except Exception as e:
        logger.error(f"Error in chart_stock_with_patterns: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat membuat chart."
        )

# Fungsi untuk mendeteksi jenis candlestick
def detect_candle_type(df, index):
    if index < 1:  # Pola seperti Engulfing/Harami butuh data sebelumnya
        return "Unknown"
    
    current = df.iloc[index]
    previous = df.iloc[index - 1]
    
    open_price = current['Open']
    close_price = current['Close']
    high_price = current['High']
    low_price = current['Low']
    body = abs(close_price - open_price)
    range_price = high_price - low_price
    upper_shadow = high_price - max(open_price, close_price)
    lower_shadow = min(open_price, close_price) - low_price
    
    prev_open = previous['Open']
    prev_close = previous['Close']
    prev_body = abs(prev_close - prev_open)
    
    # Threshold untuk Doji
    doji_threshold = 0.005 * range_price  # 0.5% dari range
    
    # Deteksi pola satu hari
    if body <= doji_threshold:
        return "Doji"
    elif close_price > open_price:
        if lower_shadow >= 2 * body and upper_shadow <= 0.1 * body:
            return "Hammer"
        elif upper_shadow >= 2 * body and lower_shadow <= 0.1 * body:
            return "Shooting Star"
    elif close_price < open_price:
        if upper_shadow >= 2 * body and lower_shadow <= 0.1 * body:
            return "Shooting Star"
        elif lower_shadow >= 2 * body and upper_shadow <= 0.1 * body:
            return "Hammer"
    
    # Deteksi pola dua hari
    if close_price > open_price and prev_close < prev_open:  # Bullish setelah Bearish
        if body > prev_body and open_price <= prev_close and close_price >= prev_open:
            return "Bullish Engulfing"
        elif body < prev_body and open_price >= prev_close and close_price <= prev_open:
            return "Bullish Harami"
    elif close_price < open_price and prev_close > prev_open:  # Bearish setelah Bullish
        if body > prev_body and open_price >= prev_close and close_price <= prev_open:
            return "Bearish Engulfing"
        elif body < prev_body and open_price <= prev_close and close_price >= prev_open:
            return "Bearish Harami"
    
    # Deteksi pola tiga hari (Morning Star, Evening Star)
    if index >= 2:
        prev2 = df.iloc[index - 2]
        prev2_open = prev2['Open']
        prev2_close = prev2['Close']
        prev2_body = abs(prev2_close - prev2_open)
        
        if (prev2_close < prev2_open and  # Hari 1: Bearish
            abs(prev_open - prev_close) <= doji_threshold and  # Hari 2: Doji/kecil
            close_price > open_price and  # Hari 3: Bullish
            close_price > (prev2_open + prev2_close) / 2):  # Hari 3 melewati tengah hari 1
            return "Morning Star"
        elif (prev2_close > prev2_open and  # Hari 1: Bullish
              abs(prev_open - prev_close) <= doji_threshold and  # Hari 2: Doji/kecil
              close_price < open_price and  # Hari 3: Bearish
              close_price < (prev2_open + prev2_close) / 2):  # Hari 3 di bawah tengah hari 1
            return "Evening Star"
    
    # Default
    return "Bullish" if close_price > open_price else "Bearish"

