async def volatility(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if not context.args:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Masukkan kode saham, contoh: /volatility BJBR")
            return

        ticker = context.args[0].upper()
        conn = DB_CONNECTION
        
        # Ambil data saham spesifik
        query = "SELECT Date, Close FROM stocks WHERE Ticker = ? ORDER BY Date DESC LIMIT 30"
        df = pd.read_sql_query(query, conn, params=(ticker,))
        
        # Ambil data untuk volatilitas pasar (rata-rata perubahan harian semua saham)
        market_query = "SELECT Date, AVG(Close) as AvgClose FROM stocks GROUP BY Date ORDER BY Date DESC LIMIT 30"
        market_df = pd.read_sql_query(market_query, conn)
        

        if df.empty:
            await context.bot.send_message(chat_id=update.effective_chat.id, text=f"Tidak ada data untuk saham {ticker}.")
            return
        if market_df.empty:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Tidak ada data pasar untuk perbandingan.")
            return

        # Hitung volatilitas saham
        df['Returns'] = df['Close'].pct_change()
        volatility = df['Returns'].std() * np.sqrt(252)  # Annualized volatility

        # Hitung volatilitas pasar
        market_df['Returns'] = market_df['AvgClose'].pct_change()
        market_vol = market_df['Returns'].std() * np.sqrt(252)  # Annualized volatility

        message = f"Analisis Volatilitas {ticker}:\n"
        message += f"Volatilitas (30 Hari, Annualized): {volatility:.2%}\n"
        message += f"Rata-rata Volatilitas Pasar: {market_vol:.2%}\n"
        message += f"Status: {'Tinggi' if volatility > market_vol else 'Rendah'} dibandingkan pasar"
        await context.bot.send_message(chat_id=update.effective_chat.id, text=message)
        logger.info(f"Analisis volatilitas untuk {ticker} dikirim")
    except Exception as e:
        logger.error(f"Error in volatility: {str(e)}")
        await context.bot.send_message(chat_id=update.effective_chat.id, text="Terjadi kesalahan saat menghitung volatilitas.")

async def correlation_heatmap(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        if len(context.args) < 2:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Masukkan minimal 2 kode saham, contoh: /heatmap BJBR BBRI BMRI")
            return

        tickers = [ticker.upper() for ticker in context.args]
        conn = DB_CONNECTION
        dfs = []
        for ticker in tickers:
            query = "SELECT Date, Close FROM stocks WHERE Ticker = ? ORDER BY Date DESC LIMIT 30"
            df = pd.read_sql_query(query, conn, params=(ticker,))
            if not df.empty:
                df['Date'] = pd.to_datetime(df['Date'])
                df = df.set_index('Date')
                df = df.rename(columns={'Close': ticker})
                dfs.append(df[ticker])

        
        if len(dfs) < 2:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Data tidak cukup untuk heatmap.")
            return

        combined_df = pd.concat(dfs, axis=1, join='inner')
        returns_df = combined_df.pct_change().dropna()
        corr_matrix = returns_df.corr()

        plt.figure(figsize=(10, 8))
        sns.heatmap(corr_matrix, annot=True, cmap='coolwarm', vmin=-1, vmax=1, center=0)
        plt.title("Heatmap Korelasi Saham")

        chart_path = f"heatmap_{'_'.join(tickers)}.png"
        plt.savefig(chart_path)
        plt.close()

        with open(chart_path, 'rb') as photo:
            await context.bot.send_photo(chat_id=update.effective_chat.id, photo=photo)
        os.remove(chart_path)
        logger.info(f"Heatmap korelasi untuk {tickers} dikirim")
    except Exception as e:
        logger.error(f"Error in correlation_heatmap: {str(e)}")
        await context.bot.send_message(chat_id=update.effective_chat.id, text="Terjadi kesalahan saat membuat heatmap.")

