async def predict_stock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if not context.args:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Silakan masukkan kode saham, contoh: /predict BJBR [arima]")
            return

        ticker = context.args[0].upper()
        use_arima = "arima" in [arg.lower() for arg in context.args]  # Cek apakah "arima" ada di argumen

        conn = DB_CONNECTION
        
        # Ambil data teknikal (50 hari terakhir untuk efisiensi)
        query = """
            SELECT Date, Close, High, Low, Volume 
            FROM stocks 
            WHERE Ticker = ? 
            ORDER BY Date DESC 
            LIMIT 50
        """
        df = pd.read_sql_query(query, conn, params=(ticker,))

        # Ambil data fundamental
        cursor = conn.cursor()
        cursor.execute("""
            SELECT ticker, name, eps, pe_ratio, debt_to_equity, roe, last_updated 
            FROM fundamental_data 
            WHERE ticker = ?
        """, (ticker,))
        fundamental_data = cursor.fetchone()

        if df.empty:
            
            await context.bot.send_message(chat_id=update.effective_chat.id, text=f"Tidak ada data teknikal untuk saham {ticker}.")
            return

        if not fundamental_data:
            
            await context.bot.send_message(chat_id=update.effective_chat.id, text=f"Tidak ada data fundamental untuk saham {ticker}. Gunakan /update_fundamental.")
            return

        # Proses data teknikal
        df['Date'] = pd.to_datetime(df['Date'])
        df = df.sort_values(by='Date')

        # Atur indeks dengan frekuensi harian untuk mendukung ARIMA
        df.set_index('Date', inplace=True)
        # Pastikan indeks memiliki frekuensi harian (mengisi tanggal yang hilang jika ada)
        df = df.asfreq('D', method='ffill')  # Isi data yang hilang dengan metode forward fill
        latest_date = df.index[-1]
        latest_close = df['Close'].iloc[-1]

        # --- 1. Linear Regression Prediction ---
        df['Day'] = np.arange(len(df))
        X = df[['Day']].values
        y = df['Close'].values
        lin_reg = LinearRegression()
        lin_reg.fit(X, y)
        future_days = np.array([[len(df) + i] for i in range(1, 6)])
        lin_reg_pred = lin_reg.predict(future_days)
        lin_slope = lin_reg.coef_[0]
        lin_trend = "Naik" if lin_slope > 0 else "Turun" if lin_slope < 0 else "Stabil"

        # --- 2. EMA Trend Prediction ---
        ema_short = df['Close'].ewm(span=12, adjust=False).mean().iloc[-1]  # EMA 12 hari
        ema_long = df['Close'].ewm(span=26, adjust=False).mean().iloc[-1]  # EMA 26 hari
        ema_trend = "Naik" if ema_short > ema_long else "Turun" if ema_short < ema_long else "Stabil"
        ema_pred = ema_short + (ema_short - ema_long) * 0.1  # Ekstrapolasi sederhana untuk 1 hari ke depan

        # --- 3. MACD Extrapolation ---
        macd = ta.macd(df['Close'])
        macd_line = macd['MACD_12_26_9'].iloc[-1]
        signal_line = macd['MACDs_12_26_9'].iloc[-1]
        macd_hist = macd_line - signal_line
        macd_trend = "Naik" if macd_line > signal_line else "Turun" if macd_line < signal_line else "Stabil"
        macd_pred = latest_close * (1 + macd_hist * 0.01)  # Prediksi sederhana berdasarkan histogram

        # --- 4. Support and Resistance Levels ---
        high_30d = df['High'].tail(30).max()
        low_30d = df['Low'].tail(30).min()
        pivot = (high_30d + low_30d + latest_close) / 3
        support1 = (2 * pivot) - high_30d
        resistance1 = (2 * pivot) - low_30d

        # --- 5. Volatility-Based Confidence Interval ---
        volatility = df['Close'].pct_change().std() * np.sqrt(252)  # Volatilitas tahunan
        conf_interval_upper = lin_reg_pred[-1] * (1 + volatility * 0.1)  # 10% volatilitas untuk 5 hari
        conf_interval_lower = lin_reg_pred[-1] * (1 - volatility * 0.1)

        # --- 6. ARIMA Prediction (Opsional) ---
        arima_forecast = None
        arima_trend = None
        if use_arima:
            try:
                arima_model = ARIMA(df['Close'], order=(5, 1, 0))  # Order (p,d,q) bisa di-tuning lebih lanjut
                arima_result = arima_model.fit()
                arima_forecast = arima_result.forecast(steps=5)
                arima_trend = "Naik" if arima_forecast.iloc[-1] > latest_close else "Turun" if arima_forecast.iloc[-1] < latest_close else "Stabil"
            except Exception as e:
                logger.error(f"Error in ARIMA prediction for {ticker}: {str(e)}")
                arima_forecast = None
                arima_trend = "Gagal menghitung (data tidak cukup atau error)"

        # --- Analisis Fundamental ---
        ticker, name, eps, pe_ratio, debt_to_equity, roe, last_updated = fundamental_data
        fundamental_score = 0
        fundamental_reasons = []

        # Kriteria fundamental
        if eps > 0:
            fundamental_score += 1
            fundamental_reasons.append("EPS positif (mengindikasikan profitabilitas)")
        if pe_ratio > 0 and pe_ratio < 15:
            fundamental_score += 1
            fundamental_reasons.append("P/E Ratio rendah (saham undervalued)")
        if debt_to_equity is not None and debt_to_equity < 1:
            fundamental_score += 1
            fundamental_reasons.append("Debt to Equity rendah (risiko keuangan rendah)")
        if roe is not None and roe > 0.1:  # ROE > 10%
            fundamental_score += 1
            fundamental_reasons.append("ROE tinggi (efisiensi ekuitas baik)")

        # Tentukan rekomendasi fundamental
        fundamental_recommendation = "Layak Dibeli" if fundamental_score >= 3 else "Perlu Analisis Lebih Lanjut"

        # --- Skor Teknikal ---
        technical_score = 0
        if lin_trend == "Naik":
            technical_score += 1
        if ema_trend == "Naik":
            technical_score += 1
        if macd_trend == "Naik":
            technical_score += 1

        # Rekomendasi gabungan
        combined_score = technical_score + fundamental_score
        final_recommendation = "Sangat Direkomendasikan untuk Dibeli" if combined_score >= 5 else "Layak Dipertimbangkan" if combined_score >= 3 else "Tahan"

        # --- Kompilasi Hasil Prediksi ---
        message = f"Prediksi Harga Saham {ticker} (Kombinasi Teknikal & Fundamental) - Tanggal Terbaru: {latest_date}\n"
        message += f"Harga Penutupan Terbaru: {latest_close:.2f}\n\n"

        # Linear Regression
        message += f"1. Linear Regression (Tren: {lin_trend}):\n"
        for i, pred in enumerate(lin_reg_pred, 1):
            pred_date = latest_date + timedelta(days=i)
            message += f"  {pred_date.strftime('%Y-%m-%d')}: {pred:.2f}\n"
        message += f"  Confidence Interval (5 Hari): {conf_interval_lower:.2f} - {conf_interval_upper:.2f}\n\n"

        # EMA
        message += f"2. EMA Trend (Tren: {ema_trend}):\n"
        message += f"  EMA 12: {ema_short:.2f}, EMA 26: {ema_long:.2f}\n"
        message += f"  Prediksi 1 Hari: {ema_pred:.2f}\n\n"

        # MACD
        message += f"3. MACD Extrapolation (Tren: {macd_trend}):\n"
        message += f"  MACD Line: {macd_line:.2f}, Signal: {signal_line:.2f}, Histogram: {macd_hist:.2f}\n"
        message += f"  Prediksi 1 Hari: {macd_pred:.2f}\n\n"

        # Support/Resistance
        message += f"4. Level Support dan Resistance (30 Hari):\n"
        message += f"  Support 1: {support1:.2f}\n"
        message += f"  Resistance 1: {resistance1:.2f}\n"
        message += f"  Pivot Point: {pivot:.2f}\n\n"

        # ARIMA (jika diaktifkan)
        if use_arima and arima_forecast is not None:
            message += f"5. ARIMA Prediction (Tren: {arima_trend}):\n"
            for i, pred in enumerate(arima_forecast, 1):
                pred_date = latest_date + timedelta(days=i)
                message += f"  {pred_date.strftime('%Y-%m-%d')}: {pred:.2f}\n\n"
            message += f"Catatan: ARIMA diaktifkan (komputasi lebih berat).\n\n"
        elif use_arima:
            message += f"5. ARIMA Prediction: {arima_trend}\n\n"

        # Analisis Fundamental
        message += f"{'6' if use_arima else '5'}. Analisis Fundamental ({name}):\n"
        message += f"  EPS: {eps:.2f}\n"
        message += f"  P/E Ratio: {pe_ratio:.2f}\n"
        message += f"  Debt to Equity: {debt_to_equity:.2f}\n"
        message += f"  ROE: {roe:.2%}\n"
        message += f"  Alasan Fundamental:\n"
        for reason in fundamental_reasons:
            message += f"    - {reason}\n"
        message += f"  Skor Fundamental: {fundamental_score}/4\n"
        message += f"  Rekomendasi Fundamental: {fundamental_recommendation}\n\n"

        # Rekomendasi Gabungan
        message += f"{'7' if use_arima else '6'}. Rekomendasi Gabungan:\n"
        message += f"  Skor Teknikal: {technical_score}/3\n"
        message += f"  Skor Total (Teknikal + Fundamental): {combined_score}/7\n"
        message += f"  Rekomendasi Akhir: {final_recommendation}\n\n"

        # Catatan Penting
        message += "Catatan:\n"
        message += "- Prediksi ini menggabungkan analisis teknikal dan fundamental untuk rekomendasi yang lebih holistik.\n"
        message += "- Gunakan /predict <ticker> arima untuk menyertakan prediksi ARIMA (lebih lambat).\n"
        message += "- Gunakan dengan analisis Anda sendiri sebelum mengambil keputusan trading."

        await context.bot.send_message(chat_id=update.effective_chat.id, text=message)
        logger.info(f"Prediksi multi-metode untuk {ticker} dikirim (ARIMA: {use_arima})")

        

    except Exception as e:
        logger.error(f"Error in predict_stock: {str(e)}")
        await context.bot.send_message(chat_id=update.effective_chat.id, text="Terjadi kesalahan saat membuat prediksi. Silakan coba lagi nanti.")        

import asyncio
import logging
import io
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from datetime import timedelta
from sklearn.linear_model import LinearRegression
from xgboost import XGBRegressor
try:
    from arch import arch_model
    ARCH_AVAILABLE = True
except ImportError:
    ARCH_AVAILABLE = False
from ta.trend import macd
from vaderSentiment.vaderSentiment import SentimentIntensityAnalyzer
from statsmodels.tsa.arima.model import ARIMA
from telegram import Update
from telegram.ext import ContextTypes

# Logger setup
logger = logging.getLogger(__name__)

async def predict_saham (update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna (fungsi check_user_access diasumsikan sudah ada)
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    
    try:
        # Validasi input
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Silakan masukkan kode saham, contoh: /predict BJBR [arima] [xgboost]",
                parse_mode='Markdown'
            )
            return

        ticker = context.args[0].upper()
        use_arima = "arima" in [arg.lower() for arg in context.args]
        use_xgboost = "xgboost" in [arg.lower() for arg in context.args]

        # Koneksi ke database (diasumsikan DB_CONNECTION sudah didefinisikan)
        conn = DB_CONNECTION
        
        # Ambil data teknikal (200 hari untuk model lebih kuat)
        query = """
            SELECT Date, Close, High, Low, Volume 
            FROM stocks 
            WHERE Ticker = ? 
            ORDER BY Date DESC 
            LIMIT 200
        """
        df = pd.read_sql_query(query, conn, params=(ticker,))

        # Ambil data fundamental
        cursor = conn.cursor()
        cursor.execute("""
            SELECT ticker, name, eps, pe_ratio, debt_to_equity, roe, last_updated 
            FROM fundamental_data 
            WHERE ticker = ?
        """, (ticker,))
        fundamental_data = cursor.fetchone()

        # Validasi data
        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"❌ Tidak ada data teknikal untuk saham *{ticker}*.",
                parse_mode='Markdown'
            )
            return

        if not fundamental_data:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"❌ Tidak ada data fundamental untuk saham *{ticker}*. Gunakan /update_fundamental.",
                parse_mode='Markdown'
            )
            return

        # Proses data teknikal
        df['Date'] = pd.to_datetime(df['Date'])
        df = df.sort_values(by='Date')
        df.set_index('Date', inplace=True)
        df = df.asfreq('D', method='ffill')  # Isi data hilang dengan forward fill
        latest_date = df.index[-1]
        latest_close = df['Close'].iloc[-1]

        # --- 1. Linear Regression Prediction ---
        df['Day'] = np.arange(len(df))
        X = df[['Day']].values
        y = df['Close'].values
        lin_reg = LinearRegression()
        lin_reg.fit(X, y)
        future_days = np.array([[len(df) + i] for i in range(1, 6)])
        lin_reg_pred = lin_reg.predict(future_days)
        lin_slope = lin_reg.coef_[0]
        lin_trend = "📈 Naik" if lin_slope > 0 else "📉 Turun" if lin_slope < 0 else "➡️ Stabil"

        # --- 2. EMA Trend Prediction ---
        ema_short = df['Close'].ewm(span=12, adjust=False).mean().iloc[-1]
        ema_long = df['Close'].ewm(span=26, adjust=False).mean().iloc[-1]
        ema_trend = "📈 Naik" if ema_short > ema_long else "📉 Turun" if ema_short < ema_long else "➡️ Stabil"
        ema_pred = ema_short + (ema_short - ema_long) * 0.1  # Ekstrapolasi sederhana

        # --- 3. MACD Extrapolation ---
        try:
            macd_data = macd(df['Close'], window_slow=26, window_fast=12, window_signal=9)
            macd_line = macd_data['MACD_12_26_9'].iloc[-1]
            signal_line = macd_data['MACDs_12_26_9'].iloc[-1]
            macd_hist = macd_line - signal_line
            macd_trend = "📈 Naik" if macd_line > signal_line else "📉 Turun" if macd_line < signal_line else "➡️ Stabil"
            macd_pred = latest_close * (1 + macd_hist * 0.01)
        except Exception as e:
            logger.error(f"Error in MACD calculation for {ticker}: {str(e)}")
            macd_line = signal_line = macd_hist = macd_pred = 0.0
            macd_trend = "Gagal menghitung MACD"
            macd_data = pd.DataFrame({'MACDh_12_26_9': [0] * len(df[-30:])})  # Fallback untuk grafik

        # --- 4. Support and Resistance Levels ---
        high_30d = df['High'].tail(30).max()
        low_30d = df['Low'].tail(30).min()
        pivot = (high_30d + low_30d + latest_close) / 3
        support1 = (2 * pivot) - high_30d
        resistance1 = (2 * pivot) - low_30d

        # --- 5. Volatility Calculation (GARCH or Fallback) ---
        volatility_message = ""
        if ARCH_AVAILABLE:
            try:
                garch_model = arch_model(df['Close'].pct_change().dropna(), vol='Garch', p=1, q=1)
                garch_res = garch_model.fit(disp='off')
                volatility = garch_res.conditional_volatility.iloc[-1] * np.sqrt(252)
                volatility_message = "Volatilitas dihitung menggunakan GARCH."
            except Exception as e:
                logger.error(f"Error in GARCH calculation for {ticker}: {str(e)}")
                volatility = df['Close'].pct_change().std() * np.sqrt(252)  # Fallback
                volatility_message = "Volatilitas dihitung menggunakan standar deviasi (GARCH gagal)."
        else:
            volatility = df['Close'].pct_change().std() * np.sqrt(252)  # Fallback
            volatility_message = "Volatilitas dihitung menggunakan standar deviasi (paket 'arch' tidak terinstal)."
        
        conf_interval_upper = lin_reg_pred[-1] * (1 + volatility * 0.1)
        conf_interval_lower = lin_reg_pred[-1] * (1 - volatility * 0.1)

        # --- 6. XGBoost Prediction ---
        xgb_pred = None
        xgb_trend = None
        if use_xgboost:
            df['Lag1'] = df['Close'].shift(1)
            df['Lag2'] = df['Close'].shift(2)
            df['EMA12'] = df['Close'].ewm(span=12).mean()
            df.dropna(inplace=True)
            
            X = df[['Lag1', 'Lag2', 'EMA12', 'Volume', 'High', 'Low']]
            y = df['Close']
            
            xgb_model = XGBRegressor(objective='reg:squarederror', n_estimators=100)
            xgb_model.fit(X, y)
            
            future_inputs = []
            last_row = df.iloc[-1]
            for i in range(5):
                new_input = [last_row['Close'], last_row['Lag1'], last_row['EMA12'], last_row['Volume'], last_row['High'], last_row['Low']]
                pred = xgb_model.predict([new_input])[0]
                future_inputs.append(pred)
                last_row = pd.Series({
                    'Close': pred,
                    'Lag1': last_row['Close'],
                    'Lag2': last_row['Lag1'],
                    'EMA12': (last_row['EMA12'] * 11 + pred) / 12,
                    'Volume': last_row['Volume'],
                    'High': pred * 1.01,
                    'Low': pred * 0.99
                })
            
            xgb_pred = future_inputs
            xgb_trend = "📈 Naik" if xgb_pred[-1] > latest_close else "📉 Turun" if xgb_pred[-1] < latest_close else "➡️ Stabil"

        # --- 7. ARIMA Prediction ---
        arima_forecast = None
        arima_trend = None
        if use_arima:
            try:
                arima_model = ARIMA(df['Close'], order=(5, 1, 0))
                arima_result = arima_model.fit()
                arima_forecast = arima_result.forecast(steps=5)
                arima_trend = "📈 Naik" if arima_forecast.iloc[-1] > latest_close else "📉 Turun" if arima_forecast.iloc[-1] < latest_close else "➡️ Stabil"
            except Exception as e:
                logger.error(f"Error in ARIMA prediction for {ticker}: {str(e)}")
                arima_forecast = None
                arima_trend = "Gagal menghitung (data tidak cukup atau error)"

        # --- 8. Analisis Sentimen (Dummy) ---
        analyzer = SentimentIntensityAnalyzer()
        sentimen_score = analyzer.polarity_scores(f"Berita positif tentang saham {ticker}.")['compound']  # Ganti dengan API X/web
        sentimen_trend = "😊 Positif" if sentimen_score > 0 else "😔 Negatif" if sentimen_score < 0 else "😐 Netral"

        # --- 9. Analisis Fundamental ---
        ticker, name, eps, pe_ratio, debt_to_equity, roe, last_updated = fundamental_data
        fundamental_score = 0
        fundamental_reasons = []

        if eps > 0:
            fundamental_score += 1
            fundamental_reasons.append("EPS positif (mengindikasikan profitabilitas)")
        if pe_ratio > 0 and pe_ratio < 15:
            fundamental_score += 1
            fundamental_reasons.append("P/E Ratio rendah (saham undervalued)")
        if debt_to_equity is not None and debt_to_equity < 1:
            fundamental_score += 1
            fundamental_reasons.append("Debt to Equity rendah (risiko keuangan rendah)")
        if roe is not None and roe > 0.1:
            fundamental_score += 1
            fundamental_reasons.append("ROE tinggi (efisiensi ekuitas baik)")

        fundamental_recommendation = "✅ Layak Dibeli" if fundamental_score >= 3 else "⚠️ Perlu Analisis Lebih Lanjut"

        # --- 10. Skor Teknikal ---
        technical_score = 0
        if "Naik" in lin_trend:
            technical_score += 1
        if "Naik" in ema_trend:
            technical_score += 1
        if "Naik" in macd_trend:
            technical_score += 1
        if use_xgboost and "Naik" in xgb_trend:
            technical_score += 1
        if use_arima and arima_forecast is not None and "Naik" in arima_trend:
            technical_score += 1
        if "Positif" in sentimen_trend:
            technical_score += 1

        # Rekomendasi gabungan
        combined_score = technical_score + fundamental_score
        final_recommendation = "⭐ Sangat Direkomendasikan untuk Dibeli" if combined_score >= 5 else "✅ Layak Dipertimbangkan" if combined_score >= 3 else "⛔ Tahan"

        # --- 11. Kompilasi Hasil Prediksi ---
        message = f"📊 *Prediksi Harga Saham {ticker}* (Kombinasi Teknikal & Fundamental) - Tanggal: *{latest_date.strftime('%Y-%m-%d')}*\n"
        message += f"💰 *Harga Penutupan Terbaru*: {latest_close:.2f}\n\n"

        # Linear Regression
        message += f"*1. Linear Regression* (Tren: {lin_trend}):\n"
        for i, pred in enumerate(lin_reg_pred, 1):
            pred_date = latest_date + timedelta(days=i)
            message += f"  {pred_date.strftime('%Y-%m-%d')}: *{pred:.2f}*\n"
        message += f"  Confidence Interval (5 Hari): *{conf_interval_lower:.2f} - {conf_interval_upper:.2f}*\n"
        message += f"  {volatility_message}\n\n"

        # EMA
        message += f"*2. EMA Trend* (Tren: {ema_trend}):\n"
        message += f"  EMA 12: *{ema_short:.2f}*, EMA 26: *{ema_long:.2f}*\n"
        message += f"  Prediksi 1 Hari: *{ema_pred:.2f}*\n\n"

        # MACD
        message += f"*3. MACD Extrapolation* (Tren: {macd_trend}):\n"
        message += f"  MACD Line: *{macd_line:.2f}*, Signal: *{signal_line:.2f}*, Histogram: *{macd_hist:.2f}*\n"
        message += f"  Prediksi 1 Hari: *{macd_pred:.2f}*\n\n"

        # Support/Resistance
        message += f"*4. Level Support dan Resistance* (30 Hari):\n"
        message += f"  Support 1: *{support1:.2f}*\n"
        message += f"  Resistance 1: *{resistance1:.2f}*\n"
        message += f"  Pivot Point: *{pivot:.2f}*\n\n"

        # XGBoost
        if use_xgboost:
            message += f"*5. XGBoost Prediction* (Tren: {xgb_trend}):\n"
            for i, pred in enumerate(xgb_pred, 1):
                pred_date = latest_date + timedelta(days=i)
                message += f"  {pred_date.strftime('%Y-%m-%d')}: *{pred:.2f}*\n"
            message += f"Catatan: XGBoost diaktifkan (menggunakan fitur non-linier).\n\n"

        # ARIMA
        if use_arima and arima_forecast is not None:
            message += f"*{6 if use_xgboost else 5}. ARIMA Prediction* (Tren: {arima_trend}):\n"
            for i, pred in enumerate(arima_forecast, 1):
                pred_date = latest_date + timedelta(days=i)
                message += f"  {pred_date.strftime('%Y-%m-%d')}: *{pred:.2f}*\n"
            message += f"Catatan: ARIMA diaktifkan (komputasi lebih berat).\n\n"
        elif use_arima:
            message += f"*{6 if use_xgboost else 5}. ARIMA Prediction*: {arima_trend}\n\n"

        # Sentimen
        message += f"*{7 if use_xgboost and use_arima else 6 if use_xgboost or use_arima else 5}. Analisis Sentimen*:\n"
        message += f"  Sentimen Pasar: *{sentimen_trend}* (Skor: {sentimen_score:.2f})\n\n"

        # Fundamental
        message += f"*{8 if use_xgboost and use_arima else 7 if use_xgboost or use_arima else 6}. Analisis Fundamental* ({name}):\n"
        message += f"  EPS: *{eps:.2f}*\n"
        message += f"  P/E Ratio: *{pe_ratio:.2f}*\n"
        message += f"  Debt to Equity: *{debt_to_equity:.2f}*\n"
        message += f"  ROE: *{roe:.2%}*\n"
        message += f"  Alasan Fundamental:\n"
        for reason in fundamental_reasons:
            message += f"    - {reason}\n"
        message += f"  Skor Fundamental: *{fundamental_score}/4*\n"
        message += f"  Rekomendasi Fundamental: *{fundamental_recommendation}*\n\n"

        # Rekomendasi Gabungan
        message += f"*{9 if use_xgboost and use_arima else 8 if use_xgboost or use_arima else 7}. Rekomendasi Gabungan*:\n"
        message += f"  Skor Teknikal: *{technical_score}/{'6' if use_xgboost and use_arima else '5' if use_xgboost or use_arima else '4'}*\n"
        message += f"  Skor Total (Teknikal + Fundamental): *{combined_score}/{'10' if use_xgboost and use_arima else '9' if use_xgboost or use_arima else '8'}*\n"
        message += f"  *Rekomendasi Akhir*: {final_recommendation}\n\n"

        # Catatan
        message += f"*Catatan*:\n"
        message += "- Prediksi ini menggabungkan analisis teknikal, fundamental, dan sentimen.\n"
        message += "- Gunakan `/predict <ticker> arima xgboost` untuk model tambahan.\n"
        message += "- 📊 Grafik terlampir untuk visualisasi.\n"
        message += "- ⚠️ *Disclaimer*: Ini bukan saran investasi. Gunakan analisis Anda sendiri."

        # --- 12. Visualisasi Grafik ---
        sns.set_style("whitegrid")  # Tema lebih bersih
        # Plot 1: Harga Historis + Prediksi
        plt.figure(figsize=(10, 6))
        plt.plot(df.index[-30:], df['Close'].tail(30), label='Harga Aktual', color='blue')
        plt.plot([latest_date + timedelta(days=i) for i in range(1, 6)], lin_reg_pred, label='Prediksi Linear', color='green', linestyle='--')
        if use_arima and arima_forecast is not None:
            plt.plot([latest_date + timedelta(days=i) for i in range(1, 6)], arima_forecast, label='Prediksi ARIMA', color='red', linestyle='--')
        if use_xgboost:
            plt.plot([latest_date + timedelta(days=i) for i in range(1, 6)], xgb_pred, label='Prediksi XGBoost', color='purple', linestyle='--')
        plt.title(f'Prediksi Harga Saham {ticker}')
        plt.xlabel('Tanggal')
        plt.ylabel('Harga Close')
        plt.legend()
        plt.xticks(rotation=45)
        buf = io.BytesIO()
        plt.savefig(buf, format='png', bbox_inches='tight')
        buf.seek(0)
        await context.bot.send_photo(chat_id=update.effective_chat.id, photo=buf, caption=f"📈 Grafik Prediksi {ticker}")
        plt.close()

        # Plot 2: MACD Histogram
        plt.figure(figsize=(10, 4))
        plt.bar(df.index[-30:], macd_data['MACDh_12_26_9'].tail(30), label='MACD Histogram', color='gray')
        plt.axhline(0, color='black', linestyle='--', linewidth=0.5)
        plt.title(f'MACD Histogram {ticker} (30 Hari Terakhir)')
        plt.xlabel('Tanggal')
        plt.ylabel('MACD Histogram')
        plt.legend()
        plt.xticks(rotation=45)
        buf = io.BytesIO()
        plt.savefig(buf, format='png', bbox_inches='tight')
        buf.seek(0)
        await context.bot.send_photo(chat_id=update.effective_chat.id, photo=buf, caption="📊 MACD Histogram")
        plt.close()

        # Kirim pesan
        await context.bot.send_message(chat_id=update.effective_chat.id, text=message, parse_mode='Markdown')
        logger.info(f"Prediksi multi-metode untuk {ticker} dikirim (ARIMA: {use_arima}, XGBoost: {use_xgboost})")

    except Exception as e:
        logger.error(f"Error in predict_saham: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="❌ Terjadi kesalahan saat membuat prediksi. Silakan coba lagi nanti.",
            parse_mode='Markdown'
        )

