        message += f"*{15 if use_xgboost and use_arima and use_lstm and use_randomforest else 14 if (use_xgboost and use_arima and use_lstm) or (use_xgboost and use_arima and use_randomforest) or (use_xgboost and use_lstm and use_randomforest) or (use_arima and use_lstm and use_randomforest) else 13 if (use_xgboost and use_arima) or (use_xgboost and use_lstm) or (use_xgboost and use_randomforest) or (use_arima and use_lstm) or (use_arima and use_randomforest) or (use_lstm and use_randomforest) else 12 if use_xgboost or use_arima or use_lstm or use_randomforest else 11}. Backtesting*:\n"
        message += f"  {backtest_message}\n\n"

        # Rekomendasi Gabungan
        message += f"*{16 if use_xgboost and use_arima and use_lstm and use_randomforest else 15 if (use_xgboost and use_arima and use_lstm) or (use_xgboost and use_arima and use_randomforest) or (use_xgboost and use_lstm and use_randomforest) or (use_arima and use_lstm and use_randomforest) else 14 if (use_xgboost and use_arima) or (use_xgboost and use_lstm) or (use_xgboost and use_randomforest) or (use_arima and use_lstm) or (use_arima and use_randomforest) or (use_lstm and use_randomforest) else 13 if use_xgboost or use_arima or use_lstm or use_randomforest else 12}. Rekomendasi Gabungan*:\n"
