        message += f"  Skor Total (Teknikal + Fundamental): *{combined_score}/{'15' if use_xgboost and use_arima and use_lstm and use_randomforest else '14' if (use_xgboost and use_arima and use_lstm) or (use_xgboost and use_arima and use_randomforest) or (use_xgboost and use_lstm and use_randomforest) or (use_arima and use_lstm and use_randomforest) else '13' if (use_xgboost and use_arima) or (use_xgboost and use_lstm) or (use_xgboost and use_randomforest) or (use_arima and use_lstm) or (use_arima and use_randomforest) or (use_lstm and use_randomforest) else '12' if use_xgboost or use_arima or use_lstm or use_randomforest else '11'}*\n"
        message += f"  *Rekomendasi Akhir*: {final_recommendation}\n\n"

        # Catatan
