        fig_macd.add_shape(type='line', x0=df.index[-30:][0], y0=0, x1=df.index[-1], y1=0, line=dict(color='black', dash='dash', width=0.5))
        fig_macd.update_layout(title=f'MACD Histogram {ticker} (30 Hari Terakhir)', xaxis_title='Tanggal', yaxis_title='MACD Histogram', template='plotly_white')
