import pandas as pd
import numpy as np
from sklearn.cluster import KMeans, DBSCAN
from tslearn.clustering import TimeSeriesKMeans
from sklearn.preprocessing import MinMaxScaler
from sklearn.metrics import mean_squared_error, mean_absolute_error
import matplotlib.pyplot as plt
from io import BytesIO
import logging

async def jurnal1(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not await check_user_access(update, context):
        return

    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Silakan masukkan kode saham, contoh: /predict AALI [xgboost] [lstm] [randomforest]",
                parse_mode='Markdown'
            )
            return

        ticker = context.args[0].upper()
        use_xgboost = "xgboost" in [arg.lower() for arg in context.args]
        use_lstm = "lstm" in [arg.lower() for arg in context.args]
        use_randomforest = "randomforest" in [arg.lower() for arg in context.args]

        conn = DB_CONNECTION
        query = """
            SELECT Date, Close, High, Low, Volume 
            FROM stocks 
            WHERE Ticker = ? 
            ORDER BY Date DESC 
            LIMIT 120
        """
        df = pd.read_sql_query(query, conn, params=(ticker,))
        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"❌ Tidak ada data teknikal untuk saham *{ticker}*.",
                parse_mode='Markdown'
            )
            return

        df['Date'] = pd.to_datetime(df['Date'])
        df = df.sort_values(by='Date')
        df.set_index('Date', inplace=True)
        df = df.asfreq('D', method='ffill')  # Isi data hilang
        latest_date = df.index[-1]
        latest_close = df['Close'].iloc[-1]

        # Fitur teknikal untuk clustering
        df['Return'] = df['Close'].pct_change().shift(1)
        df['RSI'] = df['Close'].pct_change().rolling(14).apply(
            lambda x: ((x[x > 0].sum() / 14) / (abs(x[x < 0].sum()) / 14)) * 100 if abs(x[x < 0].sum()) > 0 else 100
        )
        df['EMA12'] = df['Close'].ewm(span=12).mean()
        df.dropna(inplace=True)

        # Peringatan jika data kurang optimal
        if len(df) < 200:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"⚠️ Data hanya {len(df)} hari. Idealnya 200+ hari untuk clustering penuh. Hasil mungkin terbatas.",
                parse_mode='Markdown'
            )

        # Clustering
        scaler = MinMaxScaler()
        features = scaler.fit_transform(df[['Return', 'RSI', 'EMA12']].values)
        
        # DTW Clustering
        model_dtw = TimeSeriesKMeans(n_clusters=3, metric="dtw", max_iter=10, random_state=42)
        clusters_dtw = model_dtw.fit_predict(features)
        
        # K-Means Clustering
        model_kmeans = KMeans(n_clusters=3, random_state=42)
        clusters_kmeans = model_kmeans.fit_predict(features)
        
        # DBSCAN Clustering
        model_dbscan = DBSCAN(eps=0.5, min_samples=4)
        clusters_dbscan = model_dbscan.fit_predict(features)

        # Data Representatif per Cluster
        def get_representative_data(cluster_labels, data):
            rep_data = []
            for cluster in np.unique(cluster_labels):
                if cluster != -1:  # Hindari noise di DBSCAN
                    cluster_data = data[cluster_labels == cluster]
                    rep_data.append(np.mean(cluster_data, axis=0))
            return np.array(rep_data) if rep_data else data[-len(cluster_labels):]  # Fallback jika kosong

        rep_dtw = get_representative_data(clusters_dtw, features)
        rep_kmeans = get_representative_data(clusters_kmeans, features)
        rep_dbscan = get_representative_data(clusters_dbscan, features)

        # Prediksi dengan Model
        models = {}
        if use_xgboost:
            from xgboost import XGBRegressor
            models['xgboost'] = XGBRegressor(n_estimators=100)
        if use_lstm and TENSORFLOW_AVAILABLE:
            from tensorflow.keras.models import Sequential
            from tensorflow.keras.layers import LSTM, Dense
            models['lstm'] = Sequential([LSTM(50, input_shape=(1, 3)), Dense(1)])
            models['lstm'].compile(optimizer='adam', loss='mse')
        if use_randomforest:
            from sklearn.ensemble import RandomForestRegressor
            models['randomforest'] = RandomForestRegressor(n_estimators=100)

        # Backtesting untuk hitung MSE/MAE
        backtest_days = min(30, len(df) // 4)  # 25% dari data untuk testing
        actual = df['Close'][-backtest_days:].values
        predictions = {}
        for cluster_method, rep_data in [('dtw', rep_dtw), ('kmeans', rep_kmeans), ('dbscan', rep_dbscan), ('none', features[-backtest_days:])]:
            for model_name, model in models.items():
                if model_name == 'lstm':
                    X_train = rep_data.reshape((rep_data.shape[0], 1, rep_data.shape[1]))
                    model.fit(X_train, np.zeros((rep_data.shape[0], 1)), epochs=5, verbose=0)
                    pred = model.predict(X_train[-backtest_days:].reshape((backtest_days, 1, 3)))
                else:
                    model.fit(rep_data[-backtest_days:], df['Close'][-backtest_days-1:-1])
                    pred = model.predict(rep_data[-backtest_days:])
                mse = mean_squared_error(actual, pred[:backtest_days])
                mae = mean_absolute_error(actual, pred[:backtest_days])
                predictions[f"{cluster_method}_{model_name}"] = {'mse': mse, 'mae': mae}

        # Spider Plot
        labels = [k for k in predictions.keys()]
        mse_values = [predictions[k]['mse'] for k in labels]
        mae_values = [predictions[k]['mae'] for k in labels]

        fig, (ax1, ax2) = plt.subplots(1, 2, subplot_kw=dict(polar=True), figsize=(12, 6))
        
        N = len(labels)
        angles = [n / float(N) * 2 * np.pi for n in range(N)]
        angles += angles[:1]

        # MSE Plot
        ax1.set_title('MSE')
        values_mse = mse_values + [mse_values[0]]
        ax1.plot(angles, values_mse, linewidth=2)
        ax1.fill(angles, values_mse, alpha=0.25)
        ax1.set_xticks(angles[:-1])
        ax1.set_xticklabels(labels, rotation=45, ha='right')
        ax1.set_ylim(0, max(mse_values) * 1.1)

        # MAE Plot
        ax2.set_title('MAE')
        values_mae = mae_values + [mae_values[0]]
        ax2.plot(angles, values_mae, linewidth=2)
        ax2.fill(angles, values_mae, alpha=0.25)
        ax2.set_xticks(angles[:-1])
        ax2.set_xticklabels(labels, rotation=45, ha='right')
        ax2.set_ylim(0, max(mae_values) * 1.1)

        plt.tight_layout()
        buf = BytesIO()
        plt.savefig(buf, format='png')
        buf.seek(0)
        await context.bot.send_photo(chat_id=update.effective_chat.id, photo=buf, caption="📊 Spider Plot MSE dan MAE")

        # Lanjutkan dengan bagian prediksi lain di script Anda...

    except Exception as e:
        logger.error(f"Error in jurnal1: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="❌ Terjadi kesalahan saat membuat prediksi. Silakan coba lagi nanti.",
            parse_mode='Markdown'
        )


