async def signal(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if not context.args:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Silakan masukkan kode saham, contoh: /signal BJBR")
            return

        ticker = context.args[0].upper()
        conn = DB_CONNECTION
        query = "SELECT Date, Close, High, Low FROM stocks WHERE Ticker = ? ORDER BY Date DESC LIMIT 50"
        df = pd.read_sql_query(query, conn, params=(ticker,))
        

        if df.empty:
            await context.bot.send_message(chat_id=update.effective_chat.id, text=f"Tidak ada data untuk saham {ticker}.")
            return

        df['Date'] = pd.to_datetime(df['Date'])
        df = df.sort_values(by='Date')

        # Hitung indikator
        df['RSI'] = ta.rsi(df['Close'], length=14)
        macd = ta.macd(df['Close'])
        df['MACD'] = macd['MACD_12_26_9']
        df['Signal'] = macd['MACDs_12_26_9']
        stoch = ta.stoch(df['High'], df['Low'], df['Close'])
        df['Stoch_K'] = stoch['STOCHk_14_3_3']

        # Ambil nilai terbaru
        rsi = df['RSI'].iloc[-1] if not pd.isna(df['RSI'].iloc[-1]) else 0
        macd_line = df['MACD'].iloc[-1] if not pd.isna(df['MACD'].iloc[-1]) else 0
        signal_line = df['Signal'].iloc[-1] if not pd.isna(df['Signal'].iloc[-1]) else 0
        stoch_k = df['Stoch_K'].iloc[-1] if not pd.isna(df['Stoch_K'].iloc[-1]) else 0

        # Logika sinyal
        buy_signals = 0
        sell_signals = 0

        if rsi < 30:
            buy_signals += 1
        elif rsi > 70:
            sell_signals += 1

        if macd_line > signal_line:
            buy_signals += 1
        elif macd_line < signal_line:
            sell_signals += 1

        if stoch_k < 20:
            buy_signals += 1
        elif stoch_k > 80:
            sell_signals += 1

        # Tentukan rekomendasi
        if buy_signals >= 2:
            recommendation = "Beli (Potensi Kenaikan)"
        elif sell_signals >= 2:
            recommendation = "Jual (Potensi Penurunan)"
        else:
            recommendation = "Tahan (Netral)"

        message = f"Sinyal Trading {ticker}:\n"
        message += f"RSI: {rsi:.2f}\n"
        message += f"MACD: Line: {macd_line:.2f}, Signal: {signal_line:.2f}\n"
        message += f"Stochastic %K: {stoch_k:.2f}\n"
        message += f"Rekomendasi: {recommendation}\n"
        message += f"Tanggal: {df['Date'].iloc[-1]}"
        await context.bot.send_message(chat_id=update.effective_chat.id, text=message)
        logger.info(f"Sinyal trading untuk {ticker} dikirim")
    except Exception as e:
        logger.error(f"Error in signal: {str(e)}")
        await context.bot.send_message(chat_id=update.effective_chat.id, text="Terjadi kesalahan saat menghitung sinyal. Silakan coba lagi nanti.")

