async def news(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan kode saham, contoh: /news ESSA"
            )
            return
        
        ticker = context.args[0].upper()
        company_name = KOMPAS100_STOCKS.get(ticker, LQ45_STOCKS.get(ticker, JII70_STOCKS.get(ticker, "Nama tidak tersedia")))
        
        # Cek berita di database
        conn = DB_CONNECTION
        cursor = conn.cursor()
        cursor.execute("SELECT title, url, published_date, source, last_updated FROM news WHERE ticker = ?", (ticker,))
        news_data = cursor.fetchall()
        
        # Jika berita tidak ada atau sudah kadaluarsa (lebih dari 1 hari), perbarui
        if not news_data or (news_data and (datetime.now() - datetime.strptime(news_data[0][4], "%Y-%m-%d %H:%M:%S")) > timedelta(days=1)):
            await update_news_for_ticker(ticker, company_name)
            cursor.execute("SELECT title, url, published_date, source, last_updated FROM news WHERE ticker = ?", (ticker,))
            news_data = cursor.fetchall()
        
        if not news_data:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada berita terkait untuk {ticker} saat ini."
            )
            return
        
        message = f"📰 *Berita Terkait {ticker} - {company_name}:*\n\n"
        for news in news_data:
            title, url, published_date, source, _ = news
            message += f"**{title}**\n"
            message += f"Sumber: {source}\n"
            message += f"Terbit: {published_date}\n"
            message += f"Link: {url}\n\n"
        
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            parse_mode="Markdown",
            disable_web_page_preview=True
        )
        logger.info(f"Berita untuk {ticker} dikirim")
    
    except Exception as e:
        logger.error(f"Error in news: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mengambil berita."
        )

