async def top_losers(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak

    try:
        # Koneksi database (diasumsikan DB_CONNECTION adalah sqlite3.Connection)
        conn = DB_CONNECTION

        # Tentukan periode atau tanggal
        period = context.args[0].lower() if context.args else "harian"

        # Periksa apakah argumen adalah tanggal (YYYY-MM-DD)
        try:
            datetime.strptime(period, "%Y-%m-%d")
            is_date = True
        except ValueError:
            is_date = False

        if is_date:
            selected_date = period
            # Query untuk mengambil data saham pada tanggal tertentu
            query = """
                SELECT Date, Ticker, CompanyName, Close, Open
                FROM stocks
                WHERE Date = ?
                AND Close IS NOT NULL AND Open IS NOT NULL
            """
            logger.debug(f"Executing query: {query} with params: {selected_date}")
            df = pd.read_sql_query(query, conn, params=(selected_date,))

            if df.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data saham untuk tanggal {selected_date}."
                )
                return

            # Hitung perubahan harga: ((Close - Open) / Open * 100)
            df['Change'] = (df['Close'] - df['Open']) / df['Open'] * 100
            df_pivot = df[['Ticker', 'CompanyName', 'Change']].set_index('Ticker')
            df_pivot = df_pivot.dropna(subset=['Change'])
            df_pivot = df_pivot.sort_values(by='Change', ascending=True).head(30)

            if df_pivot.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data yang cukup untuk menghitung perubahan harga pada tanggal {selected_date}."
                )
                return

            # Buat pesan dan tombol inline
            message = f"📉 *Top Losers ({selected_date})*:\n\n"
            keyboard = []
            for ticker, row in df_pivot.iterrows():
                message += f"{ticker} ({row['CompanyName']}): {row['Change']:.2f}%\n"
                keyboard.append([InlineKeyboardButton(f"{ticker} - {row['Change']:.2f}%", callback_data=f"tl_{ticker}")])

            keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
            reply_markup = InlineKeyboardMarkup(keyboard)

        else:
            # Logika asli untuk periode harian, mingguan, atau angka
            if period == "harian":
                days = 2
            elif period == "mingguan":
                days = 5
            else:
                try:
                    days = int(period)
                    if days < 2:
                        raise ValueError("Periode harus minimal 2 hari.")
                except ValueError:
                    await context.bot.send_message(
                        chat_id=update.effective_chat.id,
                        text="Periode tidak valid. Gunakan 'harian', 'mingguan', atau angka (misal: /tl 3)."
                    )
                    return

            # Ambil tanggal unik dari database
            query_dates = "SELECT DISTINCT Date FROM stocks ORDER BY Date DESC LIMIT ?"
            dates = pd.read_sql_query(query_dates, conn, params=(days,))['Date'].tolist()

            if len(dates) < days:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Data tidak cukup untuk analisis. Diperlukan data minimal {days} hari."
                )
                return

            start_date, end_date = dates[-1], dates[0]
            query = f"""
                SELECT Date, Ticker, CompanyName, Close 
                FROM stocks 
                WHERE Date IN ({','.join(['?']*len(dates))})
                AND Close IS NOT NULL
            """
            df = pd.read_sql_query(query, conn, params=dates)

            if df.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data saham untuk periode {period}."
                )
                return

            df_pivot = df.pivot(index='Ticker', columns='Date', values='Close')
            df_pivot['CompanyName'] = df.groupby('Ticker')['CompanyName'].first()
            df_pivot['Change'] = (df_pivot[end_date] - df_pivot[start_date]) / df_pivot[start_date] * 100
            df_pivot = df_pivot.dropna(subset=['Change'])
            df_pivot = df_pivot.sort_values(by='Change', ascending=True).head(30)

            if df_pivot.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Tidak ada data yang cukup untuk menghitung perubahan harga."
                )
                return

            # Buat pesan dan tombol inline
            message = f"📉 *Top Losers ({period})*:\n\n"
            keyboard = []
            for ticker, row in df_pivot.iterrows():
                message += f"{ticker} ({row['CompanyName']}): {row['Change']:.2f}%\n"
                keyboard.append([InlineKeyboardButton(f"{ticker} - {row['Change']:.2f}%", callback_data=f"tl_{ticker}")])

            keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
            reply_markup = InlineKeyboardMarkup(keyboard)

        # Kirim pesan
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            reply_markup=reply_markup,
            parse_mode="Markdown"
        )
        logger.info(f"Top Losers untuk {'tanggal ' + selected_date if is_date else 'periode ' + period} dikirim dengan tombol inline")

    except Exception as e:
        logger.error(f"Error in top_losers: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat memproses Top Losers."
        )

