import numpy as np
from datetime import datetime
import pandas as pd
import logging

logger = logging.getLogger(__name__)

async def top_gainers_2024(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return

    try:
        # Koneksi database
        conn = DB_CONNECTION

        # Tentukan periode atau tanggal
        period = context.args[0].lower() if context.args else "harian"

        # Periksa apakah argumen adalah tanggal (YYYY-MM-DD)
        try:
            datetime.strptime(period, "%Y-%m-%d")
            is_date = True
        except ValueError:
            is_date = False

        if is_date:
            selected_date = period
            # Validasi apakah tanggal ada di database
            query_validate = "SELECT COUNT(*) as count FROM stocks WHERE Date = ?"
            count_df = pd.read_sql_query(query_validate, conn, params=(selected_date,))
            if count_df['count'].iloc[0] == 0:
                logger.warning(f"No data available in database for date {selected_date}")
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data saham untuk tanggal {selected_date}. Silakan coba tanggal lain."
                )
                return

            # Cek apakah kolom PrevClose ada di tabel stocks
            cursor = conn.cursor()
            cursor.execute("PRAGMA table_info(stocks)")
            columns = [info[1] for info in cursor.fetchall()]
            prev_close_exists = 'PrevClose' in columns

            if prev_close_exists:
                # Query menggunakan PrevClose jika tersedia
                query = """
                    SELECT Date, Ticker, CompanyName, Close, PrevClose, Volume
                    FROM stocks
                    WHERE Date = ?
                    AND Close IS NOT NULL AND PrevClose IS NOT NULL AND PrevClose != 0 AND Volume IS NOT NULL
                """
                logger.debug(f"Executing query with PrevClose: {query} with params: {selected_date}")
                df = pd.read_sql_query(query, conn, params=(selected_date,))
                df['Change'] = (df['Close'] - df['PrevClose']) / df['PrevClose'] * 100
            else:
                # Fallback: Ambil Close dari hari sebelumastri sebelumnya
                prev_date = (datetime.strptime(selected_date, "%Y-%m-%d") - timedelta(days=1)).strftime("%Y-%m-%d")
                query = """
                    SELECT s1.Date, s1.Ticker, s1.CompanyName, s1.Close, s2.Close AS PrevClose, s1.Volume
                    FROM stocks s1
                    LEFT JOIN stocks s2 ON s1.Ticker = s2.Ticker AND s2.Date = ?
                    WHERE s1.Date = ?
                    AND s1.Close IS NOT NULL AND s2.Close IS NOT NULL AND s2.Close != 0 AND s1.Volume IS NOT NULL
                """
                logger.debug(f"Executing fallback query: {query} with params: {prev_date, selected_date}")
                df = pd.read_sql_query(query, conn, params=(prev_date, selected_date))
                df['Change'] = (df['Close'] - df['PrevClose']) / df['PrevClose'] * 100

            if df.empty:
                logger.warning(f"No data found for date {selected_date} with valid Close, PrevClose, and Volume")
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data saham valid untuk tanggal {selected_date}."
                )
                return

            # Ganti nilai inf dengan NaN
            df['Change'] = df['Change'].replace([np.inf, -np.inf], np.nan)
            df_pivot = df[['Ticker', 'CompanyName', 'Change', 'Close', 'Volume']].set_index('Ticker')
            df_pivot = df_pivot.dropna(subset=['Change'])
            if df_pivot.empty:
                logger.warning(f"No valid change percentages for date {selected_date}")
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data yang cukup untuk menghitung perubahan harga pada tanggal {selected_date}."
                )
                return
            df_pivot = df_pivot.sort_values(by='Change', ascending=False).head(30)

            # Hitung nilai transaksi
            df_pivot['TransactionValue'] = df_pivot['Close'] * df_pivot['Volume']

            # Buat pesan dengan tabel rapi
            message = f"📈 *Top Gainers ({selected_date})*:\n\n"
            message += f"| Ticker      | Company Name         | Change (%) | Close     | Volume      | Value (Rp)  |\n"
            message += f"|-------------|----------------------|------------|-----------|-------------|-------------|\n"
            for ticker, row in df_pivot.iterrows():
                transaction_value = row['TransactionValue']
                if pd.isna(transaction_value):
                    transaction_value_str = "N/A"
                elif transaction_value >= 1_000_000_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000_000_000:,.2f} T"
                elif transaction_value >= 1_000_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000_000:,.2f} B"
                elif transaction_value >= 1_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000:,.2f} M"
                else:
                    transaction_value_str = f"{transaction_value:,.2f}"
                
                change_str = f"{row['Change']:>10.2f}%"
                if row['Change'] > 0:
                    change_str = f"🟢 {change_str}"
                elif row['Change'] < 0:
                    change_str = f"🔴 {change_str}"

                ticker_str = f"{ticker:<11}"
                company_str = f"{row['CompanyName'][:18]:<20}"
                close_str = f"{row['Close']:>9,.2f}"
                volume_str = f"{row['Volume']:>11,.0f}"
                value_str = f"{transaction_value_str:>11}"
                
                message += f"| {ticker_str} | {company_str} | {change_str} | {close_str} | {volume_str} | {value_str} |\n"

            keyboard = []
            for ticker, row in df_pivot.iterrows():
                keyboard.append([InlineKeyboardButton(f"{ticker} - {row['Change']:.2f}%", callback_data=f"tg_{ticker}")])

            keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
            reply_markup = InlineKeyboardMarkup(keyboard)

        else:
            # Logika untuk periode harian, mingguan, atau angka
            if period == "harian":
                days = 2
            elif period == "mingguan":
                days = 5
            else:
                try:
                    days = int(period)
                    if days < 2:
                        raise ValueError("Periode harus minimal 2 hari.")
                except ValueError:
                    await context.bot.send_message(
                        chat_id=update.effective_chat.id,
                        text="Periode tidak valid. Gunakan 'harian', 'mingguan', atau angka (misal: /tgu 3)."
                    )
                    return

            # Ambil tanggal unik dari database
            query_dates = "SELECT DISTINCT Date FROM stocks ORDER BY Date DESC LIMIT ?"
            dates_df = pd.read_sql_query(query_dates, conn, params=(days,))
            dates = dates_df['Date'].tolist()

            if len(dates) < 2:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Data tidak cukup. Diperlukan minimal 2 hari (tersedia: {len(dates)} hari)."
                )
                return

            start_date, end_date = dates[-1], dates[0]
            logger.info(f"Start Date: {start_date}, End Date: {end_date}")

            # Query utama untuk multi-hari
            query = """
                SELECT Date, Ticker, CompanyName, Close, Volume
                FROM stocks 
                WHERE Date IN ({})
                AND Close IS NOT NULL AND Volume IS NOT NULL
            """.format(','.join(['?' for _ in dates]))
            logger.debug(f"Executing query: {query} with params: {dates}")

            df = pd.read_sql_query(query, conn, params=dates)
            if df.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Tidak ada data saham untuk periode {period}."
                )
                return

            # Pivot data untuk menghitung perubahan harga
            df_pivot = df.pivot(index='Ticker', columns='Date', values='Close')
            df_pivot['CompanyName'] = df.groupby('Ticker')['CompanyName'].first()

            if start_date not in df_pivot.columns or end_date not in df_pivot.columns:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Data untuk tanggal awal atau akhir tidak tersedia."
                )
                return

            df_pivot['Change'] = (df_pivot[end_date] - df_pivot[start_date]) / df_pivot[start_date] * 100
            df_pivot['Change'] = df_pivot['Change'].replace([np.inf, -np.inf], np.nan)
            df_pivot = df_pivot.dropna(subset=['Change'])

            # Ambil Volume dan Close terakhir
            latest_date = dates[0]
            df_latest = df[df['Date'] == latest_date][['Ticker', 'Volume', 'Close']].set_index('Ticker')
            df_pivot = df_pivot.join(df_latest[['Volume', 'Close']], how='left', rsuffix='_latest')

            df_pivot['Close'] = df_pivot['Close_latest'].combine_first(df_pivot[end_date])
            df_pivot['TransactionValue'] = df_pivot.apply(
                lambda row: row['Close'] * row['Volume'] if pd.notna(row['Close']) and pd.notna(row['Volume']) else np.nan,
                axis=1
            )

            if df_pivot.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Tidak ada data yang cukup untuk menghitung perubahan harga."
                )
                return
            df_pivot = df_pivot.sort_values(by='Change', ascending=False).head(30)

            # Buat pesan dengan tabel rapi
            message = f"📈 *Top Gainers ({period})*:\n\n"
            message += f"| Ticker      | Company Name         | Change (%) | Close     | Volume      | Value (Rp)  |\n"
            message += f"|-------------|----------------------|------------|-----------|-------------|-------------|\n"
            for ticker, row in df_pivot.iterrows():
                transaction_value = row['TransactionValue']
                if pd.isna(transaction_value):
                    transaction_value_str = "N/A"
                elif transaction_value >= 1_000_000_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000_000_000:,.2f} T"
                elif transaction_value >= 1_000_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000_000:,.2f} B"
                elif transaction_value >= 1_000_000:
                    transaction_value_str = f"{transaction_value / 1_000_000:,.2f} M"
                else:
                    transaction_value_str = f"{transaction_value:,.2f}"
                
                change_str = f"{row['Change']:>10.2f}%"
                if row['Change'] > 0:
                    change_str = f"🟢 {change_str}"
                elif row['Change'] < 0:
                    change_str = f"🔴 {change_str}"

                ticker_str = f"{ticker:<11}"
                company_str = f"{row['CompanyName'][:18]:<20}"
                close_str = f"{row['Close']:>9,.2f}"
                volume_str = f"{row['Volume']:>11,.0f}"
                value_str = f"{transaction_value_str:>11}"
                
                message += f"| {ticker_str} | {company_str} | {change_str} | {close_str} | {volume_str} | {value_str} |\n"

            keyboard = []
            for ticker, row in df_pivot.iterrows():
                keyboard.append([InlineKeyboardButton(f"{ticker} - {row['Change']:.2f}%", callback_data=f"tg_{ticker}")])

            keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
            reply_markup = InlineKeyboardMarkup(keyboard)

        # Kirim pesan
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            reply_markup=reply_markup,
            parse_mode="Markdown"
        )
        logger.info(f"Top Gainers untuk {'tanggal ' + selected_date if is_date else 'periode ' + period} dikirim dengan tombol inline")

    except sqlite3.Error as e:
        logger.error(f"SQLite error in top_gainers_2024: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan pada database saat memproses Top Gainers."
        )
    except pd.io.sql.DatabaseError as e:
        logger.error(f"Pandas SQL error in top_gainers_2024: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mengambil data dari database."
        )
    except Exception as e:
        logger.error(f"Unexpected error in top_gainers_2024: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan tak terduga saat memproses Top Gainers."
        )

