async def top_losers_mbx(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        period = context.args[0].lower() if context.args else "harian"
        if period not in ["harian", "mingguan", "bulanan"]:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan periode yang valid: harian, mingguan, atau bulanan. Contoh: /tl_mbx harian"
            )
            return

        conn = DB_CONNECTION
        # Sesuaikan query berdasarkan periode
        if period == "harian":
            query = """
                SELECT Ticker, Close, LAG(Close, 1) OVER (PARTITION BY Ticker ORDER BY Date) as Prev_Close
                FROM stocks
                WHERE Ticker IN ({})
                ORDER BY Date DESC
            """.format(', '.join(f"'{ticker}'" for ticker in MBX_STOCKS.keys()))
        elif period == "mingguan":
            query = """
                SELECT Ticker, Close, LAG(Close, 5) OVER (PARTITION BY Ticker ORDER BY Date) as Prev_Close
                FROM stocks
                WHERE Ticker IN ({})
                ORDER BY Date DESC
            """.format(', '.join(f"'{ticker}'" for ticker in MBX_STOCKS.keys()))
        elif period == "bulanan":
            query = """
                SELECT Ticker, Close, LAG(Close, 20) OVER (PARTITION BY Ticker ORDER BY Date) as Prev_Close
                FROM stocks
                WHERE Ticker IN ({})
                ORDER BY Date DESC
            """.format(', '.join(f"'{ticker}'" for ticker in MBX_STOCKS.keys()))

        df = pd.read_sql_query(query, conn)

        # Hitung persentase perubahan
        df['Change_Percent'] = ((df['Close'] - df['Prev_Close']) / df['Prev_Close']) * 100
        df = df.dropna().groupby('Ticker').first().reset_index()  # Ambil data terbaru per ticker
        top_losers = df.nsmallest(10, 'Change_Percent')  # Top 10 losers

        if top_losers.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Tidak ada data Top Losers MBX untuk periode ini."
            )
            return

        message = f"🔽 *Top Losers MBX ({period.capitalize()})*\n\n"
        keyboard = []
        for i, row in top_losers.iterrows():
            ticker = row['Ticker']
            change = row['Change_Percent']
            message += f"{i+1}. {ticker} - {change:+.2f}%\n"
            keyboard.append([InlineKeyboardButton(f"{ticker} ({change:+.2f}%)", callback_data=f"tl_mbx_{ticker}")])

        keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
        reply_markup = InlineKeyboardMarkup(keyboard)

        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            reply_markup=reply_markup,
            parse_mode="Markdown"
        )
        logger.info(f"Top Losers MBX ({period}) dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in top_losers_mbx: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mengambil Top Losers MBX. Silakan coba lagi."
        )

