async def list_signal(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        # Beri tahu pengguna bahwa proses sedang berjalan
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Sedang memproses daftar saham dengan potensi kenaikan... Mohon tunggu."
        )

        conn = DB_CONNECTION
        # Ambil semua ticker unik dari tabel stocks yang memiliki data terbaru
        tickers_query = """
            SELECT DISTINCT Ticker 
            FROM stocks 
            WHERE Date = (SELECT MAX(Date) FROM stocks)
        """
        tickers = pd.read_sql_query(tickers_query, conn)['Ticker'].tolist()

        if not tickers:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Tidak ada data saham terbaru di database.")
            
            return

        buy_signals_list = []
        for ticker in tickers:
            # Ambil data 50 hari terakhir untuk ticker
            query = """
                SELECT Date, Close, High, Low 
                FROM stocks 
                WHERE Ticker = ? 
                AND Close IS NOT NULL 
                AND High IS NOT NULL 
                AND Low IS NOT NULL 
                ORDER BY Date DESC 
                LIMIT 50
            """
            df = pd.read_sql_query(query, conn, params=(ticker,))

            # Pastikan data cukup (minimal 30 hari untuk indikator yang akurat)
            if len(df) < 30:
                logger.warning(f"Data untuk {ticker} kurang dari 30 hari, dilewati.")
                continue

            df['Date'] = pd.to_datetime(df['Date'])
            df = df.sort_values(by='Date')

            # Hitung indikator dengan pengecekan
            try:
                rsi_series = ta.rsi(df['Close'], length=14)
                macd = ta.macd(df['Close'])
                stoch = ta.stoch(df['High'], df['Low'], df['Close'])

                # Pastikan indikator tidak None
                if rsi_series is None or macd is None or stoch is None:
                    logger.warning(f"Gagal menghitung indikator untuk {ticker}, dilewati.")
                    continue

                df['RSI'] = rsi_series
                df['MACD'] = macd['MACD_12_26_9']
                df['Signal'] = macd['MACDs_12_26_9']
                df['Stoch_K'] = stoch['STOCHk_14_3_3']

                # Ambil nilai terbaru dengan pengecekan None
                rsi = df['RSI'].iloc[-1] if not pd.isna(df['RSI'].iloc[-1]) else None
                macd_line = df['MACD'].iloc[-1] if not pd.isna(df['MACD'].iloc[-1]) else None
                signal_line = df['Signal'].iloc[-1] if not pd.isna(df['Signal'].iloc[-1]) else None
                stoch_k = df['Stoch_K'].iloc[-1] if not pd.isna(df['Stoch_K'].iloc[-1]) else None
                latest_date = df['Date'].iloc[-1]

                # Pastikan semua nilai indikator tersedia
                if any(v is None for v in [rsi, macd_line, signal_line, stoch_k]):
                    logger.warning(f"Indikator untuk {ticker} mengandung None, dilewati.")
                    continue

                # Logika sinyal
                buy_signals = 0
                sell_signals = 0

                if rsi < 30:
                    buy_signals += 1
                elif rsi > 70:
                    sell_signals += 1

                if macd_line > signal_line:
                    buy_signals += 1
                elif macd_line < signal_line:
                    sell_signals += 1

                if stoch_k < 20:
                    buy_signals += 1
                elif stoch_k > 80:
                    sell_signals += 1

                # Jika rekomendasi adalah "Beli (Potensi Kenaikan)", masukkan ke daftar
                if buy_signals >= 2:
                    buy_signals_list.append({
                        'ticker': ticker,
                        'rsi': rsi,
                        'macd_line': macd_line,
                        'signal_line': signal_line,
                        'stoch_k': stoch_k,
                        'date': latest_date
                    })

            except Exception as e:
                logger.error(f"Error saat menghitung indikator untuk {ticker}: {str(e)}")
                continue

        

        # Buat pesan untuk ditampilkan
        if not buy_signals_list:
            await context.bot.send_message(chat_id=update.effective_chat.id, text="Tidak ada saham dengan potensi kenaikan saat ini.")
            return

        message = "Daftar Saham dengan Potensi Kenaikan:\n\n"
        for i, signal in enumerate(buy_signals_list, 1):
            message += f"{i}. Sinyal Trading {signal['ticker']}:\n"
            message += f"RSI: {signal['rsi']:.2f}\n"
            message += f"MACD: Line: {signal['macd_line']:.2f}, Signal: {signal['signal_line']:.2f}\n"
            message += f"Stochastic %K: {signal['stoch_k']:.2f}\n"
            message += f"Rekomendasi: Beli (Potensi Kenaikan)\n"
            message += f"Tanggal: {signal['date']}\n\n"

        await context.bot.send_message(chat_id=update.effective_chat.id, text=message)
        logger.info("Daftar saham dengan potensi kenaikan dikirim")
    except Exception as e:
        logger.error(f"Error in list_signal: {str(e)}")
        await context.bot.send_message(chat_id=update.effective_chat.id, text="Terjadi kesalahan saat mengambil daftar sinyal. Silakan coba lagi nanti.")


# Fungsi untuk menampilkan menu utama dengan tombol di area input pesan
