# Pastikan database cmc_data.db ada dan tabel dibuat saat bot start
def ensure_crypto_database():
    conn = sqlite3.connect(DB_NAME)
    cursor = conn.cursor()
    
    # Tabel metadata
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS metadata (
            timestamp TEXT,
            total_coins INTEGER,
            coins_scanned INTEGER
        )
    ''')

    # Tabel coins
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS coins (
            timestamp TEXT,
            symbol TEXT,
            name TEXT,
            price_usd REAL,
            volume_24h REAL,
            volume_change_24h REAL,
            percent_change_1h REAL,
            percent_change_24h REAL,
            percent_change_7d REAL,
            percent_change_30d REAL,
            percent_change_60d REAL,
            percent_change_90d REAL,
            market_cap REAL,
            market_cap_dominance REAL,
            fully_diluted_market_cap REAL,
            quote_last_updated TEXT,
            circulating_supply REAL,
            slug TEXT,
            cmc_rank INTEGER
        )
    ''')

    # Tabel coin_metadata
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS coin_metadata (
            symbol TEXT PRIMARY KEY,
            name TEXT,
            slug TEXT,
            website TEXT,
            date_added TEXT
        )
    ''')

    conn.commit()
    conn.close()
    logger.info("Crypto database initialized")

# Modifikasi fungsi update_crypto_data
async def update_crypto_data(context: ContextTypes.DEFAULT_TYPE):
    if not CMC_API_KEY:
        logger.error("CoinMarketCap API Key tidak ditemukan. Silakan set CMC_API_KEY di variabel lingkungan.")
        return

    logger.info("Updating crypto data from CoinMarketCap")
    limit_per_request = 5000
    start = 1
    all_coins = []
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    initial_data = get_crypto_data(start, 1)
    if not initial_data:
        logger.error("Failed to fetch initial data from CoinMarketCap")
        return
    
    total_coins = initial_data['status']['total_count']
    logger.info(f"Total coins on CMC: {total_coins}")

    while start <= total_coins:
        logger.info(f"Fetching coins {start} to {min(start + limit_per_request - 1, total_coins)}...")
        data = get_crypto_data(start, limit_per_request)
        if data:
            all_coins.extend(data['data'])
        start += limit_per_request
        time.sleep(1)

    logger.info(f"Total coins successfully scanned: {len(all_coins)}")
    save_to_sqlite(total_coins, all_coins, timestamp)
    logger.info(f"Updated crypto data saved to database with timestamp {timestamp}")
        
