@app.post(f"/{TOKEN}")
async def webhook(request: Request):
    try:
        # Pastikan webhook aktif sebelum memproses update
        await health_check()
        update = Update.de_json(await request.json(), application.bot)
        await application.process_update(update)
        return {"status": "ok"}
    except Exception as e:
        logger.error(f"Error in webhook: {str(e)}")
        return {"status": "error"}

def ensure_database():
    conn = DB_CONNECTION
    cursor = conn.cursor()
    
    # Buat tabel users jika belum ada
    cursor.execute('''CREATE TABLE IF NOT EXISTS users (
        user_id INTEGER PRIMARY KEY,
        access_count INTEGER DEFAULT 0,
        last_access_date TEXT,
        subscription_type TEXT DEFAULT 'free',  -- Pastikan default adalah 'free'
        subscription_expiry TEXT
    )''')
    
    # Periksa apakah kolom subscription_type memiliki default 'free'
    cursor.execute("PRAGMA table_info(users)")
    columns = cursor.fetchall()
    sub_type_column = next((col for col in columns if col[1] == 'subscription_type'), None)
    if sub_type_column and sub_type_column[4] != "'free'":
        # Jika default bukan 'free', ubah skema tabel
        cursor.execute("ALTER TABLE users RENAME TO users_old")
        cursor.execute('''CREATE TABLE users (
            user_id INTEGER PRIMARY KEY,
            access_count INTEGER DEFAULT 0,
            last_access_date TEXT,
            subscription_type TEXT DEFAULT 'free',
            subscription_expiry TEXT
        )''')
        cursor.execute("INSERT INTO users (user_id, access_count, last_access_date, subscription_type, subscription_expiry) SELECT user_id, access_count, last_access_date, COALESCE(subscription_type, 'free'), subscription_expiry FROM users_old")
        cursor.execute("DROP TABLE users_old")
    
    # Tabel lainnya tetap sama
    cursor.execute('''CREATE TABLE IF NOT EXISTS stocks (
        Date TEXT,
        Ticker TEXT,
        CompanyName TEXT,
        Open REAL,
        High REAL,
        Low REAL,
        Close REAL,
        Volume INTEGER,
        PRIMARY KEY (Date, Ticker)
    )''')
    
    cursor.execute('''CREATE TABLE IF NOT EXISTS fundamental_data (
        Ticker TEXT PRIMARY KEY,
        CompanyName TEXT,
        EPS REAL,
        PE_Ratio REAL,
        PBV REAL,
        ROE REAL,
        Debt_to_Equity REAL,
        Market_Cap REAL,
        Last_Updated TEXT
    )''')
    
    cursor.execute('''CREATE TABLE IF NOT EXISTS watchlist (
        user_id INTEGER,
        ticker TEXT,
        PRIMARY KEY (user_id, ticker)
    )''')
    
    conn.commit()

async def fundamental(update: Update, context: ContextTypes.DEFAULT_TYPE):
    
    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan kode saham, contoh: /af ESSA"
            )
            return

        ticker = context.args[0].upper()
        conn = DB_CONNECTION
        query = """
            SELECT ticker, name, pe_ratio, market_cap, eps, roe, debt_to_equity, dividend_yield
            FROM fundamental_data 
            WHERE ticker = ?
        """
        df = pd.read_sql_query(query, conn, params=(ticker,))

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data fundamental untuk saham {ticker}. Silakan perbarui data dengan /update_fundamental."
            )
            return

        row = df.iloc[0]
        company_name = row['name']
        
        # Ambil harga saham terbaru
        query_price = """
            SELECT Close 
            FROM stocks 
            WHERE Ticker = ? 
            AND Date = (SELECT MAX(Date) FROM stocks WHERE Ticker = ?)
        """
        cursor = conn.cursor()
        cursor.execute(query_price, (ticker, ticker))
        price_data = cursor.fetchone()
        current_price = price_data[0] if price_data else "N/A"
        
        # Ambil berita terkait
        cursor.execute("SELECT title, url, published_date, source, last_updated FROM news WHERE ticker = ?", (ticker,))
        news_data = cursor.fetchall()
        
        # Jika berita tidak ada atau kadaluarsa, perbarui
        if not news_data or (news_data and (datetime.now() - datetime.strptime(news_data[0][4], "%Y-%m-%d %H:%M:%S")) > timedelta(days=1)):
            await update_news_for_ticker(ticker, company_name)
            cursor.execute("SELECT title, url, published_date, source, last_updated FROM news WHERE ticker = ?", (ticker,))
            news_data = cursor.fetchall()
        
        # Format data fundamental
        # Asumsi: roe dan dividend_yield dalam database sudah dalam bentuk persentase (misalnya, 11.45, bukan 0.1145)
        # Jika dalam bentuk desimal, uncomment baris konversi di bawah
        roe_value = row['roe']
        dividend_yield_value = row['dividend_yield']

        # Jika data dalam database dalam bentuk desimal (misalnya, 0.1145), uncomment baris berikut:
        # roe_value = row['roe'] * 100  # Konversi ke persentase
        # dividend_yield_value = row['dividend_yield'] * 100  # Konversi ke persentase

        message = f"📊 *Analisis Fundamental {ticker} - {company_name}*\n\n"
        message += f"**Harga Saat Ini:** Rp{current_price:,.2f}\n\n"
        message += f"**Fundamental:**\n"
        message += f"📈 P/E Ratio: {row['pe_ratio']:.2f}x\n"
        message += f"💰 Market Cap: Rp{row['market_cap']:,.0f}\n"
        message += f"📊 EPS: Rp{row['eps']:.2f}\n"
        message += f"📉 ROE: {roe_value:.2f}\n"  # Format manual tanpa konversi otomatis
        message += f"⚖️ Debt to Equity: {row['debt_to_equity']:.2f}\n"
        message += f"💸 Dividend Yield: {dividend_yield_value:.2f}%\n"  # Format manual tanpa konversi otomatis
        message += f"🌐 Sumber: Database Yahoo Finance\n"
        message += f"🔗 Website: https://www.idnfinancials.com/id/{ticker}\n\n"
        
        # Peringatan Debt to Equity
        if row['debt_to_equity'] > 0.5:
            message += f"⚠️ **Hati-hati:** Debt to Equity > 0.5, pertimbangkan dengan hati-hati.\n\n"
        
        # Tambahkan berita terkait
        if news_data:
            message += f"📰 *Berita Terkait:*\n\n"
            for news in news_data[:2]:  # Tampilkan 2 berita teratas
                title, url, published_date, source, _ = news
                message += f"**{title}**\n"
                message += f"Sumber: {source}\n"
                message += f"Terbit: {published_date}\n"
                message += f"Link: {url}\n\n"
        else:
            message += f"📰 *Berita Terkait:* Tidak ada berita terkait untuk {ticker} saat ini.\n\n"
        
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            parse_mode="Markdown",
            disable_web_page_preview=True
        )
        logger.info(f"Analisis fundamental untuk {ticker} dikirim")

    except Exception as e:
        logger.error(f"Error in fundamental: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat memproses analisis fundamental."
        )

async def check_fundamental(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        ensure_database()  # Pastikan database ada
        conn = DB_CONNECTION
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM fundamental_data")
        row_count = cursor.fetchone()[0]

        if row_count == 0:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Belum ada data fundamental di database. Silakan perbarui data dengan /update_fundamental."
            )
            logger.info("Tabel fundamental_data kosong")
        else:
            df = pd.read_sql_query("SELECT ticker, name, eps, last_updated FROM fundamental_data LIMIT 5", conn)
            message = f"Data fundamental tersedia ({row_count} saham):\n\n"
            for i, row in df.iterrows():
                message += f"{i+1}. {row['ticker']} ({row['name']}):\n"
                message += f"EPS: {row['eps']:.2f}\n"
                message += f"Terakhir Diperbarui: {row['last_updated']}\n\n"
            await context.bot.send_message(chat_id=update.effective_chat.id, text=message)
            logger.info(f"Data fundamental ditemukan: {row_count} saham")

        
    except Exception as e:
        logger.error(f"Error in check_fundamental: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat memeriksa data fundamental."
        )
def detect_doji(open_price: float, close_price: float) -> bool:
    """
    Mendeteksi apakah candlestick adalah Doji.
    Doji terjadi jika harga pembukaan sama dengan harga penutupan secara eksak.
    Args:
        open_price (float): Harga pembukaan
        close_price (float): Harga penutupan
    Returns:
        bool: True jika Doji, False jika bukan
    """
    if open_price == 0 or close_price == 0:
        return False
    
    return open_price == close_price  # Hanya menerima Open = Close secara eksak

async def doji(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Mencari candlestick Doji berdasarkan indeks dan periode waktu.
    Contoh: /doji lq45 atau /doji lq45 2025-03-07
    """
    if not await check_user_access(update, context):
        return
    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan indeks, contoh: /doji lq45 atau /doji lq45 2025-03-07"
            )
            return
        
        index = context.args[0].lower()
        target_date = context.args[1] if len(context.args) > 1 else None
        logger.info(f"Pencarian Doji untuk indeks: {index}, tanggal: {target_date} oleh user {update.effective_user.id}")

        indices = {
            "lq45": LQ45_STOCKS,
            "kompas100": KOMPAS100_STOCKS,
            "jii70": JII70_STOCKS
        }
        if index not in indices:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Indeks tidak valid. Gunakan: lq45, kompas100, atau jii70."
            )
            return
        
        stock_list = indices[index]
        if not stock_list:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Daftar saham {index.upper()} tidak tersedia. Silakan perbarui data."
            )
            return

        conn = DB_CONNECTION
        cursor = conn.cursor()

        if target_date:
            try:
                datetime.strptime(target_date, "%Y-%m-%d")
                query = """
                    SELECT Ticker, Open, Close, Date 
                    FROM stocks 
                    WHERE Ticker = ? AND Date = ?
                """
            except ValueError:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Format tanggal salah. Gunakan YYYY-MM-DD, contoh: 2025-03-07"
                )
                return
        else:
            query = """
                SELECT Ticker, Open, Close, Date 
                FROM stocks 
                WHERE Ticker = ? 
                AND Date = (SELECT MAX(Date) FROM stocks WHERE Ticker = ?)
            """

        doji_stocks = []
        for ticker in stock_list.keys():
            try:
                if target_date:
                    cursor.execute(query, (ticker, target_date))
                else:
                    cursor.execute(query, (ticker, ticker))
                
                row = cursor.fetchone()
                if row:
                    _, open_price, close_price, actual_date = row
                    logger.info(f"Data untuk {ticker} pada {actual_date}: Open={open_price}, Close={close_price}")
                    if open_price is None or close_price is None:
                        logger.warning(f"Data untuk {ticker} tidak lengkap pada {actual_date}")
                        continue
                    if detect_doji(open_price, close_price):
                        company_name = stock_list.get(ticker, "Nama tidak tersedia")
                        doji_stocks.append((ticker, company_name, actual_date))
                else:
                    logger.info(f"Tidak ada data untuk {ticker} pada {target_date if target_date else 'data terakhir'}")
            except Exception as e:
                logger.error(f"Error saat memeriksa Doji untuk {ticker}: {str(e)}")
                continue

        if not doji_stocks:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📉 Tidak ada pola Doji ditemukan di saham {index.upper()} {date_text}."
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown"
            )
        else:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📉 *Saham dengan Pola Doji di {index.upper()} {date_text}:*\n\n"
            keyboard = []
            for ticker, company_name, actual_date in doji_stocks:
                message += f"- {ticker} - {company_name}\n"
                callback_data = f"show_doji_chart_{ticker}_{actual_date}"
                keyboard.append([InlineKeyboardButton(f"Grafik {ticker}", callback_data=callback_data)])
            
            reply_markup = InlineKeyboardMarkup(keyboard)
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown",
                reply_markup=reply_markup
            )
        logger.info(f"Pencarian Doji untuk indeks {index} selesai")

    except Exception as e:
        logger.error(f"Error in doji: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mencari pola Doji."
        )
        
import mplfinance as mpf
import matplotlib
matplotlib.use('Agg')  # Gunakan backend non-interaktif untuk matplotlib
import io
from datetime import datetime, timedelta

async def generate_candlestick_chart(ticker: str, target_date: str) -> io.BytesIO:
    """
    Menghasilkan grafik candlestick untuk saham tertentu.
    Args:
        ticker (str): Kode saham (misalnya, BJBR)
        target_date (str): Tanggal target dalam format YYYY-MM-DD
    Returns:
        io.BytesIO: Buffer gambar grafik
    """
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        # Parse tanggal target
        target_date_dt = datetime.strptime(target_date, "%Y-%m-%d")
        start_date = (target_date_dt - timedelta(days=10)).strftime("%Y-%m-%d")
        end_date = (target_date_dt + timedelta(days=10)).strftime("%Y-%m-%d")

        # Ambil data historis dari database (21 hari: 10 hari sebelum dan sesudah)
        conn = DB_CONNECTION
        query = """
            SELECT Date, Open, High, Low, Close, Volume 
            FROM stocks 
            WHERE Ticker = ? 
            AND Date BETWEEN ? AND ?
            ORDER BY Date
        """
        df = pd.read_sql_query(query, conn, params=(ticker, start_date, end_date))

        if df.empty:
            raise ValueError(f"Tidak ada data historis untuk {ticker} pada rentang tanggal tersebut.")

        # Format data untuk mplfinance
        df['Date'] = pd.to_datetime(df['Date'])
        df = df.set_index('Date')
        df = df[['Open', 'High', 'Low', 'Close', 'Volume']]

        # Buat grafik candlestick
        buffer = io.BytesIO()
        mpf.plot(
            df,
            type='candle',
            style='yahoo',
            title=f"Candlestick Chart {ticker} (Doji pada {target_date})",
            ylabel='Harga (Rp)',
            volume=True,
            savefig=dict(fname=buffer, dpi=100, bbox_inches='tight'),
            tight_layout=True
        )
        buffer.seek(0)
        return buffer

    except Exception as e:
        logger.error(f"Error saat menghasilkan grafik untuk {ticker}: {str(e)}")
        raise

