async def list_sectors(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        conn = DB_CONNECTION
        query = "SELECT DISTINCT sector FROM fundamental_data WHERE sector IS NOT NULL AND sector != 'N/A'"
        sectors = pd.read_sql_query(query, conn)['sector'].tolist()
        

        if not sectors:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Tidak ada data sektor yang tersedia. Silakan perbarui data fundamental dengan /update_fundamental."
            )
            return

        message = "📋 *Daftar Sektor:*\n\n"
        for i, sector in enumerate(sectors, 1):
            message += f"{i}. {sector}\n"

        message += "\nPilih sektor untuk melihat daftar saham dengan tombol di bawah:"

        # Buat tombol inline untuk setiap sektor
        keyboard = [
            [InlineKeyboardButton(sector, callback_data=f"sector_{sector}")]
            for sector in sectors
        ]
        keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
        reply_markup = InlineKeyboardMarkup(keyboard)

        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            parse_mode="Markdown",
            reply_markup=reply_markup
        )
        logger.info("Daftar sektor dikirim dengan tombol inline")

    except Exception as e:
        logger.error(f"Error in list_sectors: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mengambil daftar sektor."
        )


