async def check_signals(context: ContextTypes.DEFAULT_TYPE):
    logger.info("Memulai pengecekan sinyal otomatis")
    try:
        conn = DB_CONNECTION  # Sesuaikan path jika menggunakan Render Disk
        cursor = conn.cursor()
        cursor.execute("SELECT DISTINCT user_id, ticker FROM watchlist")
        watchlist = cursor.fetchall()

        if not watchlist:
            logger.info("Watchlist kosong, tidak ada saham untuk diperiksa.")
            
            return

        for user_id, ticker in watchlist:
            logger.info(f"Memeriksa sinyal untuk {ticker} (user {user_id})")
            query = "SELECT Date, Close, High, Low FROM stocks WHERE Ticker = ? ORDER BY Date DESC LIMIT 30"
            df = pd.read_sql_query(query, conn, params=(ticker,))
            if df.empty:
                logger.warning(f"Tidak ada data untuk {ticker}, dilewati.")
                continue

            df['Date'] = pd.to_datetime(df['Date'])
            df = df.sort_values(by='Date')

            # Hitung RSI dan MACD dengan pengecekan
            rsi_series = ta.rsi(df['Close'], length=14)
            rsi = rsi_series.iloc[-1] if not rsi_series.isna().all() else None
            macd = ta.macd(df['Close'])
            macd_line = macd['MACD_12_26_9'].iloc[-1] if not macd['MACD_12_26_9'].isna().all() else None
            signal_line = macd['MACDs_12_26_9'].iloc[-1] if not macd['MACDs_12_26_9'].isna().all() else None

            if rsi is None or macd_line is None or signal_line is None:
                logger.warning(f"Indikator untuk {ticker} tidak lengkap (RSI: {rsi}, MACD: {macd_line}, Signal: {signal_line}), dilewati.")
                continue

            # Logika sinyal: RSI dan MACD harus match
            if rsi < 30 and macd_line > signal_line:
                await context.bot.send_message(
                    chat_id=user_id,
                    text=f"🚨 Sinyal Beli {ticker}!\nRSI: {rsi:.2f} (Oversold)\nMACD: Bullish Crossover"
                )
                logger.info(f"Sinyal beli dikirim untuk {ticker} ke user {user_id}")
            elif rsi > 70 and macd_line < signal_line:
                await context.bot.send_message(
                    chat_id=user_id,
                    text=f"🚨 Sinyal Jual {ticker}!\nRSI: {rsi:.2f} (Overbought)\nMACD: Bearish Crossover"
                )
                logger.info(f"Sinyal jual dikirim untuk {ticker} ke user {user_id}")
            else:
                logger.info(f"Tidak ada sinyal untuk {ticker} (RSI: {rsi:.2f}, MACD: {macd_line:.2f}, Signal: {signal_line:.2f})")

        
        logger.info("Pengecekan sinyal otomatis selesai")
    except Exception as e:
        logger.error(f"Error in check_signals: {str(e)}")

            
