async def screen_percentage_change(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan periode dan indeks (opsional), contoh:\n"
                     "- /screen harian\n"
                     "- /screen mingguan lq45\n"
                     "- /screen bulanan kompas100\n"
                     "- /screen 10 (untuk 10 hari)\n"
                     "Gunakan --threshold <nilai> untuk filter persentase ADL (contoh: /screen harian --threshold 5)",
                
            )
            return

        period_input = context.args[0].lower()
        index = context.args[1].lower() if len(context.args) > 1 and context.args[1] not in ["--threshold"] else "all"
        threshold = None

        if "--threshold" in context.args:
            try:
                threshold_idx = context.args.index("--threshold") + 1
                threshold = float(context.args[threshold_idx])
            except (IndexError, ValueError):
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Threshold ADL tidak valid. Contoh: /screen harian --threshold 5",
                    
                )
                return

        if period_input == "harian":
            days = 2
            period_display = "Harian"
        elif period_input == "mingguan":
            days = 5
            period_display = "Mingguan"
        elif period_input == "bulanan":
            days = 30
            period_display = "Bulanan"
        else:
            try:
                days = int(period_input)
                if days < 2:
                    raise ValueError("Periode harus minimal 2 hari.")
                period_display = f"{days} Hari"
            except ValueError:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Periode tidak valid. Gunakan 'harian', 'mingguan', 'bulanan', atau angka (misal: /screen 10).",
                    
                )
                return

        logger.info(f"Screening saham berdasarkan ADL untuk periode {period_display} ({days} hari), indeks: {index}, threshold: {threshold}")

        if index == "lq45":
            tickers = list(LQ45_STOCKS.keys())
        elif index == "kompas100":
            tickers = list(KOMPAS100_STOCKS.keys())
        elif index == "jii70":
            tickers = list(JII70_STOCKS.keys())
        else:
            conn = DB_CONNECTION
            tickers = pd.read_sql_query("SELECT DISTINCT Ticker FROM stocks", conn)['Ticker'].tolist()
            

        conn = DB_CONNECTION
        query_dates = "SELECT DISTINCT Date FROM stocks ORDER BY Date DESC LIMIT ?"
        dates = pd.read_sql_query(query_dates, conn, params=(days,))['Date'].tolist()

        if len(dates) < days:
            
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Data tidak cukup untuk analisis {period_display}. Diperlukan minimal {days} hari.",
                
            )
            return

        start_date, end_date = dates[-1], dates[0]

        query = f"""
            SELECT Date, Ticker, CompanyName, High, Low, Close, Volume 
            FROM stocks 
            WHERE Date IN ({','.join(['?']*len(dates))})
            AND Ticker IN ({','.join(['?']*len(tickers))})
            AND Close IS NOT NULL AND Volume IS NOT NULL
        """
        df = pd.read_sql_query(query, conn, params=dates + tickers)
        

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data saham untuk periode {period_display} dan indeks {index}.",
                
            )
            return

        # Hitung ADL untuk setiap ticker
        adl_data = {}
        for ticker in tickers:
            df_ticker = df[df['Ticker'] == ticker].sort_values('Date')
            if len(df_ticker) < 2:  # Minimal 2 hari untuk perubahan
                continue
            df_ticker['Money Flow Multiplier'] = ((df_ticker['Close'] - df_ticker['Low']) - (df_ticker['High'] - df_ticker['Close'])) / (df_ticker['High'] - df_ticker['Low'])
            df_ticker['Money Flow Volume'] = df_ticker['Money Flow Multiplier'] * df_ticker['Volume']
            df_ticker['ADL'] = df_ticker['Money Flow Volume'].cumsum()
            adl_start = df_ticker['ADL'].iloc[0]
            adl_end = df_ticker['ADL'].iloc[-1]
            if adl_start != 0:  # Hindari pembagian dengan nol
                adl_change = (adl_end - adl_start) / abs(adl_start) * 100
            else:
                adl_change = float('inf') if adl_end > 0 else float('-inf')
            adl_data[ticker] = {
                'ADL Change (%)': adl_change,
                'CompanyName': df_ticker['CompanyName'].iloc[0],
                'Volume Change': df_ticker['Volume'].iloc[-1] - df_ticker['Volume'].iloc[0]
            }

        # Buat DataFrame dari hasil ADL
        df_adl = pd.DataFrame.from_dict(adl_data, orient='index').dropna()

        if df_adl.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data ADL yang cukup untuk periode {period_display}.",
                
            )
            return

        # Filter berdasarkan threshold ADL jika ada
        if threshold is not None:
            df_adl = df_adl[abs(df_adl['ADL Change (%)']) >= threshold]

        # Urutkan berdasarkan perubahan ADL terbesar
        df_adl = df_adl.sort_values(by='ADL Change (%)', ascending=False).head(10)

        if df_adl.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada saham yang memenuhi kriteria ADL untuk periode {period_display}.",
                
            )
            return

        # Buat pesan dan tombol inline
        message = f"📊 *Screening Saham Berdasarkan ADL ({period_display} - {index.upper()})*\n\n"
        keyboard = []
        for ticker, row in df_adl.iterrows():
            adl_change = row['ADL Change (%)']
            volume_change = row['Volume Change']
            company_name = row['CompanyName']
            status = "Akumulasi" if adl_change > 0 else "Distribusi"
            volume_status = "Meningkat" if volume_change > 0 else "Menurun" if volume_change < 0 else "Stabil"
            message += f"{ticker} ({company_name}):\n"
            message += f"ADL Change: {adl_change:.2f}% ({status})\n"
            message += f"Volume: {volume_change:,} ({volume_status})\n\n"
            keyboard.append([InlineKeyboardButton(f"{ticker} - {adl_change:.2f}%", callback_data=f"p_{ticker}_{days}")])

        keyboard.append([InlineKeyboardButton("Kembali ke Menu", callback_data="back_to_menu")])
        reply_markup = InlineKeyboardMarkup(keyboard)

        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            reply_markup=reply_markup,
            parse_mode="Markdown"
        )
        logger.info(f"Screening saham berdasarkan ADL untuk {period_display} ({index}) dikirim")

    except Exception as e:
        logger.error(f"Error in screen_percentage_change: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat melakukan screening saham berdasarkan ADL.",
            
        )

async def sector_change_heatmap(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if len(context.args) < 1:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan nama sektor dan periode (opsional), contoh: /sector_heatmap Energy harian"
            )
            return

        sector = context.args[0].title()
        period = context.args[1].lower() if len(context.args) > 1 else "harian"
        logger.info(f"Perintah /sector_heatmap diterima dari user {update.effective_user.id}, sektor: {sector}, periode: {period}")

        if period == "harian":
            days = 2
        elif period == "mingguan":
            days = 5
        else:
            try:
                days = int(period)
                if days < 2:
                    raise ValueError("Periode harus minimal 2 hari.")
            except ValueError as e:
                logger.error(f"Error: Periode tidak valid - {str(e)}")
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Periode tidak valid. Gunakan 'harian', 'mingguan', atau angka (misal: /sector_heatmap Energy 3)."
                )
                return

        conn = DB_CONNECTION
        query_dates = "SELECT DISTINCT Date FROM stocks ORDER BY Date DESC LIMIT ?"
        dates = pd.read_sql_query(query_dates, conn, params=(days,))['Date'].tolist()

        if len(dates) < days:
            
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Data tidak cukup untuk analisis. Diperlukan data minimal {days} hari."
            )
            return

        start_date, end_date = dates[-1], dates[0]

        query_tickers = "SELECT ticker, name FROM fundamental_data WHERE sector = ?"
        tickers_df = pd.read_sql_query(query_tickers, conn, params=(sector,))
        tickers = tickers_df['ticker'].tolist()

        if not tickers:
            
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada saham dalam sektor {sector}."
            )
            return

        query = f"""
            SELECT Date, Ticker, CompanyName, Close 
            FROM stocks 
            WHERE Date IN ({','.join(['?']*len(dates))})
            AND Ticker IN ({','.join(['?']*len(tickers))})
            AND Close IS NOT NULL
        """
        params = dates + tickers
        df = pd.read_sql_query(query, conn, params=params)

        if df.empty:
            
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data saham untuk sektor {sector} pada tanggal yang dipilih."
            )
            return

        df_pivot = df.pivot(index='Ticker', columns='Date', values='Close')
        df_pivot['CompanyName'] = df.groupby('Ticker')['CompanyName'].first()

        df_pivot['Change (%)'] = (df_pivot[end_date] - df_pivot[start_date]) / df_pivot[start_date] * 100
        df_pivot = df_pivot.dropna(subset=['Change (%)'])
        df_pivot = df_pivot.sort_values(by='Change (%)', ascending=False)

        if df_pivot.empty:
            
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Tidak ada data yang cukup untuk menghitung perubahan harga."
            )
            return

        heatmap_data = pd.DataFrame(df_pivot['Change (%)'])
        heatmap_data.columns = ['Change (%)']

        colors = [
            (1, 0, 0),
            (1, 0.5, 0.5),
            (1, 1, 1),
            (0.5, 1, 0.5),
            (0, 0.5, 0)
        ]
        cmap = LinearSegmentedColormap.from_list("custom_cmap", colors, N=256)

        plt.figure(figsize=(8, len(heatmap_data) * 0.3))
        sns.heatmap(
            heatmap_data,
            annot=True,
            fmt=".2f",
            cmap=cmap,
            center=0,
            vmin=heatmap_data['Change (%)'].min(),
            vmax=heatmap_data['Change (%)'].max(),
            cbar_kws={'label': 'Perubahan Harga (%)'},
            linewidths=0.5,
            linecolor='gray',
            yticklabels=[f"{ticker} ({tickers_df.set_index('ticker').loc[ticker, 'name']})" for ticker in heatmap_data.index]
        )
        plt.title(f"Heatmap Perubahan Harga Sektor {sector} ({period})")
        plt.xlabel("Perubahan (%)")
        plt.ylabel("Saham")

        chart_path = f"sector_change_heatmap_{sector}_{period}.png"
        plt.tight_layout()
        plt.savefig(chart_path, bbox_inches='tight')
        plt.close()

        with open(chart_path, 'rb') as photo:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Heatmap Perubahan Harga Sektor {sector} ({period}):"
            )
            await context.bot.send_photo(chat_id=update.effective_chat.id, photo=photo)

        os.remove(chart_path)
        logger.info(f"Heatmap perubahan harga sektor {sector} untuk periode {period} dikirim")
        

    except Exception as e:
        logger.error(f"Error in sector_change_heatmap: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=f"Terjadi kesalahan saat membuat heatmap perubahan harga sektor {sector}."
        )
        
import os
import tempfile
from pathlib import Path

async def index_change_heatmap_custom(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Menghasilkan heatmap perubahan harga saham untuk indeks yang dipilih (KOMPAS100, LQ45, JII70, MBX, ISSI).
    Mendukung periode seperti 'harian', 'mingguan', angka, atau tanggal spesifik (YYYY-MM-DD).
    Jika jumlah saham melebihi batas per gambar, heatmap akan dibagi menjadi beberapa file.
    Menampilkan ticker, persentase perubahan, dan harga penutupan di setiap sel heatmap.
    """
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        if len(context.args) < 1:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan indeks dan periode (opsional), contoh: /ih2 kompas100 harian atau /ih2 lq45 2025-03-05"
            )
            return

        index = context.args[0].lower()  # Ambil indeks dari argumen pertama
        period = context.args[1].lower() if len(context.args) > 1 else "harian"
        start_date = None
        end_date = None
        days = None

        # Coba parse periode sebagai tanggal (YYYY-MM-DD)
        try:
            end_date = datetime.strptime(period, '%Y-%m-%d')
            period_type = "custom_date"
        except ValueError:
            period_type = "standard"

        if period_type == "custom_date":
            conn = DB_CONNECTION
            query_dates = "SELECT DISTINCT Date FROM stocks WHERE Date <= ? ORDER BY Date DESC LIMIT 2"
            dates = pd.read_sql_query(query_dates, conn, params=(end_date.strftime('%Y-%m-%d'),))['Date'].tolist()

            if len(dates) < 2:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Data tidak cukup untuk tanggal {period}. Diperlukan data minimal 2 hari sebelumnya."
                )
                return

            start_date = dates[1]
            end_date = dates[0]
            days = 2

        else:
            if period == "harian":
                days = 2
            elif period == "mingguan":
                days = 5
            else:
                try:
                    days = int(period)
                    if days < 2:
                        raise ValueError("Periode harus minimal 2 hari.")
                except ValueError:
                    await context.bot.send_message(
                        chat_id=update.effective_chat.id,
                        text="Periode tidak valid. Gunakan 'harian', 'mingguan', angka, atau format tanggal YYYY-MM-DD (misal: /ih2 kompas100 2025-03-05)."
                    )
                    return

            conn = DB_CONNECTION
            query_dates = "SELECT DISTINCT Date FROM stocks ORDER BY Date DESC LIMIT ?"
            dates = pd.read_sql_query(query_dates, conn, params=(days,))['Date'].tolist()

            if len(dates) < days:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Data tidak cukup untuk analisis. Diperlukan data minimal {days} hari."
                )
                return

            start_date, end_date = dates[-1], dates[0]

        # Pilih daftar saham berdasarkan indeks
        if index == "kompas100":
            tickers = list(KOMPAS100_STOCKS.keys())
            index_name = "KOMPAS100"
        elif index == "lq45":
            tickers = list(LQ45_STOCKS.keys())
            index_name = "LQ45"
        elif index == "jii70":
            tickers = list(JII70_STOCKS.keys())
            index_name = "JII70"
        elif index == "mbx":
            tickers = list(MBX_STOCKS.keys())
            index_name = "MBX"
        elif index == "issi":
            tickers = list(ISSI_STOCKS.keys())
            index_name = "ISSI"
        else:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Indeks tidak valid. Gunakan 'kompas100', 'lq45', 'jii70', 'mbx', atau 'issi'."
            )
            return

        # Ambil data dari database berdasarkan tanggal
        query = f"""
            SELECT Date, Ticker, CompanyName, Close 
            FROM stocks 
            WHERE Date IN ({','.join(['?']*len([start_date, end_date]))})
            AND Ticker IN ({','.join(['?']*len(tickers))})
            AND Close IS NOT NULL
        """
        params = [start_date, end_date] + tickers
        df = pd.read_sql_query(query, conn, params=params)

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Tidak ada data saham untuk indeks {index_name} pada tanggal yang dipilih."
            )
            return

        # Hitung perubahan harga
        df_pivot = df.pivot(index='Ticker', columns='Date', values='Close')
        df_pivot['CompanyName'] = df.groupby('Ticker')['CompanyName'].first()

        df_pivot['Change (%)'] = (df_pivot[end_date] - df_pivot[start_date]) / df_pivot[start_date] * 100
        df_pivot = df_pivot.dropna(subset=['Change (%)'])
        df_pivot = df_pivot.sort_values(by='Change (%)', ascending=False)

        if df_pivot.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Tidak ada data yang cukup untuk menghitung perubahan harga."
            )
            return

        # Siapkan data untuk heatmap
        heatmap_data = pd.DataFrame(df_pivot['Change (%)'])
        heatmap_data.columns = ['Change (%)']

        # Buat colormap seperti pada gambar (merah ke hijau)
        colors = [
            (1, 0, 0),        # Merah untuk nilai negatif
            (1, 0.5, 0.5),    # Merah muda
            (1, 1, 1),        # Putih untuk nol
            (0.5, 1, 0.5),    # Hijau muda
            (0, 0.5, 0)       # Hijau untuk nilai positif
        ]
        cmap = LinearSegmentedColormap.from_list("custom_cmap", colors, N=256)

        # Tentukan jumlah saham per baris dan kolom
        num_stocks = len(heatmap_data)
        stocks_per_row = 10  # 10 saham per baris
        max_rows_per_image = 42  # Maksimum 42 baris per gambar
        max_stocks_per_image = max_rows_per_image * stocks_per_row  # 420 saham per gambar
        dpi = 150  # Sesuaikan DPI

        # Gunakan direktori sementara untuk menyimpan file
        temp_dir = tempfile.gettempdir()
        logger.info(f"Using temporary directory: {temp_dir}")

        # Bagi heatmap menjadi beberapa bagian jika terlalu banyak saham
        chart_paths = []
        for i in range(0, num_stocks, max_stocks_per_image):
            subset_data = heatmap_data[i:i + max_stocks_per_image]
            subset_num_stocks = len(subset_data)

            # Hitung jumlah baris untuk subset ini
            num_rows = (subset_num_stocks + stocks_per_row - 1) // stocks_per_row

            # Buat grid untuk subset saham
            num_cols = 10
            grid_data = np.full((num_rows, num_cols), np.nan)  # Buat grid kosong
            labels = np.full((num_rows, num_cols), '', dtype=object)  # Label untuk ticker
            changes = np.full((num_rows, num_cols), np.nan)  # Label untuk persentase
            prices = np.full((num_rows, num_cols), np.nan)  # Label untuk harga penutupan

            # Isi grid dengan data
            for idx, (ticker, row) in enumerate(subset_data.iterrows()):
                row_idx = idx // num_cols
                col_idx = idx % num_cols
                grid_data[row_idx, col_idx] = row['Change (%)']
                labels[row_idx, col_idx] = ticker
                changes[row_idx, col_idx] = row['Change (%)']
                # Ambil harga penutupan dari df_pivot
                prices[row_idx, col_idx] = df_pivot.loc[ticker, end_date]

            # Buat heatmap
            fig_height = num_rows * 0.6 + 2  # Sesuaikan tinggi berdasarkan jumlah baris
            plt.figure(figsize=(12, fig_height), dpi=dpi)
            sns.set(font_scale=0.9)  # Sesuaikan ukuran font

            # Buat heatmap dengan data grid
            heatmap = sns.heatmap(
                grid_data,
                annot=labels,
                fmt='s',  # Gunakan string untuk ticker
                cmap=cmap,
                center=0,
                vmin=heatmap_data['Change (%)'].min(),
                vmax=heatmap_data['Change (%)'].max(),
                cbar=False,  # Tidak perlu colorbar
                linewidths=0.5,
                linecolor='gray',
                annot_kws={"size": 8, "color": "black", "weight": "bold"},
                square=False
            )

            # Tambahkan anotasi persentase perubahan dan harga penutupan
            for row in range(num_rows):
                for col in range(num_cols):
                    if not np.isnan(changes[row, col]):
                        # Tambahkan persentase perubahan
                        heatmap.text(
                            col + 0.5, row + 0.7, f"{changes[row, col]:.2f}%",
                            ha='center', va='center', fontsize=7, color='black'
                        )
                        # Tambahkan harga penutupan
                        heatmap.text(
                            col + 0.5, row + 0.9, f"Rp{prices[row, col]:,.0f}",
                            ha='center', va='center', fontsize=7, color='black'
                        )

            # Sesuaikan tata letak
            plt.axis('off')  # Hilangkan sumbu
            part_number = i // max_stocks_per_image + 1
            plt.title(
                f"{index_name} @Bjb_sinyalbot by Bisnis-IT.com/trader - Part {part_number}\n{end_date} {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
                fontsize=10, pad=20, loc='left'
            )

            # Simpan heatmap sebagai gambar di direktori sementara
            chart_filename = f"index_change_heatmap_{index}_{period}_part{part_number}.png"
            chart_path = os.path.join(temp_dir, chart_filename)
            logger.info(f"Saving heatmap to: {chart_path}")
            plt.tight_layout()
            plt.savefig(chart_path, dpi=dpi, bbox_inches='tight')
            plt.close()
            chart_paths.append(chart_path)

        # Kirim setiap bagian heatmap ke pengguna
        for chart_path in chart_paths:
            # Pastikan file benar-benar ada sebelum mengirim
            if not os.path.exists(chart_path):
                logger.error(f"Heatmap file not found after saving: {chart_path}")
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text=f"Gagal membuat heatmap untuk {index_name}. File gambar tidak dapat disimpan."
                )
                return

            logger.info(f"Heatmap file exists: {os.path.exists(chart_path)}")

            # Kirim heatmap ke pengguna
            try:
                logger.info(f"Attempting to send file: {chart_path}")
                with open(chart_path, 'rb') as photo:
                    part_number = chart_paths.index(chart_path) + 1
                    if period_type == "custom_date":
                        await context.bot.send_message(
                            chat_id=update.effective_chat.id,
                            text=f"Heatmap Perubahan Harga {index_name} ({start_date} ke {end_date}) - Part {part_number}:"
                        )
                    else:
                        await context.bot.send_message(
                            chat_id=update.effective_chat.id,
                            text=f"Heatmap Perubahan Harga {index_name} ({period}) - Part {part_number}:"
                        )
                    await context.bot.send_photo(chat_id=update.effective_chat.id, photo=photo)
            except Exception as e:
                logger.error(f"Error sending photo: {str(e)}")
                # Fallback: Kirim sebagai dokumen jika gagal sebagai foto
                try:
                    with open(chart_path, 'rb') as document:
                        await context.bot.send_document(chat_id=update.effective_chat.id, document=document, filename=os.path.basename(chart_path))
                except Exception as doc_e:
                    logger.error(f"Error sending document: {str(doc_e)}")
                    await context.bot.send_message(
                        chat_id=update.effective_chat.id,
                        text=f"Gagal mengirim heatmap untuk {index_name}: {str(doc_e)}"
                    )
                    raise  # Re-raise untuk masuk ke except luar

            # Hapus file sementara setelah dikirim
            try:
                os.remove(chart_path)
                logger.info(f"Deleted temporary file: {chart_path}")
            except Exception as e:
                logger.error(f"Error deleting temporary file {chart_path}: {str(e)}")

        logger.info(f"Heatmap perubahan harga {index_name} untuk periode {period} dikirim")

    except Exception as e:
        logger.error(f"Error in index_change_heatmap_custom: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=f"Terjadi kesalahan saat membuat heatmap perubahan harga {index_name if 'index_name' in locals() else index}: {str(e)}"
        )
                
import pandas as pd
from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import ContextTypes
import logging

async def value_investing_analysis(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        # Cek apakah ada argumen ticker
        args = context.args
        specific_ticker = args[0].upper() if args else None

        # Koneksi ke database
        conn = DB_CONNECTION
        
        # Query dasar untuk mengambil data fundamental
        query = """
            SELECT ticker, name, sector, pe_ratio, pb_ratio, dividend_yield, market_cap, eps, roe, debt_to_equity,
                   dcf_earnings_based, dcf_fcf_based, earnings_power_value, graham_number, median_ps_value,
                   net_current_asset_value, peter_lynch_value, projected_fcf, tangible_book
            FROM fundamental_data 
            WHERE pe_ratio IS NOT NULL 
            AND pb_ratio IS NOT NULL 
            AND dividend_yield IS NOT NULL 
            AND roe IS NOT NULL 
            AND debt_to_equity IS NOT NULL
        """
        if specific_ticker:
            query += f" AND ticker = ?"
            df = pd.read_sql_query(query, conn, params=(specific_ticker,))
        else:
            df = pd.read_sql_query(query, conn)

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"🚫 Tidak ada data fundamental yang tersedia untuk {'saham ' + specific_ticker if specific_ticker else 'analisis value investing'}. Silakan perbarui data dengan /update_fundamental."
            )
            return

        # Konversi kolom numerik ke tipe float, tangani nilai non-numerik
        numeric_columns = ['pe_ratio', 'pb_ratio', 'dividend_yield', 'roe', 'debt_to_equity', 
                           'market_cap', 'eps', 'dcf_earnings_based', 'dcf_fcf_based', 
                           'graham_number', 'peter_lynch_value', 'median_ps_value', 
                           'net_current_asset_value', 'projected_fcf', 'tangible_book']
        for col in numeric_columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

        # Koreksi dividend_yield dan roe jika dalam format desimal (misalnya, 1074.00 menjadi 0.1074)
        df['dividend_yield'] = df['dividend_yield'].apply(lambda x: x / 10000 if x > 100 else x)  # Asumsi data salah skala
        df['roe'] = df['roe'].apply(lambda x: x / 100 if x > 1 else x)  # Asumsi ROE disimpan sebagai persen

        # Hapus baris dengan nilai NaN pada kolom kunci
        df = df.dropna(subset=['pe_ratio', 'pb_ratio', 'dividend_yield', 'roe', 'debt_to_equity'])

        if df.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="⚠️ Data fundamental tidak lengkap setelah pembersihan. Silakan periksa database."
            )
            return

        # Hitung rata-rata P/E ratio per sektor
        sector_pe_avg = df.groupby('sector')['pe_ratio'].mean().to_dict()
        df['sector_pe_avg'] = df['sector'].map(sector_pe_avg)

        # Jika tidak ada ticker spesifik, terapkan kriteria value investing
        if not specific_ticker:
            value_stocks = df[
                (df['pe_ratio'] < df['sector_pe_avg']) &
                (df['pb_ratio'] < 1.5) &
                (df['dividend_yield'] > 0.02) &
                (df['roe'] > 0.10) &
                (df['debt_to_equity'] < 1.0)
            ]
        else:
            value_stocks = df

        if value_stocks.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"🚫 {'Saham ' + specific_ticker + ' tidak memenuhi kriteria value investing.' if specific_ticker else 'Tidak ada saham yang memenuhi kriteria value investing saat ini.'}"
            )
            return

        # Ambil harga saham terbaru
        conn = DB_CONNECTION
        tickers = value_stocks['ticker'].tolist()
        query_price = f"""
            SELECT Ticker, Close 
            FROM stocks 
            WHERE Ticker IN ({','.join(['?']*len(tickers))})
            AND Date = (SELECT MAX(Date) FROM stocks WHERE Ticker = stocks.Ticker)
        """
        df_price = pd.read_sql_query(query_price, conn, params=tickers)

        if df_price.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="⚠️ Tidak ada data harga terbaru untuk saham yang dianalisis."
            )
            return

        # Rename kolom untuk konsistensi
        df_price = df_price.rename(columns={'Ticker': 'ticker'})

        # Gabungkan harga saham terbaru dengan data fundamental
        value_stocks = value_stocks.merge(df_price, on='ticker', how='left')

        # Hitung undervaluation/overvaluation
        value_stocks['dcf_earnings_diff'] = (value_stocks['dcf_earnings_based'] - value_stocks['Close']) / value_stocks['Close'] * 100
        value_stocks['dcf_fcf_diff'] = (value_stocks['dcf_fcf_based'] - value_stocks['Close']) / value_stocks['Close'] * 100
        value_stocks['graham_diff'] = (value_stocks['graham_number'] - value_stocks['Close']) / value_stocks['Close'] * 100
        value_stocks['peter_lynch_diff'] = (value_stocks['peter_lynch_value'] - value_stocks['Close']) / value_stocks['Close'] * 100

        # Filter saham undervalued jika tidak ada ticker spesifik
        if not specific_ticker:
            value_stocks['undervalued_count'] = (
                (value_stocks['dcf_earnings_diff'] > 0).astype(int) +
                (value_stocks['dcf_fcf_diff'] > 0).astype(int) +
                (value_stocks['graham_diff'] > 0).astype(int) +
                (value_stocks['peter_lynch_diff'] > 0).astype(int)
            )
            value_stocks = value_stocks[value_stocks['undervalued_count'] >= 2]

            if value_stocks.empty:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="🚫 Tidak ada saham yang undervalued berdasarkan metrik valuasi tambahan."
                )
                return

            value_stocks = value_stocks.sort_values(by=['undervalued_count', 'pe_ratio'], ascending=[False, True]).head(10)

        # Simpan ke context.user_data
        context.user_data['value_stocks'] = value_stocks

        # Buat pesan dengan emoji dan format angka yang lebih baik
        message = f"📈 *{'Analisis Value Investing untuk ' + specific_ticker if specific_ticker else 'Hasil Analisis Value Investing'}* 📊\n\n"
        for _, row in value_stocks.iterrows():
            ticker = row['ticker']
            name = row['name']
            current_price = row['Close'] if pd.notna(row['Close']) else "N/A"
            market_cap_millions = row['market_cap'] / 1_000_000 if pd.notna(row['market_cap']) else "N/A"
            message += f"🏦 **{ticker} - {name}**\n"
            message += f"📊 Harga Saat Ini: {current_price:.2f}\n"
            message += f"📈 P/E Ratio: {row['pe_ratio']:.2f} (Rata-rata sektor: {row['sector_pe_avg']:.2f})\n"
            message += f"📊 P/B Ratio: {row['pb_ratio']:.2f}\n"
            message += f"💸 Dividend Yield: {row['dividend_yield']*100:.2f}%\n"
            message += f"📈 ROE: {row['roe']*100:.2f}%\n"
            message += f"⚖️ Debt-to-Equity: {row['debt_to_equity']:.2f}\n"
            message += f"💰 Market Cap: {market_cap_millions:,.2f} Juta\n"
            message += f"**💡 Metrik Valuasi:**\n"
            message += f"📊 DCF (Earnings): {row['dcf_earnings_based']:.2f} ({row['dcf_earnings_diff']:.2f}% {'📈 undervalued' if row['dcf_earnings_diff'] > 0 else '📉 overvalued'})\n"
            message += f"📊 DCF (FCF): {row['dcf_fcf_based']:.2f} ({row['dcf_fcf_diff']:.2f}% {'📈 undervalued' if row['dcf_fcf_diff'] > 0 else '📉 overvalued'})\n"
            message += f"📊 Graham Number: {row['graham_number']:.2f} ({row['graham_diff']:.2f}% {'📈 undervalued' if row['graham_diff'] > 0 else '📉 overvalued'})\n"
            message += f"📊 Peter Lynch Value: {row['peter_lynch_value']:.2f} ({row['peter_lynch_diff']:.2f}% {'📈 undervalued' if row['peter_lynch_diff'] > 0 else '📉 overvalued'})\n"
            message += f"📊 Median P/S Value: {row['median_ps_value']:.2f}\n"
            message += f"📊 Net Current Asset Value: {row['net_current_asset_value']:.2f}\n"
            message += f"📊 Projected FCF: {row['projected_fcf']:.2f}\n"
            message += f"📊 Tangible Book Value: {row['tangible_book']:.2f}\n\n"

        # Tambahkan tombol inline
        keyboard = [
            [InlineKeyboardButton(ticker, callback_data=f"value_{ticker}")]
            for ticker in value_stocks['ticker']
        ]
        keyboard.append([InlineKeyboardButton("🔙 Kembali ke Menu", callback_data="back_to_menu")])
        reply_markup = InlineKeyboardMarkup(keyboard)

        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=message,
            parse_mode="Markdown",
            reply_markup=reply_markup
        )
        logger.info("Analisis value investing dikirim")

    except Exception as e:
        logger.error(f"Error in value_investing_analysis: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="⚠️ Terjadi kesalahan saat melakukan analisis value investing."
        )
        
async def ma_crossover(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Mencari crossover MA5, MA20, MA60, dan MA200 berdasarkan indeks dan periode waktu.
    Contoh: /ma_cross lq45 atau /ma_cross lq45 2025-03-07
    """
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        # Validasi input
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan indeks, contoh: /ma_cross lq45 atau /ma_cross lq45 2025-03-07"
            )
            return
        
        # Ambil argumen
        index = context.args[0].lower()
        target_date = context.args[1] if len(context.args) > 1 else None
        logger.info(f"Pencarian MA crossover untuk indeks: {index}, tanggal: {target_date} oleh user {update.effective_user.id}")

        # Validasi indeks
        indices = {
            "lq45": LQ45_STOCKS,
            "kompas100": KOMPAS100_STOCKS,
            "jii70": JII70_STOCKS,
            "issi": ISSI_STOCKS,
            "mbx": MBX_STOCKS
        }
        if index not in indices:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Indeks tidak valid. Gunakan: lq45, kompas100, jii70, issi, atau mbx."
            )
            return
        
        stock_list = indices[index]
        if not stock_list:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Daftar saham {index.upper()} tidak tersedia. Silakan perbarui data."
            )
            return

        # Koneksi ke database
        conn = DB_CONNECTION

        # Siapkan query berdasarkan tanggal
        if target_date:
            try:
                datetime.strptime(target_date, "%Y-%m-%d")
                # Ambil data 60 hari sebelumnya untuk menghitung MA
                query = """
                    SELECT Date, Close 
                    FROM stocks 
                    WHERE Ticker = ? 
                    AND Date <= ? 
                    ORDER BY Date DESC 
                    LIMIT 60
                """
            except ValueError:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Format tanggal salah. Gunakan YYYY-MM-DD, contoh: 2025-03-07"
                )
                return
        else:
            # Ambil data terakhir 60 hari
            query = """
                SELECT Date, Close 
                FROM stocks 
                WHERE Ticker = ? 
                ORDER BY Date DESC 
                LIMIT 60
            """

        # Daftar untuk menyimpan crossover
        crossover_stocks = []
        for ticker in stock_list.keys():
            try:
                if target_date:
                    df = pd.read_sql_query(query, conn, params=(ticker, target_date))
                else:
                    df = pd.read_sql_query(query, conn, params=(ticker,))
                
                if len(df) < 60:  # Pastikan cukup data untuk MA200
                    logger.info(f"Tidak cukup data untuk {ticker} (hanya {len(df)} baris)")
                    continue
                
                # Hitung Moving Averages
                df = df.sort_values('Date')  # Urutkan ascending untuk MA
                df['MA5'] = df['Close'].rolling(window=5, min_periods=5).mean()
                df['MA20'] = df['Close'].rolling(window=20, min_periods=20).mean()
                df['MA60'] = df['Close'].rolling(window=60, min_periods=60).mean()
                df['MA200'] = df['Close'].rolling(window=200, min_periods=60).mean()

                # Ambil dua baris terakhir untuk deteksi crossover
                last_two = df.tail(2)
                if len(last_two) < 2:
                    continue
                
                prev = last_two.iloc[0]
                curr = last_two.iloc[1]
                actual_date = curr['Date']

                # Deteksi crossover
                crossover_info = []
                if prev['MA5'] < prev['MA20'] and curr['MA5'] > curr['MA20']:
                    crossover_info.append("MA5 cross atas MA20 (Bullish)")
                elif prev['MA5'] > prev['MA20'] and curr['MA5'] < curr['MA20']:
                    crossover_info.append("MA5 cross bawah MA20 (Bearish)")
                
                if prev['MA20'] < prev['MA60'] and curr['MA20'] > curr['MA60']:
                    crossover_info.append("MA20 cross atas MA60 (Bullish)")
                elif prev['MA20'] > prev['MA60'] and curr['MA20'] < curr['MA60']:
                    crossover_info.append("MA20 cross bawah MA60 (Bearish)")
                
                if prev['MA60'] < prev['MA200'] and curr['MA60'] > curr['MA200']:
                    crossover_info.append("MA60 cross atas MA200 (Bullish)")
                elif prev['MA60'] > prev['MA200'] and curr['MA60'] < curr['MA200']:
                    crossover_info.append("MA60 cross bawah MA200 (Bearish)")

                if crossover_info:
                    company_name = stock_list.get(ticker, "Nama tidak tersedia")
                    crossover_stocks.append((ticker, company_name, actual_date, crossover_info))

            except Exception as e:
                logger.error(f"Error saat memeriksa MA crossover untuk {ticker}: {str(e)}")
                continue

        # Format pesan
        if not crossover_stocks:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📊 Tidak ada crossover MA ditemukan di saham {index.upper()} {date_text}."
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown"
            )
        else:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📊 *Saham dengan Crossover MA di {index.upper()} {date_text}:*\n\n"
            keyboard = []
            for ticker, company_name, actual_date, crossover_info in crossover_stocks:
                message += f"- {ticker} - {company_name}: {', '.join(crossover_info)}\n"
                callback_data = f"show_ma_chart_{ticker}_{actual_date}"
                keyboard.append([InlineKeyboardButton(f"Grafik {ticker}", callback_data=callback_data)])
            
            reply_markup = InlineKeyboardMarkup(keyboard)
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown",
                reply_markup=reply_markup
            )
        logger.info(f"Pencarian MA crossover untuk indeks {index} selesai")

    except Exception as e:
        logger.error(f"Error in ma_crossover: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mencari crossover MA."
        )    
        
async def ma5_cross(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Mencari saham dengan crossover MA5 (terhadap MA20) berdasarkan indeks dan periode waktu.
    Contoh: /ma5_cross lq45 atau /ma5_cross lq45 2025-03-07
    """
    if not await check_user_access(update, context):
        return
    try:
        if not context.args:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Masukkan indeks, contoh: /ma5_cross lq45 atau /ma5_cross lq45 2025-03-07"
            )
            return
        
        index = context.args[0].lower()
        target_date = context.args[1] if len(context.args) > 1 else None
        logger.info(f"Pencarian MA5 crossover untuk indeks: {index}, tanggal: {target_date} oleh user {update.effective_user.id}")

        indices = {
            "lq45": LQ45_STOCKS,
            "kompas100": KOMPAS100_STOCKS,
            "jii70": JII70_STOCKS,
            "issi": ISSI_STOCKS,
            "mbx": MBX_STOCKS
        }
        if index not in indices:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Indeks tidak valid. Gunakan: lq45, kompas100, jii70, issi, atau mbx."
            )
            return
        
        stock_list = indices[index]
        if not stock_list:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=f"Daftar saham {index.upper()} tidak tersedia. Silakan perbarui data."
            )
            return

        conn = DB_CONNECTION

        if target_date:
            try:
                datetime.strptime(target_date, "%Y-%m-%d")
                query = """
                    SELECT Date, Close 
                    FROM stocks 
                    WHERE Ticker = ? 
                    AND Date <= ? 
                    ORDER BY Date DESC 
                    LIMIT 60
                """
            except ValueError:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Format tanggal salah. Gunakan YYYY-MM-DD, contoh: 2025-03-07"
                )
                return
        else:
            query = """
                SELECT Date, Close 
                FROM stocks 
                WHERE Ticker = ? 
                ORDER BY Date DESC 
                LIMIT 60
            """

        crossover_stocks = []
        for ticker in stock_list.keys():
            try:
                if target_date:
                    df = pd.read_sql_query(query, conn, params=(ticker, target_date))
                else:
                    df = pd.read_sql_query(query, conn, params=(ticker,))
                
                if len(df) < 20:
                    logger.info(f"Tidak cukup data untuk {ticker} (hanya {len(df)} baris)")
                    continue
                
                if df['Close'].isnull().any():
                    logger.info(f"Data untuk {ticker} mengandung nilai NULL pada kolom Close")
                    continue
                
                df = df.sort_values('Date')
                df['MA5'] = df['Close'].rolling(window=5, min_periods=5).mean()
                df['MA20'] = df['Close'].rolling(window=20, min_periods=20).mean()

                # Debugging
                logger.debug(f"MA5 untuk {ticker}: {df['MA5'].tail(5).tolist()}")
                logger.debug(f"MA20 untuk {ticker}: {df['MA20'].tail(5).tolist()}")

                # Deteksi crossover di seluruh periode
                df['Prev_MA5'] = df['MA5'].shift(1)
                df['Prev_MA20'] = df['MA20'].shift(1)
                bullish_cross = (df['MA5'] > df['MA20']) & (df['Prev_MA5'] <= df['Prev_MA20'])
                bearish_cross = (df['MA5'] < df['MA20']) & (df['Prev_MA5'] >= df['Prev_MA20'])

                company_name = stock_list.get(ticker, "Nama tidak tersedia")
                if bullish_cross.any():
                    cross_date = df[bullish_cross]['Date'].iloc[-1]
                    if not target_date or cross_date == target_date:
                        crossover_info = "MA5 cross atas MA20 (Bullish)"
                        crossover_stocks.append((ticker, company_name, cross_date, crossover_info))
                if bearish_cross.any():
                    cross_date = df[bearish_cross]['Date'].iloc[-1]
                    if not target_date or cross_date == target_date:
                        crossover_info = "MA5 cross bawah MA20 (Bearish)"
                        crossover_stocks.append((ticker, company_name, cross_date, crossover_info))

            except Exception as e:
                logger.error(f"Error saat memeriksa MA5 crossover untuk {ticker}: {str(e)}")
                continue

        if not crossover_stocks:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📊 Tidak ada crossover MA5 ditemukan di saham {index.upper()} {date_text}. Mungkin data terbatas atau tidak ada crossover pada periode ini."
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown"
            )
        else:
            date_text = f"pada {target_date}" if target_date else "pada data terakhir"
            message = f"📊 *Saham dengan Crossover MA5 di {index.upper()} {date_text}:*\n\n"
            keyboard = []
            for ticker, company_name, actual_date, crossover_info in crossover_stocks:
                message += f"- {ticker} - {company_name}: {crossover_info} (Tanggal: {actual_date})\n"
                callback_data = f"show_ma5_chart_{ticker}_{actual_date}"
                keyboard.append([InlineKeyboardButton(f"Grafik {ticker}", callback_data=callback_data)])
            
            reply_markup = InlineKeyboardMarkup(keyboard)
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=message,
                parse_mode="Markdown",
                reply_markup=reply_markup
            )
        logger.info(f"Pencarian MA5 crossover untuk indeks {index} selesai")

    except Exception as e:
        logger.error(f"Error in ma5_cross: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text="Terjadi kesalahan saat mencari crossover MA5."
        )

import yfinance as yf
import matplotlib.pyplot as plt
import seaborn as sns
from telegram import Update
from telegram.ext import ContextTypes
import logging
import os
from datetime import datetime, timedelta
import pandas as pd

# Setup logging
logger = logging.getLogger(__name__)

# Cache variables
last_fetched = None
cached_chart_path = None
CACHE_DURATION = timedelta(minutes=5)

async def global_indices(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global last_fetched, cached_chart_path
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    # Check if cached data is still valid
    current_time = datetime.now()
    if last_fetched and cached_chart_path and (current_time - last_fetched) < CACHE_DURATION and os.path.exists(cached_chart_path):
        logger.info("Using cached global indices chart")
        with open(cached_chart_path, 'rb') as photo:
            await context.bot.send_photo(
                chat_id=update.effective_chat.id,
                photo=photo,
                caption="Harga Indeks Global Terbaru"
            )
        return
    
    # Inisialisasi chart_path agar tidak undefined di blok finally
    chart_path = None
    
    try:
        # Daftar indeks global dan simbolnya di Yahoo Finance
        indices = {
            "Dow Jones": "^DJI",          # Standar
            "NASDAQ": "^IXIC",           # Standar
            "S&P 500": "^GSPC",          # Standar
            "IHSG": "^JKSE",            # Standar
            "FTSE 100 (Inggris)": "^FTSE",  # Standar
            "Nikkei": "^N225",
            "KOSPI (Korea)": "^KS11",
            "Shanghai (China)": "000001.SS",
            "BSE Sensex (India)": "^BSESN",
            "DAX (Jerman)": "^GDAXI",
        }

        # Ambil data harga terbaru dan perubahan persentase
        data = []
        for name, symbol in indices.items():
            try:
                ticker = yf.Ticker(symbol)
                # Ambil data 2 hari terakhir untuk menghitung perubahan persentase
                hist = ticker.history(period="2d")
                if len(hist) >= 2:  # Pastikan ada data untuk 2 hari
                    last_price = hist['Close'].iloc[-1]
                    prev_price = hist['Close'].iloc[-2]
                    change_percent = (last_price - prev_price) / prev_price * 100
                    data.append({
                        "Index": name,
                        "Last Price": last_price,
                        "Change (%)": change_percent
                    })
                else:
                    logger.warning(f"Tidak dapat mengambil data untuk {name} ({symbol})")
                    continue  # Lewati indeks ini jika data tidak tersedia
            except Exception as e:
                logger.warning(f"Gagal mengambil data untuk {name} ({symbol}): {str(e)}")
                continue  # Lewati indeks ini jika terjadi error

        # Buat DataFrame untuk visualisasi
        if len(data) < 5:  # Minimal 5 indeks untuk menampilkan grafik
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Data indeks global tidak cukup (kurang dari 5 indeks tersedia). Silakan coba lagi nanti."
            )
            return

        df = pd.DataFrame(data)

        # Tentukan warna berdasarkan perubahan persentase
        colors = ['green' if change >= 0 else 'red' for change in df['Change (%)']]

        # Buat grafik menggunakan matplotlib
        plt.figure(figsize=(12, 8))
        bars = plt.barh(df['Index'], df['Last Price'], color=colors)

        # Tambahkan label harga dan perubahan persentase di ujung bar
        for i, bar in enumerate(bars):
            width = bar.get_width()
            change = df['Change (%)'].iloc[i]
            # Perbaiki pemanggilan plt.text() dengan menghapus argumen 'x' yang berlebihan
            plt.text(width + 500, bar.get_y() + bar.get_height()/2, 
                     f"{width:,.2f} ({change:+.2f}%)", 
                     ha='left', va='center', fontsize=10)

        # Sesuaikan tata letak grafik
        plt.title("Harga Indeks Global Terbaru", fontsize=14, pad=20)
        plt.xlabel("Harga Penutupan", fontsize=12)
        plt.ylabel("Indeks", fontsize=12)

        # Tambahkan label branding di bagian bawah grafik
        plt.text(0, -0.5, "Created @Bjb_SinyalBot Bisnis-IT.com/trader", 
                 ha='left', va='bottom', fontsize=10, color='gray', 
                 transform=plt.gca().transAxes)

        plt.tight_layout()

        # Simpan grafik ke file sementara
        chart_path = "global_indices_chart.png"
        plt.savefig(chart_path, dpi=150, bbox_inches='tight')
        plt.close()

        # Kirim grafik ke pengguna
        with open(chart_path, 'rb') as photo:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Harga Indeks Global Terbaru:"
            )
            await context.bot.send_photo(
                chat_id=update.effective_chat.id,
                photo=photo
            )

        # Update cache
        last_fetched = current_time
        cached_chart_path = chart_path

        logger.info("Global indices chart sent successfully")

    except Exception as e:
        logger.error(f"Error in global_indices: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=f"Terjadi kesalahan saat mengambil data indeks global: {str(e)}"
        )

    finally:
        # Hapus file sementara jika tidak digunakan untuk cache
        if chart_path and cached_chart_path != chart_path and os.path.exists(chart_path):
            try:
                os.remove(chart_path)
                logger.info(f"Deleted temporary file: {chart_path}")
            except Exception as e:
                logger.error(f"Error deleting temporary file {chart_path}: {str(e)}")
                
async def commodity_prices(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        # Daftar simbol komoditas yang akan diambil
        commodities = {
            "Gold": "GC=F",
            "Silver": "SI=F",
            "Copper": "HG=F",
            "Crude Oil WTI": "CL=F",
            "Brent Crude": "BZ=F",
            "Natural Gas": "NG=F",
            "Coal": "MTF=F",
            "Aluminium": "ALI=F",
            "Platinum": "PL=F",
            "Palladium": "PA=F",
            "Corn": "ZC=F",
            "Wheat": "ZW=F",
            "Soybeans": "ZS=F",
            "Sugar": "SB=F",
            "Cotton": "CT=F",
        }

        # List untuk menyimpan hasil yang berhasil
        results = []

        # Iterasi melalui setiap komoditas
        for name, symbol in commodities.items():
            try:
                ticker = yf.Ticker(symbol)
                # Ambil data untuk 5 hari terakhir untuk memastikan cukup data
                data = ticker.history(period="5d")
                
                if data.empty:
                    logger.warning(f"Tidak dapat mengambil data untuk {name} ({symbol}): Data kosong")
                    continue
                
                # Ambil harga penutupan terbaru
                latest_close = data['Close'][-1] if not data['Close'].empty else None
                if latest_close is None:
                    logger.warning(f"Tidak dapat mengambil harga penutupan terbaru untuk {name} ({symbol})")
                    continue
                
                # Format harga
                latest_close = round(latest_close, 2)
                
                # Coba hitung persentase perubahan jika ada cukup data
                change_str = ""
                if len(data) >= 2:
                    previous_close = data['Close'][-2]  # Harga sebelumnya
                    if previous_close is not None and previous_close != 0:
                        change_percent = ((latest_close - previous_close) / previous_close) * 100
                        change_percent = round(change_percent, 2)
                        # Tentukan emoji berdasarkan perubahan
                        if change_percent > 0:
                            change_str = f"🟢 +{change_percent}%"
                        elif change_percent < 0:
                            change_str = f"🔴 {change_percent}%"
                        else:
                            change_str = "⚪ 0.00%"
                    else:
                        change_str = "⚪ N/A"
                else:
                    change_str = "⚪ N/A"
                
                # Tambahkan ke hasil, meskipun tidak ada persentase perubahan
                results.append(f"{name}: ${latest_close} {change_str}")
                
            except Exception as e:
                logger.warning(f"Tidak dapat mengambil data untuk {name} ({symbol}): {str(e)}")
                continue

        # Bangun pesan respons
        if results:
            message = "📈 *Harga Komoditas Terkini*\n\n"
            message += "\n".join(results)
        else:
            message = (
                "📈 *Harga Komoditas Terkini*\n\n"
                "Maaf, tidak ada data komoditas yang tersedia saat ini. "
                "Silakan coba lagi nanti."
            )

        # Kirim pesan ke pengguna
        await update.message.reply_text(
            message,
            parse_mode="Markdown"
        )

    except Exception as e:
        logger.error(f"Error di commodity_prices: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data komoditas. Silakan coba lagi nanti.",
            parse_mode="Markdown"
        )

import yfinance as yf
import pandas as pd
import matplotlib.pyplot as plt
import os
import logging
from telegram import Update
from telegram.ext import ContextTypes

async def major_currencies(update: Update, context: ContextTypes.DEFAULT_TYPE):
    # Inisialisasi chart_path agar tidak undefined di blok finally
    chart_path = None
    # Periksa akses pengguna
    if not await check_user_access(update, context):
        return  # Hentikan eksekusi jika akses ditolak
    try:
        # Daftar pasangan mata uang utama dan simbolnya di Yahoo Finance
        currencies = {
            "EUR/USD": "EURUSD=X",  # Euro terhadap Dolar AS
            "GBP/USD": "GBPUSD=X",  # Pound Sterling terhadap Dolar AS
            "USD/JPY": "USDJPY=X",  # Dolar AS terhadap Yen Jepang
            "USD/CAD": "USDCAD=X",  # Dolar AS terhadap Dolar Kanada
            "USD/CHF": "USDCHF=X",  # Dolar AS terhadap Franc Swiss
            "USD/IDR": "IDR=X",    # Dolar AS terhadap Rupiah Indonesia
            "USD/CNY": "CNY=X",    # Dolar AS terhadap Yuan Tiongkok
            "USD/RUB": "RUB=X",    # Dolar AS terhadap Rubel Rusia
            "USD/AUD": "AUDUSD=X", # Dolar AS terhadap Dolar Australia (kebalikan dari AUD/USD)
            "USD/INR": "INR=X",    # Dolar AS terhadap Rupee India
        }

        # Ambil data harga terbaru dan perubahan persentase
        data = []
        for name, symbol in currencies.items():
            try:
                ticker = yf.Ticker(symbol)
                # Ambil data 2 hari terakhir untuk menghitung perubahan persentase
                hist = ticker.history(period="2d")
                if len(hist) >= 2:  # Pastikan ada data untuk 2 hari
                    last_price = hist['Close'].iloc[-1]
                    prev_price = hist['Close'].iloc[-2]
                    change_percent = (last_price - prev_price) / prev_price * 100
                    data.append({
                        "Currency": name,
                        "Last Price": last_price,
                        "Change (%)": change_percent
                    })
                else:
                    logger.warning(f"Tidak dapat mengambil data untuk {name} ({symbol})")
                    continue  # Lewati pasangan mata uang ini jika data tidak tersedia
            except Exception as e:
                logger.warning(f"Gagal mengambil data untuk {name} ({symbol}): {str(e)}")
                continue  # Lewati pasangan mata uang ini jika terjadi error

        # Buat DataFrame untuk visualisasi
        if not data:  # Jika tidak ada data sama sekali
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Gagal mengambil data untuk semua pasangan mata uang. Silakan coba lagi nanti."
            )
            return

        df = pd.DataFrame(data)

        # Tentukan warna berdasarkan perubahan persentase
        colors = ['green' if change >= 0 else 'red' for change in df['Change (%)']]

        # Buat grafik menggunakan matplotlib
        plt.figure(figsize=(12, 8))
        bars = plt.barh(df['Currency'], df['Last Price'], color=colors)

        # Tambahkan label harga dan perubahan persentase di ujung bar
        for i, bar in enumerate(bars):
            width = bar.get_width()
            change = df['Change (%)'].iloc[i]
            currency = df['Currency'].iloc[i]
            # Format khusus berdasarkan pasangan mata uang
            if currency in ["USD/IDR", "USD/INR", "USD/RUB"]:
                # Untuk mata uang dengan nilai besar (IDR, INR, RUB)
                label = f"{width:,.2f} ({change:+.2f}%)"
            elif currency == "USD/CNY":
                # Untuk CNY, gunakan 4 desimal karena nilainya sedang
                label = f"{width:.4f} ({change:+.2f}%)"
            else:
                # Untuk mata uang lain (EUR/USD, USD/JPY, dll.), gunakan 4 desimal
                label = f"{width:.4f} ({change:+.2f}%)"
            plt.text(width + max(width * 0.05, 0.01), bar.get_y() + bar.get_height()/2, 
                     label, 
                     ha='left', va='center', fontsize=10)

        # Sesuaikan tata letak grafik
        plt.title("Harga Major Currencies Terbaru", fontsize=14, pad=20)
        plt.xlabel("Nilai Tukar", fontsize=12)
        plt.ylabel("Pasangan Mata Uang", fontsize=12)

        # Tambahkan label branding di bagian bawah grafik
        plt.text(0, -0.5, "Created @Bjb_SinyalBot Bisnis-IT.com/trader", 
                 ha='left', va='bottom', fontsize=10, color='gray', 
                 transform=plt.gca().transAxes)

        plt.tight_layout()

        # Simpan grafik ke file sementara
        chart_path = "major_currencies_chart.png"
        plt.savefig(chart_path, dpi=150, bbox_inches='tight')
        plt.close()

        # Kirim grafik ke pengguna
        with open(chart_path, 'rb') as photo:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Harga Major Currencies Terbaru:"
            )
            await context.bot.send_photo(
                chat_id=update.effective_chat.id,
                photo=photo
            )

        logger.info("Major currencies chart sent successfully")

    except Exception as e:
        logger.error(f"Error in major_currencies: {str(e)}")
        await context.bot.send_message(
            chat_id=update.effective_chat.id,
            text=f"Terjadi kesalahan saat mengambil data major currencies: {str(e)}"
        )

    finally:
        # Hapus file sementara jika ada
        if chart_path and os.path.exists(chart_path):
            try:
                os.remove(chart_path)
                logger.info(f"Deleted temporary file: {chart_path}")
            except Exception as e:
                logger.error(f"Error deleting temporary file {chart_path}: {str(e)}")

                
