import requests
import time
from datetime import datetime
import sqlite3
from telegram import Update, ReplyKeyboardMarkup, ReplyKeyboardRemove

# ... (impor lainnya seperti yfinance, matplotlib, pandas, dll. yang sudah ada di bot.py)

# API Key CoinMarketCap (diambil dari variabel lingkungan)
CMC_API_KEY = os.getenv("COINMARKETCAP_API_KEY")
CMC_URL = 'https://pro-api.coinmarketcap.com/v1/cryptocurrency/listings/latest'
CMC_HEADERS = {
    'Accepts': 'application/json',
    'X-CMC_PRO_API_KEY': CMC_API_KEY,
}

# Nama database
DB_NAME = "cmc_data.db"

# Fungsi untuk mendapatkan data dari CoinMarketCap API
def get_crypto_data(start, limit):
    params = {
        'start': str(start),
        'limit': str(limit),
        'convert': 'USD'
    }
    response = requests.get(CMC_URL, headers=CMC_HEADERS, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        logger.error(f"Error fetching data from CoinMarketCap at start={start}: {response.status_code}")
        return None

# Fungsi untuk memproses data koin dinamis
def process_coins_data(all_coins, timestamp):
    processed_data = []
    for coin in all_coins:
        quote = coin['quote']['USD']
        processed_data.append({
            'timestamp': timestamp,
            'symbol': coin['symbol'],
            'name': coin['name'],
            'price_usd': quote['price'],
            'volume_24h': quote['volume_24h'],
            'volume_change_24h': quote['volume_change_24h'],
            'percent_change_1h': quote['percent_change_1h'],
            'percent_change_24h': quote['percent_change_24h'],
            'percent_change_7d': quote['percent_change_7d'],
            'percent_change_30d': quote['percent_change_30d'],
            'percent_change_60d': quote['percent_change_60d'],
            'percent_change_90d': quote['percent_change_90d'],
            'market_cap': quote['market_cap'],
            'market_cap_dominance': quote['market_cap_dominance'],
            'fully_diluted_market_cap': quote['fully_diluted_market_cap'],
            'quote_last_updated': quote['last_updated'],
            'circulating_supply': coin['circulating_supply'],
            'slug': coin['slug'],
            'cmc_rank': coin['cmc_rank']
        })
    return processed_data

# Fungsi untuk memproses data koin statis (termasuk website)
def process_coin_metadata(all_coins):
    metadata = []
    for coin in all_coins:
        website = f"https://coinmarketcap.com/currencies/{coin['slug']}/"
        metadata.append({
            'symbol': coin['symbol'],
            'name': coin['name'],
            'slug': coin['slug'],
            'website': website,
            'date_added': coin['date_added']
        })
    return metadata

# Fungsi untuk menyimpan data ke SQLite
def save_to_sqlite(total_coins, all_coins, timestamp):
    conn = sqlite3.connect(DB_NAME)
    cursor = conn.cursor()

    # Tabel metadata
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS metadata (
            timestamp TEXT,
            total_coins INTEGER,
            coins_scanned INTEGER
        )
    ''')

    # Tabel coins
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS coins (
            timestamp TEXT,
            symbol TEXT,
            name TEXT,
            price_usd REAL,
            volume_24h REAL,
            volume_change_24h REAL,
            percent_change_1h REAL,
            percent_change_24h REAL,
            percent_change_7d REAL,
            percent_change_30d REAL,
            percent_change_60d REAL,
            percent_change_90d REAL,
            market_cap REAL,
            market_cap_dominance REAL,
            fully_diluted_market_cap REAL,
            quote_last_updated TEXT,
            circulating_supply REAL,
            slug TEXT,
            cmc_rank INTEGER
        )
    ''')

    # Tabel coin_metadata
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS coin_metadata (
            symbol TEXT PRIMARY KEY,
            name TEXT,
            slug TEXT,
            website TEXT,
            date_added TEXT
        )
    ''')

    # Simpan metadata
    cursor.execute('''
        INSERT INTO metadata (timestamp, total_coins, coins_scanned)
        VALUES (?, ?, ?)
    ''', (timestamp, total_coins, len(all_coins)))

    # Simpan data koin dinamis
    processed_data = process_coins_data(all_coins, timestamp)
    cursor.executemany('''
        INSERT INTO coins (
            timestamp, symbol, name, price_usd, volume_24h, volume_change_24h,
            percent_change_1h, percent_change_24h, percent_change_7d,
            percent_change_30d, percent_change_60d, percent_change_90d,
            market_cap, market_cap_dominance, fully_diluted_market_cap,
            quote_last_updated, circulating_supply, slug, cmc_rank
        ) VALUES (
            :timestamp, :symbol, :name, :price_usd, :volume_24h, :volume_change_24h,
            :percent_change_1h, :percent_change_24h, :percent_change_7d,
            :percent_change_30d, :percent_change_60d, :percent_change_90d,
            :market_cap, :market_cap_dominance, :fully_diluted_market_cap,
            :quote_last_updated, :circulating_supply, :slug, :cmc_rank
        )
    ''', processed_data)

    # Simpan atau perbarui data statis
    coin_metadata = process_coin_metadata(all_coins)
    cursor.executemany('''
        INSERT OR REPLACE INTO coin_metadata (symbol, name, slug, website, date_added)
        VALUES (:symbol, :name, :slug, :website, :date_added)
    ''', coin_metadata)

    conn.commit()
    conn.close()

from datetime import datetime, timedelta
import pandas as pd
import sqlite3
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap
import seaborn as sns
import numpy as np
from telegram import Update
from telegram.ext import ContextTypes
import os
import logging

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

async def price_graph(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Menampilkan kalender perubahan harga saham dalam persentase (naik/turun) sebagai gambar dengan harga closing.
    Format: /pg <kode_saham> [periode: '1month' atau jumlah hari kerja, default '1month']
    """
    try:
        # Validasi input
        if len(context.args) < 1:
            await update.message.reply_text(
                "Gunakan: /pg <kode_saham> [periode]\nContoh: /pg BJBR 1month atau /pg BJBR 20",
                parse_mode="Markdown"
            )
            return

        ticker = context.args[0].upper()
        period_input = context.args[1] if len(context.args) > 1 else "1month"

        # Tentukan periode
        if period_input.lower() == "1month":
            period_days = 31  # Ambil 1 bulan penuh, akan difilter ke hari kerja
        else:
            try:
                period_days = int(period_input)
                if period_days < 1:
                    raise ValueError("Periode harus lebih dari 0.")
            except ValueError:
                await update.message.reply_text(
                    "Periode tidak valid. Gunakan '1month' atau jumlah hari kerja (contoh: 20).",
                    parse_mode="Markdown"
                )
                return

        # Ambil semua ticker yang ada di database untuk validasi
        conn = sqlite3.connect(DATABASE_PATH)
        query_tickers = "SELECT DISTINCT Ticker FROM stocks"
        valid_tickers_df = pd.read_sql_query(query_tickers, conn)
        valid_tickers = set(valid_tickers_df['Ticker'].str.upper())

        if ticker not in valid_tickers:
            await update.message.reply_text(
                f"Kode saham {ticker} tidak ditemukan di database. Ticker yang tersedia: {', '.join(sorted(valid_tickers))[:10]}...",
                parse_mode="Markdown"
            )
            conn.close()
            return

        # Ambil data dari database termasuk harga closing
        end_date = datetime.now()
        start_date = end_date - timedelta(days=period_days)

        query = """
            SELECT Date, Close 
            FROM stocks 
            WHERE Ticker = ? AND Date BETWEEN ? AND ? AND Close IS NOT NULL
            ORDER BY Date ASC
        """
        logger.info(f"Executing query: Ticker={ticker}, Start={start_date.strftime('%Y-%m-%d')}, End={end_date.strftime('%Y-%m-%d')}")
        df = pd.read_sql_query(query, conn, params=(ticker, start_date.strftime('%Y-%m-%d'), end_date.strftime('%Y-%m-%d')))

        if df.empty:
            # Jika tidak ada data untuk periode tersebut, ambil data terbaru yang tersedia
            query_fallback = """
                SELECT Date, Close 
                FROM stocks 
                WHERE Ticker = ? AND Close IS NOT NULL
                ORDER BY Date DESC
                LIMIT 20
            """
            logger.info(f"Fallback query: Ticker={ticker}")
            df = pd.read_sql_query(query_fallback, conn, params=(ticker,))

            if df.empty:
                await update.message.reply_text(
                    f"Tidak ada data untuk saham {ticker} di database.",
                    parse_mode="Markdown"
                )
                conn.close()
                return
            else:
                logger.info(f"Fallback data retrieved: {len(df)} rows")

        conn.close()

        # Hitung perubahan persentase harian
        df['Date'] = pd.to_datetime(df['Date'])
        df = df.sort_values('Date')
        df['Prev_Close'] = df['Close'].shift(1)
        df['Change (%)'] = (df['Close'] - df['Prev_Close']) / df['Prev_Close'] * 100
        df = df.dropna(subset=['Change (%)'])  # Hapus baris tanpa perubahan (hari pertama)

        # Filter hanya hari kerja (Senin-Jumat) dan batasi ke 20 hari kerja jika periode '1month'
        df = df[df['Date'].dt.weekday < 5]  # Hanya Senin-Jumat
        if period_input.lower() == "1month":
            working_days = df.tail(20)  # Ambil 20 hari kerja terakhir
        else:
            working_days = df.tail(period_days)  # Ambil sesuai input pengguna

        if working_days.empty:
            await update.message.reply_text(
                f"Tidak ada cukup data untuk saham {ticker} untuk menghitung perubahan harga. Minimal 2 hari data diperlukan.",
                parse_mode="Markdown"
            )
            return

        # Tentukan rentang tanggal untuk kalender (hanya hari kerja)
        min_date = working_days['Date'].min()
        max_date = working_days['Date'].max()
        all_dates = []
        current_date = min_date
        while current_date <= max_date:
            if current_date.weekday() < 5:  # Hanya Senin-Jumat
                all_dates.append(current_date)
            current_date += timedelta(days=1)

        # Jika tidak ada cukup hari untuk membuat kalender, buat minimal 1 minggu
        if not all_dates:
            all_dates = [min_date]

        # Siapkan data untuk kalender
        calendar_data = {row['Date']: row['Change (%)'] for _, row in working_days.iterrows()}
        closing_prices = {row['Date']: row['Close'] for _, row in working_days.iterrows()}

        # Grouping data berdasarkan bulan
        calendar_by_month = {}
        for date in all_dates:
            month_key = date.strftime('%b')  # Misalnya 'Jun' untuk June
            if month_key not in calendar_by_month:
                calendar_by_month[month_key] = []
            calendar_by_month[month_key].append(date)

        # Siapkan data untuk heatmap
        weeks = []
        current_week = [None] * 5  # Inisialisasi minggu dengan 5 slot (Senin-Jumat)
        for date in all_dates:
            weekday = date.weekday()  # 0=Senin, 4=Jumat
            if weekday == 0 and any(current_week):  # Senin dan minggu sebelumnya tidak kosong
                weeks.append(current_week)
                current_week = [None] * 5
            current_week[weekday] = date
        if any(current_week):  # Tambahkan minggu terakhir jika ada data
            weeks.append(current_week)

        # Jika tidak ada minggu (data sangat sedikit), buat minggu minimal
        if not weeks:
            current_week = [None] * 5
            weekday = min_date.weekday()
            current_week[weekday] = min_date
            weeks.append(current_week)

        # Log untuk debugging
        logger.info(f"Weeks created: {weeks}")

        # Buat heatmap data dan labels dengan memastikan konsistensi
        heatmap_data = []
        heatmap_labels = []
        for week in weeks:
            week_data = [0] * 5  # Inisialisasi dengan 5 elemen (Senin-Jumat)
            week_labels = [""] * 5  # Inisialisasi dengan 5 elemen
            for i, date in enumerate(week):
                if date is None:
                    week_data[i] = 0
                    week_labels[i] = ""
                elif date not in calendar_data:
                    week_data[i] = 0
                    week_labels[i] = f"{date.day}\n(Libur)"
                else:
                    change = calendar_data[date]
                    close_price = closing_prices[date]
                    week_data[i] = change
                    week_labels[i] = f"{date.day}\n{change:+.2f}%\nClose: {close_price:.2f}"
            heatmap_data.append(week_data)
            heatmap_labels.append(week_labels)

        # Log untuk debugging
        logger.info(f"Heatmap data: {heatmap_data}")
        logger.info(f"Heatmap labels: {heatmap_labels}")

        # Konversi ke numpy array
        heatmap_data = np.array(heatmap_data, dtype=float)
        heatmap_labels = np.array(heatmap_labels, dtype=str)

        # Pastikan bentuk array benar
        if heatmap_data.shape[1] != 5 or heatmap_labels.shape[1] != 5:
            raise ValueError(f"Heatmap data atau labels tidak memiliki 5 kolom: data shape={heatmap_data.shape}, labels shape={heatmap_labels.shape}")

        # Buat colormap (merah ke hijau, abu-abu untuk 0)
        colors = [
            (1, 0, 0),        # Merah untuk negatif
            (1, 0.5, 0.5),    # Transisi
            (0.7, 0.7, 0.7),  # Abu-abu untuk 0 (libur)
            (0.5, 1, 0.5),    # Transisi
            (0, 0.5, 0)       # Hijau untuk positif
        ]
        cmap = LinearSegmentedColormap.from_list("custom_cmap", colors, N=256)

        # Buat gambar kalender
        plt.figure(figsize=(6, len(weeks) * 0.8), dpi=150)
        sns.set(font_scale=0.8)
        heatmap = sns.heatmap(
            heatmap_data,
            annot=heatmap_labels,
            fmt="s",
            cmap=cmap,
            center=0,
            vmin=heatmap_data.min() if heatmap_data.size > 0 else -1,
            vmax=heatmap_data.max() if heatmap_data.size > 0 else 1,
            cbar=False,
            linewidths=0.5,
            linecolor='gray',
            xticklabels=["Mon", "Tue", "Wed", "Thu", "Fri"],
            yticklabels=[date.strftime('%b') if date and date in all_dates else "" for date in [week[0] if week[0] else None for week in weeks]]
        )

        # Atur rotasi label sumbu Y
        heatmap.set_yticklabels(heatmap.get_yticklabels(), rotation=90, va='center')

        # Tambahkan judul
        plt.title(f"Kalender Perubahan Harga {ticker} by bisnis-it.com/saham", fontsize=12, pad=20)
        plt.xlabel("Hari", fontsize=10)
        plt.ylabel("Bulan", fontsize=10)

        # Simpan gambar
        chart_path = f"price_graph_{ticker}.png"
        plt.tight_layout()
        plt.savefig(chart_path, dpi=150, bbox_inches='tight')
        plt.close()

        # Kirim gambar ke pengguna
        try:
            with open(chart_path, 'rb') as photo:
                await context.bot.send_photo(
                    chat_id=update.effective_chat.id,
                    photo=photo,
                    caption=f"Kalender Perubahan Harga {ticker}\n🟩 = Naik | 🟥 = Turun | ⬜ = Libur by bisnis-it.com/saham"
                )
        except Exception as e:
            logger.error(f"Error sending photo: {str(e)}")
            with open(chart_path, 'rb') as document:
                await context.bot.send_document(
                    chat_id=update.effective_chat.id,
                    document=document,
                    filename=chart_path
                )

        # Hapus file sementara
        os.remove(chart_path)

    except Exception as e:
        logger.error(f"Error in price_graph: {str(e)}")
        await update.message.reply_text(
            f"Terjadi kesalahan saat membuat kalender perubahan harga: {str(e)}",
            parse_mode="Markdown"
        )
        
async def set_alert(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    args = context.args
    if len(args) != 3:
        await update.message.reply_text("Gunakan: /sa <symbol> <harga> <above/below>")
        return
    symbol, price, alert_type = args
    if alert_type.lower() not in ["above", "below"]:
        await update.message.reply_text("Tipe alert harus 'above' atau 'below'.")
        return
    try:
        price = float(price)
        conn = sqlite3.connect(DATABASE_PATH)
        c = conn.cursor()
        c.execute("INSERT INTO price_alerts (user_id, stock_symbol, price_threshold, alert_type) VALUES (?, ?, ?, ?)",
                 (user_id, symbol.upper(), price, alert_type.lower()))
        conn.commit()
        logger.info(f"Alert ditambahkan untuk user {user_id}: {symbol} {alert_type} {price}")
        await update.message.reply_text(f"Alert ditambahkan: {symbol} {alert_type} Rp {price:,.2f}")
    except Exception as e:
        logger.error(f"Error in sa: {str(e)}")
        await update.message.reply_text("Gagal menambah alert. Silakan coba lagi.")
    finally:
        conn.close()
        
async def view_alerts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    try:
        conn = sqlite3.connect(DATABASE_PATH)
        c = conn.cursor()
        c.execute("SELECT stock_symbol, price_threshold, alert_type FROM price_alerts WHERE user_id = ?", (user_id,))
        alerts = c.fetchall()
        if not alerts:
            await update.message.reply_text("Anda belum memiliki alert.")
            return
        message = "Daftar Alert Anda:\n\n"
        for symbol, price, alert_type in alerts:
            message += f"{symbol} {alert_type} Rp {price:,.2f}\n"
        logger.info(f"Menampilkan alert untuk user {user_id}")
        await update.message.reply_text(message)
    except Exception as e:
        logger.error(f"Error in va: {str(e)}")
        await update.message.reply_text("Gagal menampilkan alert. Silakan coba lagi.")
    finally:
        conn.close()                

from telegram import Update
from telegram.ext import ContextTypes, CommandHandler
import sqlite3
import pandas as pd
import logging

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

async def tp(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Tambah saham ke portofolio. Format: /tp <ticker> <quantity> <buy_price>"""
    try:
        user_id = update.effective_user.id
        if len(context.args) != 3:
            await update.message.reply_text(
                "Gunakan: /tp <ticker> <qty> <buy_price>\nContoh: /tp BJBR 100 9000",
                parse_mode="Markdown"
            )
            return

        ticker = context.args[0].upper()
        quantity = int(context.args[1])
        buy_price = float(context.args[2])

        # Validasi ticker
        conn = sqlite3.connect(DATABASE_PATH)
        query = "SELECT DISTINCT Ticker FROM stocks WHERE Ticker = ?"
        df = pd.read_sql_query(query, conn, params=(ticker,))
        if df.empty:
            await update.message.reply_text(
                f"Kode saham {ticker} tidak ditemukan.",
                parse_mode="Markdown"
            )
            conn.close()
            return

        # Simpan ke database
        cursor = conn.cursor()
        cursor.execute('''
            INSERT OR REPLACE INTO portfolio (user_id, ticker, quantity, buy_price)
            VALUES (?, ?, ?, ?)
        ''', (user_id, ticker, quantity, buy_price))
        conn.commit()
        conn.close()

        await update.message.reply_text(
            f"Added {quantity} lots {ticker} @ Rp {buy_price:,.2f}.",
            parse_mode="Markdown"
        )

    except Exception as e:
        logger.error(f"Error in tp: {str(e)}")
        await update.message.reply_text(
            f"Error: {str(e)}",
            parse_mode="Markdown"
        )

import sqlite3
import pandas as pd
from telegram import Update
from telegram.ext import ContextTypes
import logging
from PIL import Image, ImageDraw, ImageFont
import io

# Logging setup (sesuaikan dengan kode bot kamu)
logger = logging.getLogger(__name__)

# Path ke database (sesuaikan dengan path di Render)
DATABASE_PATH = "stock_data.db"  # Simpan di direktori yang sama dengan bot.py

async def vp(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Lihat portofolio pengguna. Format: /vp"""
    try:
        user_id = update.effective_user.id
        conn = sqlite3.connect(DATABASE_PATH)

        # Ambil data portofolio
        query = "SELECT ticker, quantity, buy_price FROM portfolio WHERE user_id = ?"
        df = pd.read_sql_query(query, conn, params=(user_id,))

        if df.empty:
            await update.message.reply_text(
                "Portofolio kosong. Gunakan /tp untuk menambah.",
                parse_mode="Markdown"
            )
            conn.close()
            return

        # Hitung performa dan siapkan data untuk tabel
        table_data = []
        total_val = 0
        total_buy = 0
        total_lots = 0
        lot_size = 100  # 1 lot = 100 lembar

        for _, row in df.iterrows():
            ticker = row['ticker']
            qty = row['quantity']
            buy_price = row['buy_price']

            # Ambil harga terbaru
            query_price = """
                SELECT Close FROM stocks 
                WHERE Ticker = ? AND Close IS NOT NULL
                ORDER BY Date DESC LIMIT 1
            """
            price_df = pd.read_sql_query(query_price, conn, params=(ticker,))
            curr_price = price_df['Close'].iloc[0] if not price_df.empty else 0

            # Hitung nilai (1 lot = 100 lembar)
            buy_val = qty * lot_size * buy_price
            curr_val = qty * lot_size * curr_price
            perf = ((curr_val - buy_val) / buy_val * 100) if buy_val != 0 else 0
            selisih = curr_val - buy_val

            total_buy += buy_val
            total_val += curr_val
            total_lots += qty

            # Tambahkan data ke tabel
            table_data.append([
                ticker,
                f"{qty}",  # Kolom Lots (jumlah lot)
                f"{buy_price:,.0f}",  # Kolom Buy (harga beli)
                f"{curr_price:,.0f}",  # Kolom Current (harga saat ini)
                f"{'🟢' if perf >= 0 else '🔴'} {perf:+.1f}%",
                f"Rp {selisih:,.0f}"
            ])

        # Hitung total
        total_perf = ((total_val - total_buy) / total_buy * 100) if total_buy != 0 else 0
        avg_buy_price = total_buy / total_lots if total_lots != 0 else 0
        avg_curr_price = total_val / total_lots if total_lots != 0 else 0
        selisih_total = total_val - total_buy

        conn.close()

        # Buat gambar tabel
        headers = ["Saham", "Lots", "Buy", "Current", "performansi", "selisih"]
        img = create_table_image(headers, table_data, total_lots, avg_buy_price, avg_curr_price, total_buy, total_val, selisih_total, total_perf)

        # Simpan gambar ke buffer
        buffer = io.BytesIO()
        img.save(buffer, format="PNG")
        buffer.seek(0)

        # Kirim gambar ke Telegram
        await update.message.reply_photo(photo=buffer, caption="📊 *Portofolio*", parse_mode="Markdown")

    except Exception as e:
        logger.error(f"Error in vp: {str(e)}")
        await update.message.reply_text(
            f"Error: {str(e)}",
            parse_mode="Markdown"
        )

def create_table_image(headers, data, total_lots, avg_buy_price, avg_curr_price, total_buy, total_val, selisih_total, total_perf):
    """Membuat gambar tabel menggunakan Pillow"""
    # Warna
    header_bg = (200, 200, 200)  # Abu-abu untuk header
    positive_bg = (144, 238, 144)  # Hijau untuk performansi positif
    negative_bg = (255, 99, 71)  # Merah untuk performansi negatif
    white = (255, 255, 255)
    black = (0, 0, 0)

    # Dimensi tabel
    num_cols = len(headers)
    num_rows = len(data) + 1  # +1 untuk header
    cell_width = 200  # Lebar sel disesuaikan
    cell_height = 60  # Tinggi sel
    table_width = cell_width * num_cols
    table_height = cell_height * num_rows

    # Ruang untuk judul dan total
    title_height = 50
    total_text_height = 150
    img_width = table_width
    img_height = title_height + table_height + total_text_height

    # Buat gambar
    img = Image.new("RGB", (img_width, img_height), white)
    draw = ImageDraw.Draw(img)

    # Gunakan font dengan ukuran lebih besar
    try:
        font = ImageFont.truetype("arial.ttf", 24)
        title_font = ImageFont.truetype("arial.ttf", 30)
    except:
        font = ImageFont.load_default()
        title_font = ImageFont.load_default()

    # Gambar judul "Daftar Portofolio"
    draw.text(
        (10, 10),
        "Daftar Portofolio {active_account} {current_time}",
        fill=black,
        font=title_font
    )

    # Gambar header
    for col, header in enumerate(headers):
        x = col * cell_width
        y = title_height
        draw.rectangle(
            [(x, y), (x + cell_width, y + cell_height)],
            fill=header_bg,
            outline=black
        )
        draw.text(
            (x + 10, y + 15),
            header,
            fill=black,
            font=font
        )

    # Gambar isi tabel
    for row_idx, row in enumerate(data):
        for col_idx, cell in enumerate(row):
            x = col_idx * cell_width
            y = title_height + (row_idx + 1) * cell_height

            # Tentukan warna latar belakang untuk kolom performansi
            if col_idx == 4:  # Kolom performansi (indeks 4)
                if "🟢" in cell:
                    fill_color = positive_bg
                elif "🔴" in cell:
                    fill_color = negative_bg
                else:
                    fill_color = white
            else:
                fill_color = white

            draw.rectangle(
                [(x, y), (x + cell_width, y + cell_height)],
                fill=fill_color,
                outline=black
            )
            draw.text(
                (x + 10, y + 15),
                cell,
                fill=black,
                font=font
            )

    # Tambahkan teks total di bawah tabel
    total_text = (
        f"Total\n"
        f"Buy = {total_lots} lots x 100 lembar x {avg_buy_price:,.0f} = Rp {total_buy:,.0f}\n"
        f"Now = {total_lots} lots x 100 lembar x {avg_curr_price:,.0f} = Rp {total_val:,.0f}\n"
        f"selisih = Rp {selisih_total:,.0f}\n"
        f"performansi = {total_perf:+.1f}%"
    )
    draw.text(
        (10, title_height + table_height + 10),
        total_text,
        fill=black,
        font=font
    )

    # Potong gambar agar tidak ada spasi berlebih
    img = img.crop((0, 0, img_width, title_height + table_height + total_text_height))

    return img

import sqlite3
import logging
import io
import yfinance as yf
import pandas as pd
from datetime import datetime
import pytz
from telegram import Update
from telegram.ext import ContextTypes
import html

logger = logging.getLogger(__name__)
DATABASE_PATH = "stock_data.db"

async def analyze_report4(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan laporan konsolidasi portofolio pengguna dalam bentuk tabel gambar."""
    logger.info(f"Perintah /analyze_report1 dipanggil oleh user {update.effective_user.id}")
    user_id = update.effective_user.id
    try:
        # Ambil data transaksi pengguna
        transactions = get_user_transactions(user_id)

        if not transactions:
            await update.message.reply_text(
                "Belum ada transaksi pembelian saham di akun aktif.",
                parse_mode="Markdown"
            )
            return

        # Kumpulkan data transaksi per ticker
        ticker_summary = {}
        for tx in transactions:
            if tx.get("status") == "open":
                ticker = tx["ticker"]
                lot = tx["lot"]
                buy_price = tx["buy_price"]
                if ticker not in ticker_summary:
                    ticker_summary[ticker] = {"total_lot": 0, "total_cost": 0}
                ticker_summary[ticker]["total_lot"] += lot
                ticker_summary[ticker]["total_cost"] += buy_price * lot * 100

        if not ticker_summary:
            await update.message.reply_text(
                "Tidak ada posisi saham terbuka di akun aktif.",
                parse_mode="Markdown"
            )
            return

        # Hitung performa dan siapkan data untuk tabel
        table_data = []
        total_val = 0
        total_buy = 0
        total_lots = 0
        lot_size = 100  # 1 lot = 100 lembar

        # Hubungkan ke database untuk harga terkini
        conn = sqlite3.connect(DATABASE_PATH)
        for ticker, data in ticker_summary.items():
            total_lot = data["total_lot"]
            total_cost = data["total_cost"]
            avg_buy_price = total_cost / (total_lot * lot_size)

            # Ambil harga terkini dari database
            query_price = """
                SELECT Close FROM stock_data 
                WHERE symbol = ? AND Close IS NOT NULL
                ORDER BY date DESC LIMIT 1
            """
            price_df = pd.read_sql_query(query_price, conn, params=(ticker,))
            if price_df.empty:
                logger.warning(f"Tidak ada data harga untuk {ticker}")
                try:
                    # Fallback ke yfinance jika data tidak ada di database
                    ticker_data = yf.Ticker(ticker + ".JK")
                    price_data = ticker_data.history(period="1d")
                    if price_data.empty:
                        raise ValueError("Tidak ada data harga")
                    current_price = float(price_data["Close"].iloc[-1])
                    # Validasi harga realistis
                    if current_price > 50000 or current_price < 50:
                        raise ValueError(f"Harga tidak realistis: Rp {current_price:,.2f}")
                except Exception as e:
                    logger.error(f"Error mengambil harga {ticker} dari yfinance: {str(e)}")
                    current_price = avg_buy_price  # Fallback ke harga beli
            else:
                current_price = float(price_df["Close"].iloc[0])
                logger.info(f"Harga terkini {ticker}: Rp {current_price:,.2f}")

            # Hitung nilai dan performa
            buy_val = total_lot * lot_size * avg_buy_price
            curr_val = total_lot * lot_size * current_price
            perf = ((curr_val - buy_val) / buy_val * 100) if buy_val != 0 else 0
            selisih = curr_val - buy_val

            total_buy += buy_val
            total_val += curr_val
            total_lots += total_lot

            # Tambahkan data ke tabel
            table_data.append([
                ticker,
                f"{total_lot}",
                f"{avg_buy_price:,.0f}",
                f"{current_price:,.0f}",
                f"{'🟢' if perf >= 0 else '🔴'} {perf:+.1f}%",
                f"Rp {selisih:,.0f}"
            ])

        # Hitung total
        total_perf = ((total_val - total_buy) / total_buy * 100) if total_buy != 0 else 0
        avg_buy_price = total_buy / total_lots if total_lots != 0 else 0
        avg_curr_price = total_val / total_lots if total_lots != 0 else 0
        selisih_total = total_val - total_buy

        conn.close()

        # Buat gambar tabel
        headers = ["Saham", "Lots", "Buy", "Current", "Performansi", "Selisih"]
        img = create_table_image(headers, table_data, total_lots, avg_buy_price, avg_curr_price, total_buy, total_val, selisih_total, total_perf)

        # Simpan gambar ke buffer
        buffer = io.BytesIO()
        img.save(buffer, format="PNG")
        buffer.seek(0)

        # Kirim gambar ke Telegram
        current_time = datetime.now(pytz.timezone('Asia/Jakarta')).strftime("%Y-%m-%d %H:%M WIB")
        await update.message.reply_photo(
            photo=buffer,
            caption=f"📊 *Analisa Laporan Konsolidasi*\nPer tanggal: {current_time}",
            parse_mode="Markdown"
        )
        logger.info(f"Laporan konsolidasi berhasil dibuat untuk user {user_id}")

    except Exception as e:
        logger.error(f"Error di analyze_report1 untuk user {user_id}: {str(e)}")
        await update.message.reply_text(
            f"Terjadi kesalahan saat menghasilkan analisa laporan: {str(e)}",
            parse_mode="Markdown"
        )    

