        total_buy = 0
        total_lots = 0
        lot_size = 100  # 1 lot = 100 lembar

        # Hubungkan ke database untuk harga terkini
        conn = sqlite3.connect(DATABASE_PATH)
        for ticker, data in ticker_summary.items():
            total_lot = data["total_lot"]
            total_cost = data["total_cost"]
            avg_buy_price = total_cost / (total_lot * lot_size)

            # Ambil harga terkini dari database
            query_price = """
                SELECT Close FROM stock_data 
                WHERE symbol = ? AND Close IS NOT NULL
                ORDER BY date DESC LIMIT 1
            """
            price_df = pd.read_sql_query(query_price, conn, params=(ticker,))
            if price_df.empty:
                logger.warning(f"Tidak ada data harga untuk {ticker} di database")
                try:
                    # Fallback ke yfinance
                    ticker_data = yf.Ticker(ticker + ".JK")
                    price_data = ticker_data.history(period="1d")
                    if price_data.empty:
                        raise ValueError("Tidak ada data harga dari yfinance")
                    current_price = float(price_data["Close"].iloc[-1])
                    # Validasi harga realistis
                    if current_price > 50000 or current_price < 50:
                        raise ValueError(f"Harga tidak realistis: Rp {current_price:,.2f}")
                except Exception as e:
                    logger.error(f"Error mengambil harga {ticker} dari yfinance: {str(e)}")
                    current_price = avg_buy_price  # Fallback ke harga beli
            else:
                current_price = float(price_df["Close"].iloc[0])
                logger.info(f"Harga terkini {ticker}: Rp {current_price:,.2f}")

            # Hitung nilai dan performa
            buy_val = total_lot * lot_size * avg_buy_price
            curr_val = total_lot * lot_size * current_price
            perf = ((curr_val - buy_val) / buy_val * 100) if buy_val != 0 else 0
            selisih = curr_val - buy_val

            total_buy += buy_val
            total_val += curr_val
            total_lots += total_lot

            # Tambahkan data ke tabel
