import sqlite3
import logging
import numpy as np
from sklearn.preprocessing import MinMaxScaler
from sklearn.metrics import mean_absolute_error
from pmdarima import auto_arima

from prophet import Prophet
import plotly.graph_objects as go
from datetime import datetime, timedelta
import pandas as pd
import yfinance as yf
from xgboost import XGBRegressor

# Setup logging
logger = logging.getLogger(__name__)

DATABASE_PATH = "stock_data.db"  # Simpan di direktori yang sama dengan bot.py

def calculate_ma(prices, period=10):
    """Menghitung Simple Moving Average (MA)."""
    ma = []
    for i in range(len(prices)):
        if i < period - 1:
            ma.append(0)
        else:
            ma.append(np.mean(prices[i-period+1:i+1]))
    return np.array(ma)

def calculate_rsi(prices, period=14):
    """Menghitung Relative Strength Index (RSI)."""
    deltas = np.diff(prices)
    gains = np.where(deltas > 0, deltas, 0)
    losses = np.where(deltas < 0, -deltas, 0)

    avg_gain = []
    avg_loss = []
    for i in range(len(prices)):
        if i < period:
            avg_gain.append(0)
            avg_loss.append(0)
        else:
            gain_slice = gains[i-period:i] if i > 0 else gains[:i]
            loss_slice = losses[i-period:i] if i > 0 else losses[:i]
            avg_gain.append(np.mean(gain_slice) if len(gain_slice) > 0 else 0)
            avg_loss.append(np.mean(loss_slice) if len(loss_slice) > 0 else 0)

    avg_gain = np.array(avg_gain)
    avg_loss = np.array(avg_loss)
    rs = np.divide(avg_gain, avg_loss, out=np.zeros_like(avg_gain), where=avg_loss != 0)
    rsi = 100 - (100 / (1 + rs))
    rsi[:period] = 0
    return rsi

def calculate_stochastic(highs, lows, closes, k_period=14, d_period=3):
    """Menghitung Stochastic Oscillator (%K dan %D)."""
    lowest_low = []
    highest_high = []
    for i in range(len(closes)):
        if i < k_period - 1:
            lowest_low.append(0)
            highest_high.append(0)
        else:
            low_slice = lows[i-k_period+1:i+1]
            high_slice = highs[i-k_period+1:i+1]
            lowest_low.append(np.min(low_slice))
            highest_high.append(np.max(high_slice))

    lowest_low = np.array(lowest_low)
    highest_high = np.array(highest_high)
    k = np.zeros(len(closes))
    for i in range(k_period - 1, len(closes)):
        if highest_high[i] - lowest_low[i] != 0:
            k[i] = ((closes[i] - lowest_low[i]) / (highest_high[i] - lowest_low[i])) * 100

    d = []
    for i in range(len(closes)):
        if i < k_period + d_period - 2:
            d.append(0)
        else:
            d.append(np.mean(k[i-d_period+1:i+1]))

    return k, np.array(d)

def calculate_macd(prices, fast_period=12, slow_period=26, signal_period=9):
    """Menghitung MACD dan Signal Line."""
    ema_fast = []
    ema_slow = []
    for i in range(len(prices)):
        if i < fast_period - 1:
            ema_fast.append(0)
        else:
            ema_fast.append(np.mean(prices[i-fast_period+1:i+1]))
        if i < slow_period - 1:
            ema_slow.append(0)
        else:
            ema_slow.append(np.mean(prices[i-slow_period+1:i+1]))

    k_fast = 2 / (fast_period + 1)
    k_slow = 2 / (slow_period + 1)
    for i in range(len(prices)):
        if ema_fast[i] != 0:
            ema_fast[i] = prices[i] * k_fast + ema_fast[i-1] * (1 - k_fast) if i > fast_period - 1 else ema_fast[i]
        if ema_slow[i] != 0:
            ema_slow[i] = prices[i] * k_slow + ema_slow[i-1] * (1 - k_slow) if i > slow_period - 1 else ema_slow[i]

    ema_fast = np.array(ema_fast)
    ema_slow = np.array(ema_slow)
    macd = ema_fast - ema_slow

    signal = []
    for i in range(len(prices)):
        if i < slow_period + signal_period - 2:
            signal.append(0)
        else:
            signal.append(np.mean(macd[i-signal_period+1:i+1]))

    return macd, np.array(signal)

def calculate_bollinger_bands(prices, period=20, std_dev_multiplier=2):
    """Menghitung Bollinger Bands (Upper dan Lower Band)."""
    sma = []
    for i in range(len(prices)):
        if i < period - 1:
            sma.append(0)
        else:
            sma.append(np.mean(prices[i-period+1:i+1]))

    std_dev = []
    for i in range(len(prices)):
        if i < period - 1:
            std_dev.append(0)
        else:
            window = prices[i-period+1:i+1]
            std_dev.append(np.std(window))

    sma = np.array(sma)
    std_dev = np.array(std_dev)
    upper_band = sma + (std_dev_multiplier * std_dev)
    lower_band = sma - (std_dev_multiplier * std_dev)
    return upper_band, lower_band

def fetch_global_index(dates):
    """Mengambil data indeks global (S&P 500) menggunakan yfinance."""
    start_date = min(dates).strftime('%Y-%m-%d')
    end_date = (max(dates) + timedelta(days=1)).strftime('%Y-%m-%d')
    sp500 = yf.download('^GSPC', start=start_date, end=end_date, progress=False)
    sp500 = sp500['Close'].reindex(pd.to_datetime([d.strftime('%Y-%m-%d') for d in dates])).fillna(method='ffill')
    global_index = sp500.values
    changes = np.zeros(len(global_index))
    for i in range(1, len(global_index)):
        changes[i] = ((global_index[i] - global_index[i-1]) / global_index[i-1]) * 100 if global_index[i-1] != 0 else 0
    return global_index, changes

import sqlite3
import logging
import numpy as np
from sklearn.linear_model import LinearRegression
from telegram import Update
from telegram.ext import ContextTypes
from datetime import datetime, timedelta

# Setup logging
logger = logging.getLogger(__name__)

DATABASE_PATH = "stock_data.db"  # Simpan di direktori yang sama dengan bot.py

async def pg3(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan Price Graph 3: Rata-rata pergerakan saham dan prediksi menggunakan Machine Learning."""
    ticker = "Unknown"  # Default nilai ticker untuk keperluan logging
    try:
        # Pastikan ada argumen ticker
        if not context.args:
            await update.message.reply_text(
                "Gunakan: /pg3 <kode_saham>\nContoh: /pg3 BMRI",
                parse_mode="Markdown"
            )
            return

        ticker = context.args[0].upper()

        # Koneksi ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        # Ambil data harga saham 70 hari terakhir
        end_date = datetime.now()
        start_date = end_date - timedelta(days=70)
        cursor.execute(
            "SELECT Date, Close FROM stocks WHERE Ticker = ? AND Date >= ? AND Date <= ? ORDER BY Date ASC",
            (ticker, start_date.strftime('%Y-%m-%d'), end_date.strftime('%Y-%m-%d'))
        )
        price_data = cursor.fetchall()

        if not price_data:
            await update.message.reply_text(
                f"Data untuk {ticker} tidak ditemukan dalam 70 hari terakhir.",
                parse_mode="Markdown"
            )
            conn.close()
            return

        # Konversi data ke list untuk analisis
        dates = [datetime.strptime(row[0], '%Y-%m-%d') for row in price_data]
        prices = [float(row[1]) for row in price_data]

        if len(prices) < 10:
            await update.message.reply_text(
                f"Data untuk {ticker} tidak cukup untuk analisis. Minimal diperlukan 10 hari data, hanya tersedia {len(prices)} hari.",
                parse_mode="Markdown"
            )
            conn.close()
            return

        # 1. Hitung rata-rata pergerakan harian (persentase perubahan harian)
        daily_changes = []
        for i in range(1, len(prices)):
            change = ((prices[i] - prices[i-1]) / prices[i-1]) * 100 if prices[i-1] != 0 else 0
            daily_changes.append(change)

        avg_daily_change = np.mean(daily_changes) if daily_changes else 0
        std_daily_change = np.std(daily_changes) if daily_changes else 0

        # 2. Latih model Linear Regression untuk prediksi harga
        # Siapkan data untuk model: x adalah indeks hari, y adalah harga
        X = np.arange(len(prices)).reshape(-1, 1)  # Indeks hari (0, 1, 2, ...)
        y = np.array(prices)  # Harga penutupan

        # Latih model
        model = LinearRegression()
        model.fit(X, y)

        # Prediksi harga untuk 5 hari ke depan
        future_days = np.array([len(prices) + i for i in range(5)]).reshape(-1, 1)
        predicted_prices = model.predict(future_days)

        # Hitung tren berdasarkan koefisien regresi
        trend_slope = model.coef_[0]
        trend = "Meningkat" if trend_slope > 0 else "Menurun" if trend_slope < 0 else "Stabil"

        # 3. Format pesan akhir
        message = f"📈 *Price Graph 3 untuk {ticker}*\n\n"
        message += "*Analisis Pergerakan Harian*\n"
        message += f"📊 Rata-rata Pergerakan Harian: {avg_daily_change:+.2f}%\n"
        message += f"📉 Volatilitas (Std Dev): {std_daily_change:.2f}%\n\n"
        message += "*Prediksi Harga (Linear Regression)*\n"
        message += f"📈 Tren: {trend}\n"
        message += "Harga Prediksi 5 Hari ke Depan:\n"
        for i, price in enumerate(predicted_prices, 1):
            future_date = (end_date + timedelta(days=i)).strftime('%Y-%m-%d')
            message += f"{future_date}: {price:.2f}\n"

        await update.message.reply_text(message, parse_mode="Markdown")

        conn.close()

    except Exception as e:
        logger.error(f"Error in pg3 for ticker {ticker}: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat memproses Price Graph 3. Silakan coba lagi.",
            parse_mode="Markdown"
        )
import sqlite3
import logging
import numpy as np
from sklearn.preprocessing import MinMaxScaler
