def calculate_stochastic(highs, lows, closes, k_period=14, d_period=3):
    """Menghitung Stochastic Oscillator (%K dan %D)."""
    lowest_low = []
    highest_high = []
    for i in range(len(closes)):
        if i < k_period - 1:
            lowest_low.append(0)
            highest_high.append(0)
        else:
            low_slice = lows[i-k_period+1:i+1]
            high_slice = highs[i-k_period+1:i+1]
            lowest_low.append(np.min(low_slice))
            highest_high.append(np.max(high_slice))

