def check_consecutive_red(ticker, cursor, end_date, max_days=10):
    """Mengembalikan jumlah hari merah berturut-turut sebelum end_date."""
    try:
        cursor.execute(
            """
            SELECT date, close 
            FROM stocks 
            WHERE ticker = ? AND date <= ? 
            ORDER BY date DESC 
            LIMIT ? + 1
            """,
            (ticker, end_date.strftime("%Y-%m-%d"), max_days + 1)
        )
        data = cursor.fetchall()
        if len(data) < 2:
            return 0
        
        consecutive_red = 0
        prev_price = None
        
        for i, (date, close) in enumerate(data[:-1]):  # Hanya data sebelum end_date untuk perbandingan
            if not close:  # Lewati jika data hilang
                continue
            close = float(close)
            if prev_price is not None:
                if close >= prev_price:
                    break
                consecutive_red += 1
            prev_price = close
        
        # Periksa end_date sebagai bagian dari periode merah
        if data and data[0][0] == end_date.strftime("%Y-%m-%d") and prev_price is not None:
            current_close = float(data[0][1]) if data[0][1] else None
            if current_close and current_close < prev_price:
                consecutive_red += 1
        
        return consecutive_red if consecutive_red >= 2 else 0
    except Exception as e:
        logger.warning(f"Gagal memeriksa penurunan berturut-turut untuk {ticker}: {str(e)}")
        return 0
    
# Fungsi untuk menghitung rata-rata volume 5 hari sebelumnya
def get_avg_volume_5_days(ticker, cursor, end_date):
    """Menghitung rata-rata volume 5 hari sebelum end_date."""
    try:
        # Ambil data volume 5 hari sebelum end_date
        start_date = end_date - timedelta(days=7)  # Mulai dari 7 hari sebelumnya untuk toleransi
        cursor.execute(
            """
            SELECT volume 
            FROM stocks 
            WHERE ticker = ? AND date < ? AND date >= ? 
            ORDER BY date DESC 
            LIMIT 5
            """,
            (ticker, end_date.strftime("%Y-%m-%d"), start_date.strftime("%Y-%m-%d"))
        )
        volumes = cursor.fetchall()
        if len(volumes) < 5:
            return 0  # Tidak cukup data untuk menghitung rata-rata
        
        total_volume = sum(float(v[0]) for v in volumes)
        avg_volume = total_volume / len(volumes)
        return avg_volume
    except Exception as e:
        logger.warning(f"Gagal menghitung rata-rata volume untuk {ticker}: {str(e)}")
        return 0


