def calculate_ma(prices, period=10):
    """Menghitung Simple Moving Average (MA)."""
    ma = []
    for i in range(len(prices)):
        if i < period - 1:
            ma.append(0)
        else:
            ma.append(np.mean(prices[i-period+1:i+1]))
    return np.array(ma)

def calculate_rsi(prices, period=14):
    """Menghitung Relative Strength Index (RSI)."""
    deltas = np.diff(prices)
    gains = np.where(deltas > 0, deltas, 0)
    losses = np.where(deltas < 0, -deltas, 0)

    avg_gain = []
    avg_loss = []
    for i in range(len(prices)):
        if i < period:
            avg_gain.append(0)
            avg_loss.append(0)
        else:
            gain_slice = gains[i-period:i] if i > 0 else gains[:i]
            loss_slice = losses[i-period:i] if i > 0 else losses[:i]
            avg_gain.append(np.mean(gain_slice) if len(gain_slice) > 0 else 0)
            avg_loss.append(np.mean(loss_slice) if len(loss_slice) > 0 else 0)

    avg_gain = np.array(avg_gain)
    avg_loss = np.array(avg_loss)
    rs = np.divide(avg_gain, avg_loss, out=np.zeros_like(avg_gain), where=avg_loss != 0)
    rsi = 100 - (100 / (1 + rs))
    rsi[:period] = 0
    return rsi

def calculate_stochastic(highs, lows, closes, k_period=14, d_period=3):
    """Menghitung Stochastic Oscillator (%K dan %D)."""
    lowest_low = []
    highest_high = []
    for i in range(len(closes)):
        if i < k_period - 1:
            lowest_low.append(0)
            highest_high.append(0)
        else:
            low_slice = lows[i-k_period+1:i+1]
            high_slice = highs[i-k_period+1:i+1]
            lowest_low.append(np.min(low_slice))
            highest_high.append(np.max(high_slice))

    lowest_low = np.array(lowest_low)
    highest_high = np.array(highest_high)
    k = np.zeros(len(closes))
    for i in range(k_period - 1, len(closes)):
        if highest_high[i] - lowest_low[i] != 0:
            k[i] = ((closes[i] - lowest_low[i]) / (highest_high[i] - lowest_low[i])) * 100

    d = []
    for i in range(len(closes)):
        if i < k_period + d_period - 2:
            d.append(0)
        else:
            d.append(np.mean(k[i-d_period+1:i+1]))

    return k, np.array(d)

def calculate_macd(prices, fast_period=12, slow_period=26, signal_period=9):
    """Menghitung MACD dan Signal Line."""
    ema_fast = []
    ema_slow = []
    for i in range(len(prices)):
        if i < fast_period - 1:
            ema_fast.append(0)
        else:
            ema_fast.append(np.mean(prices[i-fast_period+1:i+1]))
        if i < slow_period - 1:
            ema_slow.append(0)
        else:
            ema_slow.append(np.mean(prices[i-slow_period+1:i+1]))

    k_fast = 2 / (fast_period + 1)
    k_slow = 2 / (slow_period + 1)
    for i in range(len(prices)):
        if ema_fast[i] != 0:
            ema_fast[i] = prices[i] * k_fast + ema_fast[i-1] * (1 - k_fast) if i > fast_period - 1 else ema_fast[i]
        if ema_slow[i] != 0:
            ema_slow[i] = prices[i] * k_slow + ema_slow[i-1] * (1 - k_slow) if i > slow_period - 1 else ema_slow[i]

    ema_fast = np.array(ema_fast)
    ema_slow = np.array(ema_slow)
    macd = ema_fast - ema_slow

    signal = []
    for i in range(len(prices)):
        if i < slow_period + signal_period - 2:
            signal.append(0)
        else:
            signal.append(np.mean(macd[i-signal_period+1:i+1]))

    return macd, np.array(signal)

def calculate_bollinger_bands(prices, period=20, std_dev_multiplier=2):
    """Menghitung Bollinger Bands (Upper dan Lower Band)."""
    sma = []
    for i in range(len(prices)):
        if i < period - 1:
            sma.append(0)
        else:
            sma.append(np.mean(prices[i-period+1:i+1]))

    std_dev = []
    for i in range(len(prices)):
        if i < period - 1:
            std_dev.append(0)
        else:
            window = prices[i-period+1:i+1]
            std_dev.append(np.std(window))

    sma = np.array(sma)
    std_dev = np.array(std_dev)
    upper_band = sma + (std_dev_multiplier * std_dev)
    lower_band = sma - (std_dev_multiplier * std_dev)
    return upper_band, lower_band

def fetch_global_index(dates):
    """Mengambil data indeks global (S&P 500) menggunakan yfinance."""
    start_date = min(dates).strftime('%Y-%m-%d')
    end_date = (max(dates) + timedelta(days=1)).strftime('%Y-%m-%d')
    sp500 = yf.download('^GSPC', start=start_date, end=end_date, progress=False)
    sp500 = sp500['Close'].reindex(pd.to_datetime([d.strftime('%Y-%m-%d') for d in dates])).fillna(method='ffill')
    global_index = sp500.values
    changes = np.zeros(len(global_index))
    for i in range(1, len(global_index)):
        changes[i] = ((global_index[i] - global_index[i-1]) / global_index[i-1]) * 100 if global_index[i-1] != 0 else 0
    return global_index, changes

def simulate_economic_data(dates):
    """Mensimulasikan data suku bunga (BI Rate) dan nilai tukar USD/IDR."""
    bi_rate = [5.5]
    for i in range(1, len(dates)):
        change = np.random.normal(0, 0.05)
        bi_rate.append(max(bi_rate[-1] + change, 3.0))
    bi_rate = np.array(bi_rate)

    exchange_rate = [15500]
    for i in range(1, len(dates)):
        change = np.random.normal(0, 50)
        exchange_rate.append(max(exchange_rate[-1] + change, 14000))
    exchange_rate = np.array(exchange_rate)

    return bi_rate, exchange_rate

def simulate_sentiment_data(dates):
    """Mensimulasikan data sentimen pasar (skor antara -1 dan 1)."""
    # Dalam aplikasi nyata, gunakan API seperti NewsAPI atau Twitter API untuk analisis sentimen
    sentiment_scores = []
    for _ in range(len(dates)):
        score = np.random.uniform(-1, 1)  # Skor sentimen antara -1 (negatif) dan 1 (positif)
        sentiment_scores.append(score)
    return np.array(sentiment_scores)

