class TransformerModel(nn.Module):
    """Model Transformer untuk prediksi deret waktu."""
    def __init__(self, input_dim, d_model=64, nhead=4, num_layers=2, dropout=0.1):
        super(TransformerModel, self).__init__()
        self.input_projection = nn.Linear(input_dim, d_model)
        self.transformer = nn.Transformer(
            d_model=d_model,
            nhead=nhead,
            num_encoder_layers=num_layers,
            num_decoder_layers=num_layers,
            dropout=dropout,
            batch_first=True
        )
        self.fc = nn.Linear(d_model, 1)

    def forward(self, src, tgt):
        src = self.input_projection(src)
        tgt = self.input_projection(tgt)
        output = self.transformer(src, tgt)
        output = self.fc(output)
        return output

def train_transformer_model(model, X, y, epochs=30, batch_size=32, learning_rate=0.001):
    """Melatih model Transformer."""
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = model.to(device)
    criterion = nn.MSELoss()
    optimizer = torch.optim.Adam(model.parameters(), lr=learning_rate)

    X_tensor = torch.FloatTensor(X).to(device)
    y_tensor = torch.FloatTensor(y).to(device)

    dataset = TensorDataset(X_tensor, y_tensor)
    dataloader = DataLoader(dataset, batch_size=batch_size, shuffle=True)

    model.train()
    for epoch in range(epochs):
        total_loss = 0
        for batch_X, batch_y in dataloader:
            optimizer.zero_grad()
            batch_y = batch_y.unsqueeze(1).repeat(1, batch_X.size(1), 1)
            output = model(batch_X, batch_y)
            loss = criterion(output[:, -1, :], batch_y[:, -1, :])
            loss.backward()
            optimizer.step()
            total_loss += loss.item()
        avg_loss = total_loss / len(dataloader)
        logger.info(f"Epoch {epoch+1}/{epochs}, Loss: {avg_loss:.4f}")

    return model

def optimize_xgboost(X, y, n_trials=20):
    """Optimasi hyperparameter XGBoost menggunakan Optuna."""
    def objective(trial):
        params = {
            'n_estimators': trial.suggest_int('n_estimators', 50, 200),
            'learning_rate': trial.suggest_float('learning_rate', 0.01, 0.3, log=True),
            'max_depth': trial.suggest_int('max_depth', 3, 10),
            'random_state': 42
        }
        model = XGBRegressor(**params)
        model.fit(X, y)
        predictions = model.predict(X)
        mae = mean_absolute_error(y, predictions)
        return mae

    study = optuna.create_study(direction='minimize')
    study.optimize(objective, n_trials=n_trials)
    best_params = study.best_params
    return best_params

