        # 3. Simulasi data suku bunga dan nilai tukar
        bi_rate, exchange_rate = simulate_economic_data(dates)

        # 4. Simulasi data sentimen pasar
        sentiment_scores = simulate_sentiment_data(dates)

        # 5. Analisis Korelasi
        data_df = pd.DataFrame({
            'Price': prices,
            'S&P 500': global_index,
            'BI Rate': bi_rate,
            'USD/IDR': exchange_rate,
            'Sentiment': sentiment_scores
        })
        correlation_matrix = data_df.corr(method='pearson')
        corr_price_sp500 = correlation_matrix.loc['Price', 'S&P 500']
        corr_price_bi_rate = correlation_matrix.loc['Price', 'BI Rate']
        corr_price_exchange = correlation_matrix.loc['Price', 'USD/IDR']
        corr_price_sentiment = correlation_matrix.loc['Price', 'Sentiment']

        # Visualisasi Heatmap Korelasi
        labels = ['Price', 'S&P 500', 'BI Rate', 'USD/IDR', 'Sentiment']
        corr_fig = ff.create_annotated_heatmap(
            z=correlation_matrix.values,
            x=labels,
            y=labels,
            colorscale='Viridis',
            showscale=True,
            annotation_text=np.round(correlation_matrix.values, 2)
        )
        corr_fig.update_layout(title=f'Heatmap Korelasi Fitur Eksternal untuk {ticker}')
        corr_fig.write_html('correlation_heatmap.html')

        # 6. Prediksi dengan ARIMA
        arima_model = auto_arima(
            prices,
            seasonal=True,
            m=5,
            stepwise=True,
            suppress_warnings=True,
            trace=False
        )
        arima_result = arima_model.fit(prices)
        arima_forecast = arima_result.predict(n_periods=5)
        arima_predicted_prices = arima_forecast.tolist()

        arima_train_pred = arima_result.predict_in_sample()
        arima_train_pred = arima_train_pred[-len(prices)+arima_model.order[1]:]
        arima_mae = mean_absolute_error(prices[arima_model.order[1]:], arima_train_pred)

        # 7. Prediksi dengan Prophet
        prophet_df = pd.DataFrame({'ds': dates, 'y': prices})
        prophet_model = Prophet(daily_seasonality=True, yearly_seasonality=False, weekly_seasonality=True)
        prophet_model.fit(prophet_df)
        future_dates = prophet_model.make_future_dataframe(periods=5, include_history=False)
        prophet_forecast = prophet_model.predict(future_dates)
        prophet_predicted_prices = prophet_forecast['yhat'].values.tolist()

        prophet_train_pred = prophet_model.predict(prophet_df)['yhat'].values
        prophet_mae = mean_absolute_error(prices, prophet_train_pred)

        # 8. Prediksi dengan Transformer
        ma = calculate_ma(prices, period=10)
        rsi = calculate_rsi(prices, period=14)
        stochastic_k, stochastic_d = calculate_stochastic(highs, lows, prices, k_period=14, d_period=3)
        macd, macd_signal = calculate_macd(prices)
        upper_band, lower_band = calculate_bollinger_bands(prices)

        data = np.column_stack((prices, volumes, ma, rsi, stochastic_k, stochastic_d, macd, macd_signal, upper_band, lower_band, global_index_changes, bi_rate, exchange_rate, sentiment_scores))

        scaler = MinMaxScaler(feature_range=(0, 1))
        scaled_data = scaler.fit_transform(data)

        sequence_length = 14
        X_trans, y_trans = [], []
        for i in range(sequence_length, len(scaled_data)):
            X_trans.append(scaled_data[i-sequence_length:i])
            y_trans.append(scaled_data[i, 0])

        X_trans, y_trans = np.array(X_trans), np.array(y_trans)

        transformer_model = TransformerModel(input_dim=14, d_model=64, nhead=4, num_layers=2, dropout=0.1)
        transformer_model = train_transformer_model(transformer_model, X_trans, y_trans, epochs=20, batch_size=32)

        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        transformer_model.eval()
        last_sequence = scaled_data[-sequence_length:]
        transformer_predicted_prices = []
        current_sequence = torch.FloatTensor(last_sequence).unsqueeze(0).to(device)

        avg_volume = np.mean(volumes[-sequence_length:])
        avg_ma = np.mean(ma[-sequence_length:])
        avg_rsi = np.mean(rsi[-sequence_length:])
        avg_k = np.mean(stochastic_k[-sequence_length:])
        avg_d = np.mean(stochastic_d[-sequence_length:])
        avg_macd = np.mean(macd[-sequence_length:])
        avg_macd_signal = np.mean(macd_signal[-sequence_length:])
        avg_upper_band = np.mean(upper_band[-sequence_length:])
        avg_lower_band = np.mean(lower_band[-sequence_length:])
        avg_global_index_change = np.mean(global_index_changes[-sequence_length:])
        avg_bi_rate = np.mean(bi_rate[-sequence_length:])
        avg_exchange_rate = np.mean(exchange_rate[-sequence_length:])
        avg_sentiment = np.mean(sentiment_scores[-sequence_length:])

        for _ in range(5):
            with torch.no_grad():
                current_sequence_reshaped = current_sequence
                dummy_tgt = current_sequence_reshaped.clone()
                next_price = transformer_model(current_sequence_reshaped, dummy_tgt)[:, -1, :]
                transformer_predicted_prices.append(next_price.cpu().numpy()[0, 0])
                new_row = scaler.transform([[prices[-1], avg_volume, avg_ma, avg_rsi, avg_k, avg_d, avg_macd, avg_macd_signal, avg_upper_band, avg_lower_band, avg_global_index_change, avg_bi_rate, avg_exchange_rate, avg_sentiment]])
                new_row_tensor = torch.FloatTensor(new_row).to(device)
                current_sequence = torch.cat((current_sequence[:, 1:, :], new_row_tensor.unsqueeze(0)), dim=1)

        transformer_predicted_data = np.column_stack((
            transformer_predicted_prices,
            [avg_volume] * 5,
            [avg_ma] * 5,
            [avg_rsi] * 5,
            [avg_k] * 5,
            [avg_d] * 5,
            [avg_macd] * 5,
            [avg_macd_signal] * 5,
            [avg_upper_band] * 5,
            [avg_lower_band] * 5,
            [avg_global_index_change] * 5,
            [avg_bi_rate] * 5,
            [avg_exchange_rate] * 5,
            [avg_sentiment] * 5
        ))
        transformer_predicted_prices = scaler.inverse_transform(transformer_predicted_data)[:, 0]

        transformer_train_pred = []
        with torch.no_grad():
            X_trans_tensor = torch.FloatTensor(X_trans).to(device)
            for i in range(len(X_trans_tensor)):
                batch = X_trans_tensor[i:i+1]
                dummy_tgt = batch.clone()
                pred = transformer_model(batch, dummy_tgt)[:, -1, :].cpu().numpy().flatten()
                transformer_train_pred.append(pred[0])
        transformer_train_pred = np.array(transformer_train_pred)
        transformer_mae = mean_absolute_error(y_trans, scaler.inverse_transform(np.column_stack((transformer_train_pred, scaled_data[sequence_length:, 1:]))[:, 0]))

        # 9. Prediksi dengan XGBoost
        X_xgb, y_xgb = [], []
        for i in range(sequence_length, len(data)):
            X_xgb.append(data[i-sequence_length:i].flatten())
            y_xgb.append(data[i, 0])

        X_xgb, y_xgb = np.array(X_xgb), np.array(y_xgb)

        best_params_xgb = optimize_xgboost(X_xgb, y_xgb, n_trials=20)
        xgb_model = XGBRegressor(**best_params_xgb, random_state=42)
        xgb_model.fit(X_xgb, y_xgb)

        xgb_predicted_prices = []
        current_xgb_sequence = data[-sequence_length:].flatten()
        for _ in range(5):
            current_xgb_sequence_reshaped = current_xgb_sequence.reshape(1, -1)
            next_price = xgb_model.predict(current_xgb_sequence_reshaped)[0]
            xgb_predicted_prices.append(next_price)
            current_xgb_sequence = np.roll(current_xgb_sequence, -14)
            current_xgb_sequence[-14:] = [next_price, avg_volume, avg_ma, avg_rsi, avg_k, avg_d, avg_macd, avg_macd_signal, avg_upper_band, avg_lower_band, avg_global_index_change, avg_bi_rate, avg_exchange_rate, avg_sentiment]

        xgb_train_pred = xgb_model.predict(X_xgb)
        xgb_mae = mean_absolute_error(y_xgb, xgb_train_pred)

        # 10. Ensemble Model
        total_inverse_mae = (1 / arima_mae) + (1 / transformer_mae) + (1 / prophet_mae) + (1 / xgb_mae)
        arima_weight = (1 / arima_mae) / total_inverse_mae
        transformer_weight = (1 / transformer_mae) / total_inverse_mae
        prophet_weight = (1 / prophet_mae) / total_inverse_mae
