# Fungsi untuk membagi pesan panjang menjadi beberapa bagian
async def send_long_message(context, chat_id, header, rows, period_label, max_length=4096):
    """Mengirim pesan panjang dengan membagi ke beberapa pesan jika melebihi batas karakter."""
    # Header tabel untuk setiap pesan
    table_header = (
        f"| Saham | Perubahan (%) | Harga (Rp) | Volume | Nilai (Rp) |\n"
        f"|-------|---------------|------------|--------|------------|\n"
    )
    # Judul awal hanya untuk pesan pertama
    full_header = f"📈 *Top Gainers MBX ({period_label.replace('_', ' ')})*\n\n{table_header}"
    
    current_message = full_header
    message_count = 1
    messages = []

    for row in rows:
        ticker, change, price, volume, trans_value = row
        change_emoji = "🟢" if change >= 0 else "🔴"
        row_text = f"| {ticker:<5} | {change_emoji} {change:+.2f} | {price:,.2f} | {volume} | {trans_value} |\n"
        
        # Cek apakah penambahan baris melebihi batas
        if len(current_message) + len(row_text) > max_length:
            # Simpan pesan saat ini
            messages.append(current_message)
            # Mulai pesan baru dengan header tabel saja
            current_message = f"📈 *Top Gainers MBX ({period_label.replace('_', ' ')}) - Bagian {message_count + 1}*\n\n{table_header}"
            message_count += 1
        
        current_message += row_text

    # Tambahkan pesan terakhir
    if current_message not in messages:
        messages.append(current_message)

    # Kirim semua pesan
    for msg in messages:
        await context.bot.send_message(
            chat_id=chat_id,
            text=msg,
            parse_mode="Markdown"
        )

async def top_gainers_mbx(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan top gainers saham MBX untuk periode tertentu atau tanggal spesifik."""
    try:
        # Ambil parameter dari args
        period = context.args[0].lower() if context.args else "harian"
        days = 1  # Default untuk harian
        is_date = False
        end_date = None
        start_date = None
        period_label = "Harian"

        # Validasi input: tanggal, periode, atau jumlah hari
        try:
            # Coba parse sebagai tanggal (YYYY-MM-DD)
            end_date = datetime.strptime(period, "%Y-%m-%d")
            is_date = True
            period_label = period  # Gunakan tanggal sebagai label
            days = 1  # Bandingkan dengan hari sebelumnya
        except ValueError:
            # Bukan tanggal, cek apakah angka (jumlah hari) atau periode
            try:
                days = int(period)
                period_label = f"{days} Hari"
            except ValueError:
                if period not in ["harian", "mingguan"]:
                    await update.message.reply_text(
                        "Periode tidak valid. Gunakan: 'harian', 'mingguan', jumlah hari (contoh: /tgmbx 10), atau tanggal (contoh: /tgmbx 2025-06-12).",
                        parse_mode="Markdown"
                    )
                    return
                days = 7 if period == "mingguan" else 1
                period_label = period.capitalize()

        # Validasi MBX_STOCKS
        if not MBX_STOCKS:
            await update.message.reply_text(
                "Tidak ada data ticker MBX yang tersedia.",
                parse_mode="Markdown"
            )
            return

        # Koneksi ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        # Tentukan end_date dan start_date
        if is_date:
            # Gunakan tanggal input sebagai end_date
            cursor.execute("SELECT MAX(Date) FROM stocks WHERE Date <= ?", (period,))
            latest_date = cursor.fetchone()[0]
            if not latest_date:
                await update.message.reply_text(
                    f"Tidak ada data saham pada atau sebelum {period}.",
                    parse_mode="Markdown"
                )
                conn.close()
                return
            end_date = datetime.strptime(latest_date, "%Y-%m-%d")
            # Cari tanggal sebelumnya untuk start_date
            cursor.execute(
                "SELECT MAX(Date) FROM stocks WHERE Date < ?",
                (end_date.strftime("%Y-%m-%d"),)
            )
            prev_date = cursor.fetchone()[0]
            if not prev_date:
                await update.message.reply_text(
                    f"Tidak ada data saham sebelum {period} untuk perbandingan.",
                    parse_mode="Markdown"
                )
                conn.close()
                return
            start_date = datetime.strptime(prev_date, "%Y-%m-%d")
        else:
            # Ambil tanggal terbaru dari database untuk end_date
            cursor.execute("SELECT MAX(Date) FROM stocks")
            latest_date = cursor.fetchone()[0]
            if not latest_date:
                await update.message.reply_text("Data saham tidak ditemukan.", parse_mode="Markdown")
                conn.close()
                return
            end_date = datetime.strptime(latest_date, "%Y-%m-%d")
            start_date = end_date - timedelta(days=days)

        # Query untuk mengambil data pada start_date dan end_date
        query = """
            SELECT Ticker, Date, Close, Volume
            FROM stocks
            WHERE Ticker IN ({})
            AND Date IN (
                SELECT MAX(Date) FROM stocks WHERE Ticker = stocks.Ticker AND Date <= ?
            )
            OR Date IN (
                SELECT MAX(Date) FROM stocks WHERE Ticker = stocks.Ticker AND Date <= ?
            )
        """.format(', '.join(f"'{ticker}'" for ticker in MBX_STOCKS.keys()))

        df = pd.read_sql_query(query, conn, params=(start_date.strftime("%Y-%m-%d"), end_date.strftime("%Y-%m-%d")))
        conn.close()

        if df.empty:
            await update.message.reply_text(
                f"Tidak ada data gainers untuk MBX pada periode {period_label.replace('_', ' ')}.",
                parse_mode="Markdown"
            )
            return

        # Pivot data untuk mendapatkan start_price, end_price, start_volume, dan end_volume
        df = df.sort_values('Date').groupby(['Ticker', 'Date']).first().reset_index()
        df_pivot = df.pivot(index='Ticker', columns='Date', values=['Close', 'Volume']).reset_index()
        df_pivot.columns = ['Ticker', 'start_price', 'end_price', 'start_volume', 'end_volume']

        # Hapus baris dengan nilai NaN
        df_pivot = df_pivot.dropna()

        # Hitung persentase perubahan dan nominal transaksi
        df_pivot['change'] = ((df_pivot['end_price'] - df_pivot['start_price']) / df_pivot['start_price']) * 100
        df_pivot['trans_value'] = df_pivot['end_price'] * df_pivot['end_volume']

        # Urutkan semua saham berdasarkan change (tanpa batasan)
        all_gainers = df_pivot.sort_values('change', ascending=False)

        if all_gainers.empty:
            await update.message.reply_text(
                f"Tidak ada data gainers untuk MBX pada periode {period_label.replace('_', ' ')}.",
                parse_mode="Markdown"
            )
            return

        # Siapkan data baris untuk pengiriman
        rows = [
            (
                row['Ticker'],
                row['change'],
                row['end_price'],
                format_number(row['end_volume']),
                format_number(row['trans_value'])
            )
            for _, row in all_gainers.iterrows()
        ]

        # Kirim pesan dengan membagi jika terlalu panjang
        await send_long_message(
            context=context,
            chat_id=update.effective_chat.id,
            header="",
            rows=rows,
            period_label=period_label
        )

        logger.info(f"Top gainers MBX untuk periode {period_label} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in top_gainers_mbx: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data top gainers MBX. Silakan coba lagi.",
            parse_mode="Markdown"
        )

# Fungsi untuk menghitung top gainers ISSI
async def top_gainers_issi(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan top gainers saham ISSI untuk periode tertentu (harian atau N hari)."""
    try:
        # Ambil parameter periode dari args
        period = context.args[0].lower() if context.args else "harian"
        days = 1  # Default untuk harian

        # Jika periode adalah angka, artinya jumlah hari
        try:
            days = int(period)
            period = f"{days}_hari"
        except ValueError:
            if period not in ["harian", "mingguan"]:
                await update.message.reply_text(
                    "Periode tidak valid. Gunakan: 'harian', 'mingguan', atau jumlah hari (contoh: /tgissi 10).",
                    parse_mode="Markdown"
                )
                return
            days = 7 if period == "mingguan" else 1

        # Koneksi ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        # Ambil tanggal terbaru dari database
        cursor.execute("SELECT MAX(date) FROM stocks")
        latest_date = cursor.fetchone()[0]
        if not latest_date:
            await update.message.reply_text("Data saham tidak ditemukan.", parse_mode="Markdown")
            conn.close()
            return

        # Hitung tanggal awal berdasarkan periode
        end_date = datetime.strptime(latest_date, "%Y-%m-%d")
        start_date = end_date - timedelta(days=days)

        # Ambil daftar saham ISSI
        issi_stocks = ISSI_STOCKS.keys()
        gainers = []

        for ticker in issi_stocks:
            try:
                # Ambil harga penutupan pada start_date dan end_date
                cursor.execute(
                    """
                    SELECT close FROM stocks 
                    WHERE ticker = ? AND date <= ? 
                    ORDER BY date DESC LIMIT 1
                    """,
                    (ticker, start_date.strftime("%Y-%m-%d"))
                )
                start_price = cursor.fetchone()
                cursor.execute(
                    """
                    SELECT close FROM stocks 
                    WHERE ticker = ? AND date <= ? 
                    ORDER BY date DESC LIMIT 1
                    """,
                    (ticker, end_date.strftime("%Y-%m-%d"))
                )
                end_price = cursor.fetchone()

                if start_price and end_price:
                    start_price = float(start_price[0])
                    end_price = float(end_price[0])
                    if start_price > 0:
                        percentage_change = ((end_price - start_price) / start_price) * 100
                        gainers.append({
                            "ticker": ticker,
                            "change": percentage_change,
                            "end_price": end_price
                        })
            except Exception as e:
                logger.warning(f"Gagal menghitung perubahan untuk {ticker}: {str(e)}")
                continue

        conn.close()

        if not gainers:
            await update.message.reply_text(
                f"Tidak ada data gainers untuk ISSI pada periode {period.replace('_', ' ')}.",
                parse_mode="Markdown"
            )
            return

        # Urutkan gainers berdasarkan persentase perubahan (descending)
        gainers.sort(key=lambda x: x["change"], reverse=True)
        top_gainers = gainers[:30]  # Ambil top 10

        # Format output dalam tabel Markdown
        message = f"📈 *Top Gainers ISSI ({period.replace('_', ' ')})*\n\n"
        message += "| Saham | Perubahan (%) | Harga Akhir (Rp) |\n"
        message += "|-------|---------------|------------------|\n"
        for gainer in top_gainers:
            ticker = gainer["ticker"]
            change = gainer["change"]
            price = gainer["end_price"]
            change_emoji = "🟢" if change >= 0 else "🔴"
            message += f"| {ticker:<5} | {change_emoji} {change:+.2f} | {price:,.0f} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"Top gainers ISSI untuk periode {period} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in top_gainers_issi: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data top gainers ISSI. Silakan coba lagi.",
            parse_mode="Markdown"
        )
 
