# Fungsi untuk menangani pilihan menu eksplorasi
async def handle_explore_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        user_input = update.message.text.strip().upper()
        logger.info(f"handle_explore_menu dipanggil dengan input: {user_input}")

        # Jika pengguna memilih "⬅️ Kembali ke Menu Crypto"
        if user_input == "⬅️ Kembali ke Menu Crypto":
            context.user_data["menu_state"] = "crypto"
            await show_crypto_menu(update, context)
            return

        # Simulasi pemanggilan fungsi get_crypto_price
        context.args = [user_input]  # Simulasi argumen untuk fungsi get_crypto_price
        try:
            # Panggil fungsi get_crypto_price untuk mengambil informasi kripto
            crypto_info = await get_crypto_price(update, context)

            # Jika fungsi get_crypto_price mengembalikan None atau gagal
            if not crypto_info:
                await update.message.reply_text(
                    f"Informasi untuk *{user_input}* sedang dalam pengembangan. Silakan coba simbol lain!",
                    parse_mode="Markdown"
                )
            else:
                # Format informasi kripto (contoh placeholder)
                # Anda dapat menyesuaikan format ini berdasarkan data yang dikembalikan oleh get_crypto_price
                message = (
                    f"💰 *Informasi {user_input}*\n\n"
                    f"Harga Saat Ini: ${crypto_info.get('price', 'N/A')}\n"
                    f"Perubahan (24 Jam): {crypto_info.get('change_24h', 'N/A')}%\n"
                    f"Kapitalisasi Pasar: ${crypto_info.get('market_cap', 'N/A')}\n"
                    f"Volume (24 Jam): ${crypto_info.get('volume_24h', 'N/A')}\n"
                )
                await update.message.reply_text(message, parse_mode="Markdown")

        except Exception as e:
            logger.error(f"Error saat mengambil informasi kripto untuk {user_input}: {str(e)}")
            await update.message.reply_text(
                f"Informasi untuk *{user_input}* sedang dalam pengembangan. Silakan coba simbol lain!",
                parse_mode="Markdown"
            )

        # Tampilkan kembali menu Crypto setelah interaksi
        context.user_data["menu_state"] = "crypto"
        await show_crypto_menu(update, context)

    except Exception as e:
        logger.error(f"Error di handle_explore_menu: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat memproses simbol koin. Silakan coba lagi.",
            parse_mode="Markdown"
        )
        # Tampilkan kembali menu Crypto
        context.user_data["menu_state"] = "crypto"
        await show_crypto_menu(update, context)

# Fungsi untuk menangani pencarian simbol
async def handle_search_symbol(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if "explore_mode" not in context.user_data or context.user_data["explore_mode"] != "search_symbol":
        return

    user_input = update.message.text.strip().upper()
    if user_input == "Cancel":
        context.user_data.pop("explore_mode", None)
        await explore(update, context)
        return
    if not await check_user_access(update, context):
        return
    try:
        conn = sqlite3.connect("coins.db")
        cursor = conn.cursor()

        cursor.execute("SELECT MAX(timestamp) FROM coins")
        latest_timestamp = cursor.fetchone()[0]
        if not latest_timestamp:
            await update.message.reply_text("Data cryptocurrency tidak ditemukan. Silakan coba lagi nanti.")
            conn.close()
            return

        cursor.execute('''
            SELECT c.symbol, c.name, c.price_usd, c.percent_change_24h, cm.website
            FROM coins c
            JOIN coin_metadata cm ON c.symbol = cm.symbol
            WHERE c.timestamp = ? AND c.symbol = ?
        ''', (latest_timestamp, user_input))
        coin = cursor.fetchone()

        if coin:
            symbol, name, price, change, website = coin
            response = f"💰 *{name} ({symbol})*\n\n"
            response += f"Harga: ${price:,.2f}\nPerubahan 24h: {change:+.2f}%\nWebsite: {website}"
        else:
            response = f"Koin dengan simbol {user_input} tidak ditemukan."

        conn.close()
        await update.message.reply_text(response, parse_mode="Markdown")

        # Kembali ke menu eksplorasi
        context.user_data.pop("explore_mode", None)
        await explore(update, context)

    except Exception as e:
        logger.error(f"Error in handle_search_symbol: {str(e)}")
        await update.message.reply_text(f"Terjadi kesalahan: {str(e)}")
        # Kembali ke menu eksplorasi meskipun ada error
        context.user_data.pop("explore_mode", None)
        await explore(update, context)
        

