# Fungsi baru untuk Top Gainers berdasarkan tanggal
async def top_gainers_filtered(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan Top Gainers untuk indeks tertentu pada tanggal spesifik."""
    try:
        # Validasi argumen
        if len(context.args) != 2:
            await update.message.reply_text(
                "Gunakan: /tgf <index> yyyy-mm-dd\nContoh: /tgf LQ45 2025-01-31",
                parse_mode="Markdown"
            )
            return

        index = context.args[0].upper()
        date_str = context.args[1]

        # Validasi indeks
        if index not in INDEX_STOCKS:
            await update.message.reply_text(
                f"Indeks tidak valid. Pilih dari: {', '.join(INDEX_STOCKS.keys())}",
                parse_mode="Markdown"
            )
            return

        # Validasi format tanggal
        try:
            target_date = datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            await update.message.reply_text(
                "Format tanggal tidak valid. Gunakan yyyy-mm-dd (contoh: 2025-01-31).",
                parse_mode="Markdown"
            )
            return

        # Ambil tanggal sebelumnya (1 hari sebelumnya untuk perhitungan perubahan)
        prev_date = target_date - timedelta(days=1)
        target_date_str = target_date.strftime('%Y-%m-%d')
        prev_date_str = prev_date.strftime('%Y-%m-%d')

        # Koneksi ke database
        conn = DB_CONNECTION
        cursor = conn.cursor()

        # Cek apakah tanggal tersedia di database
        cursor.execute("SELECT DISTINCT Date FROM stocks WHERE Date IN (?, ?)", (target_date_str, prev_date_str))
        available_dates = set(row[0] for row in cursor.fetchall())
        if target_date_str not in available_dates:
            cursor.execute("SELECT MAX(Date) FROM stocks")
            max_date = cursor.fetchone()[0]
            await update.message.reply_text(
                f"Tidak ada data untuk tanggal {target_date_str}. Data terakhir tersedia pada {max_date}.",
                parse_mode="Markdown"
            )
            return
        if prev_date_str not in available_dates:
            cursor.execute("SELECT MIN(Date) FROM stocks")
            min_date = cursor.fetchone()[0]
            await update.message.reply_text(
                f"Tidak ada data untuk tanggal sebelumnya ({prev_date_str}) untuk menghitung perubahan. "
                f"Data paling awal tersedia pada {min_date}.",
                parse_mode="Markdown"
            )
            return

        # Ambil daftar saham dari indeks
        stocks = INDEX_STOCKS[index]
        stock_symbols = list(stocks.keys())

        # Query untuk harga penutupan, volume pada tanggal target dan tanggal sebelumnya
        query = """
            SELECT s1.Ticker, s1.Close as close_target, s2.Close as close_prev, s1.Volume as volume_target
            FROM stocks s1
            LEFT JOIN stocks s2 ON s1.Ticker = s2.Ticker AND s2.Date = ?
            WHERE s1.Ticker IN ({}) AND s1.Date = ?
        """.format(','.join('?' * len(stock_symbols)))

        params = [prev_date_str] + stock_symbols + [target_date_str]
        cursor.execute(query, params)
        data = cursor.fetchall()

        if not data:
            await update.message.reply_text(
                f"Tidak ada data untuk indeks {index} pada tanggal {target_date_str}.",
                parse_mode="Markdown"
            )
            return

        # Hitung persentase perubahan dan total nilai transaksi
        gainers = []
        for row in data:
            ticker, close_target, close_prev, volume_target = row
            if close_target and close_prev and volume_target:  # Pastikan data tidak None
                change_pct = ((close_target - close_prev) / close_prev) * 100
                total_value = close_target * volume_target if volume_target else 0
                gainers.append({
                    'symbol': ticker,
                    'name': stocks.get(ticker, ticker),
                    'close': close_target,
                    'volume': volume_target,
                    'total_value': total_value,
                    'change_pct': change_pct
                })

        # Urutkan berdasarkan perubahan persentase (descending) dan ambil top 10
        gainers.sort(key=lambda x: x['change_pct'], reverse=True)
        top_gainers = gainers[:10]

        # Format output dengan singkatan total nilai
        message = f"📈 *Top Gainers {index} pada {target_date_str}*\n\n"
        message += "| Saham | Harga (Rp) | Volume | Total Nilai | Perubahan (%) |\n"
        message += "|-------|------------|--------|-------------|---------------|\n"
        for gainer in top_gainers:
            # Format total nilai dengan singkatan
            total_value = gainer['total_value']
            if total_value >= 1_000_000_000_000:  # Triliun
                total_value_str = f"{total_value / 1_000_000_000_000:,.1f}T"
            elif total_value >= 1_000_000_000:    # Miliar
                total_value_str = f"{total_value / 1_000_000_000:,.1f}B"
            elif total_value >= 1_000_000:        # Juta
                total_value_str = f"{total_value / 1_000_000:,.1f}M"
            else:
                total_value_str = f"{total_value:,.0f}"

            message += f"| {gainer['symbol']} ({gainer['name'][:20]}) | {gainer['close']:,.2f} | {gainer['volume']:,.0f} | {total_value_str} | {gainer['change_pct']:+.2f} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"Top Gainers untuk {index} pada {target_date_str} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in top_gainers_filtered: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat memproses Top Gainers. Silakan coba lagi.",
            parse_mode="Markdown"
        )
    finally:
        cursor.close()

