        query = update.callback_query
        if query:
            await query.answer()
            index = query.data.split('_')[1]  # heatmap_kompas100 -> kompas100
        else:
            if len(context.args) < 1:
                await context.bot.send_message(
                    chat_id=update.effective_chat.id,
                    text="Masukkan indeks dan periode (opsional), contoh: /ih kompas100 harian atau /ih lq45 2025-03-05"
                )
                return
            index = context.args[0].lower()

