        df_pivot['CompanyName'] = df.groupby('Ticker')['CompanyName'].first()

        df_pivot['Change (%)'] = (df_pivot[end_date] - df_pivot[start_date]) / df_pivot[start_date] * 100
        df_pivot = df_pivot.dropna(subset=['Change (%)'])
        df_pivot = df_pivot.sort_values(by='Change (%)', ascending=False)

        if df_pivot.empty:
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text="Tidak ada data yang cukup untuk menghitung perubahan harga."
            )
            return

        # Siapkan data untuk heatmap
        heatmap_data = pd.DataFrame(df_pivot['Change (%)'])
        heatmap_data.columns = ['Change (%)']

        # Buat colormap seperti pada gambar (merah ke hijau)
        colors = [
            (1, 0, 0),
            (1, 0.5, 0.5),
            (1, 1, 1),
            (0.5, 1, 0.5),
            (0, 0.5, 0)
        ]
        cmap = LinearSegmentedColormap.from_list("custom_cmap", colors, N=256)

        # Tentukan jumlah saham per bagian (untuk membagi heatmap)
        num_stocks = len(heatmap_data)
        max_stocks_per_image = 50  # Batasi 50 saham per gambar
        dpi = 150  # Kurangi DPI untuk mengurangi dimensi piksel
        chart_paths = []

        # Bagi heatmap menjadi beberapa bagian jika terlalu banyak saham
        for i in range(0, num_stocks, max_stocks_per_image):
            subset_data = heatmap_data[i:i + max_stocks_per_image]
            subset_num_stocks = len(subset_data)

            # Hitung tinggi gambar berdasarkan jumlah saham di subset
            height_per_stock = 0.3
            fig_height = max(5, subset_num_stocks * height_per_stock)  # Tinggi minimum 5 inci
