async def crypto_indodax(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan top 20 cryptocurrency dari Indodax berdasarkan volume dengan persentase perubahan 24 jam."""
    try:
        # Panggil API Indodax untuk data ticker
        response = requests.get("https://indodax.com/api/ticker_all")
        if response.status_code != 200:
            logger.error(f"Gagal mengambil data ticker dari Indodax: status {response.status_code}")
            await update.message.reply_text("Gagal mengambil data ticker dari Indodax. Silakan coba lagi nanti.")
            return

        data = response.json()
        tickers = data.get("tickers", {})
        if not tickers:
            logger.warning("Tidak ada data ticker dari Indodax")
            await update.message.reply_text("Tidak ada data harga crypto yang tersedia.")
            return

        # Panggil API Indodax untuk data summaries (untuk volume)
        response_summaries = requests.get("https://indodax.com/api/summaries")
        if response_summaries.status_code != 200:
            logger.error(f"Gagal mengambil data summaries dari Indodax: status {response_summaries.status_code}")
            await update.message.reply_text("Gagal mengambil data summaries dari Indodax. Silakan coba lagi nanti.")
            return

        summaries = response_summaries.json().get("tickers", {})
        if not summaries:
            logger.warning("Tidak ada data summaries dari Indodax")
            await update.message.reply_text("Tidak ada data summaries yang tersedia.")
            return

        # Buat list untuk menyimpan data crypto dengan volume
        crypto_list = []
        for pair, info in tickers.items():
            price = float(info["last"])
            price_24h = float(info["last_24hours"]) if "last_24hours" in info else price
            # Hitung persentase perubahan
            change_24h = ((price - price_24h) / price_24h * 100) if price_24h != 0 else 0
            # Ambil volume dari summaries
            volume = float(summaries.get(pair, {}).get("vol_idr", 0))
            # Ganti _ dengan spasi untuk menghindari masalah parsing
            pair_clean = pair.replace("_", " ").upper()
            crypto_list.append({
                "pair": pair_clean,
                "price": price,
                "change_24h": change_24h,
                "volume": volume
            })

        # Urutkan berdasarkan volume (descending) dan ambil top 20
        crypto_list.sort(key=lambda x: x["volume"], reverse=True)
        crypto_list = crypto_list[:20]  # Batasi ke top 20

        # Format output dalam bentuk tabel Markdown
        message = "📈 *Harga Cryptocurrency di Indodax (Top 20 Volume)*\n\n"
        message += "| Crypto   | Harga (Rp)    | Perubahan 24h (%) |\n"
        message += "|----------|---------------|-------------------|\n"

        for crypto in crypto_list:
            pair = crypto["pair"]
            price = crypto["price"]
            change_24h = crypto["change_24h"]
            # Tambahkan emoji berdasarkan perubahan
            change_emoji = "🟢" if change_24h >= 0 else "🔴"
            message += f"| {pair:<8} | {price:,.0f} | {change_emoji} {change_24h:+.1f} |\n"

        logger.info(f"Mengirim harga crypto: {message}")
        await update.message.reply_text(message, parse_mode="Markdown")

    except Exception as e:
        logger.error(f"Error in crypto_indodax: {str(e)}")
        await update.message.reply_text("Terjadi kesalahan saat mengambil harga crypto.")

logger = logging.getLogger(__name__)

