async def buy_simulation_db(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        # Parse argumen
        args = context.args
        if not args or len(args) != 4:
            await update.message.reply_text(
                "Format perintah salah. Gunakan: /buy <jumlah_saham> <indeks> <tahun1>-<bulan1>-<tanggal1> <tahun2>-<bulan2>-<tanggal2>\n"
                "Contoh: /buy 1 LQ45 2025-01-31 2025-06-12",
                parse_mode="Markdown"
            )
            return

        num_stocks, index, date1_str, date2_str = args
        try:
            num_stocks = int(num_stocks)
            if num_stocks <= 0:
                raise ValueError("Jumlah saham harus lebih dari 0")
        except ValueError:
            await update.message.reply_text(
                "Jumlah saham harus berupa angka positif.",
                parse_mode="Markdown"
            )
            return

        index = index.upper()
        if index not in INDEX_STOCKS:
            await update.message.reply_text(
                f"Indeks {index} tidak dikenal. Indeks yang tersedia: {', '.join(INDEX_STOCKS.keys())}",
                parse_mode="Markdown"
            )
            return

        # Validasi tanggal
        try:
            date1 = date1_str
            date2 = date2_str
            if date2 <= date1:
                raise ValueError("Tanggal jual harus setelah tanggal beli")
        except ValueError as e:
            await update.message.reply_text(
                f"Format tanggal salah atau {str(e)}. Gunakan YYYY-MM-DD.",
                parse_mode="Markdown"
            )
            return

        # Ambil semua saham dari indeks
        stocks = INDEX_STOCKS.get(index)
        if not stocks:
            await update.message.reply_text(
                f"Tidak ada saham yang tersedia untuk indeks {index}.",
                parse_mode="Markdown"
            )
            return

        # Hubungkan ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        # Buat header tabel
        table = "| Saham | Harga Beli (Rp) | Harga Jual (Rp) | Lot | Status |\n"
        table += "|-------|-----------------|-----------------|-----|--------|\n"

        total_profit = 0
        total_buy_price = 0
        total_sell_price = 0
        max_profit = float('-inf')
        max_loss = float('inf')
        max_profit_stock = ""
        max_loss_stock = ""
        rows = []

        for symbol in stocks:
            try:
                # Ambil harga beli (cari tanggal terdekat sebelum atau pada date1)
                cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? AND Date <= ? ORDER BY Date DESC LIMIT 1", (symbol, date1))
                buy_data = cursor.fetchone()
                buy_price = float(buy_data[0]) if buy_data else None

                # Jika tidak ada data untuk date1, ambil harga terdekat sebelumnya
                if buy_price is None:
                    cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? AND Date <= ? ORDER BY Date DESC", (symbol, date1))
                    buy_data_list = cursor.fetchall()
                    buy_price = float(buy_data_list[0][0]) if buy_data_list else 0

                # Ambil harga jual (cari tanggal terdekat sebelum atau pada date2)
                cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? AND Date <= ? ORDER BY Date DESC LIMIT 1", (symbol, date2))
                sell_data = cursor.fetchone()
                sell_price = float(sell_data[0]) if sell_data else buy_price

                # Hitung lot berdasarkan num_stocks (1 lot = 100 saham per saham)
                lot = num_stocks * 100
                # Hitung profit/loss per saham
                status = (sell_price - buy_price) * lot
                total_profit += status
                total_buy_price += buy_price * lot
                total_sell_price += sell_price * lot

                # Update max profit dan max loss
                if status > max_profit:
                    max_profit = status
                    max_profit_stock = symbol
                if status < max_loss:
                    max_loss = status
                    max_loss_stock = symbol

                # Format status dengan indikator warna
                status_text = f"{'🟢 +' if status >= 0 else '🔴 -'}Rp {abs(status):,.2f}"
                rows.append(f"| {symbol} | {buy_price:,.2f} | {sell_price:,.2f} | {lot} | {status_text} |\n")
            except Exception as e:
                logging.error(f"Gagal mengambil data untuk {symbol} pada {date1}/{date2}: {str(e)}")
                rows.append(f"| {symbol} | - | - | {lot} | Gagal |\n")

        conn.close()

        # Gabungkan baris menjadi tabel
        full_table = table + "".join(rows)
        # Tambahkan total profit/loss, total harga beli, total nominal jual, dan saham dengan untung/rugi terbesar
        total_status = f"{'🟢 Keuntungan' if total_profit >= 0 else '🔴 Kerugian'}: Rp {abs(total_profit):,.2f}"
        full_table += f"\n**{total_status}**"
        full_table += f"\n**Total Harga Beli: Rp {total_buy_price:,.2f}**"
        full_table += f"\n**Total Nominal Jual: Rp {total_sell_price:,.2f}**"
        full_table += f"\n**Saham dengan Keuntungan Terbesar: {max_profit_stock} (Rp {max_profit:,.2f})**"
        full_table += f"\n**Saham dengan Rugi Terbesar: {max_loss_stock} (Rp {max_loss:,.2f})**"

        # Bagi pesan jika terlalu panjang (batas ~4000 karakter)
        MAX_MESSAGE_LENGTH = 4000
        if len(full_table) > MAX_MESSAGE_LENGTH:
            parts = [full_table[i:i + MAX_MESSAGE_LENGTH] for i in range(0, len(full_table), MAX_MESSAGE_LENGTH)]
            for i, part in enumerate(parts):
                if i == 0:
                    await update.message.reply_text(
                        f"📊 *Simulasi Beli Saham ({index})*\n\n"
                        f"Periode: {date1} (Beli) - {date2} (Jual)\n\n"
                        f"{part}",
                        parse_mode="Markdown"
                    )
                else:
                    await update.message.reply_text(
                        f"(lanjutan {i+1})\n\n{part}",
                        parse_mode="Markdown"
                    )
        else:
            await update.message.reply_text(
                f"📊 *Simulasi Beli Saham ({index})*\n\n"
                f"Periode: {date1} (Beli) - {date2} (Jual)\n\n"
                f"{full_table}",
                parse_mode="Markdown"
            )

    except Exception as e:
        logging.error(f"Error di buy_simulation_db: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat melakukan simulasi. Silakan coba lagi atau periksa input Anda.",
            parse_mode="Markdown"
        )
# Path untuk file transaksi sementara
TRANSACTION_FILE = "transactions.json"        

# Fungsi untuk memuat transaksi dari file
def load_transactions():
    try:
        with open(TRANSACTION_FILE, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {"buys": [], "sells": []}
    except json.JSONDecodeError:
        logging.error(f"File {TRANSACTION_FILE} rusak atau tidak valid, menginisialisasi ulang.")
        return {"buys": [], "sells": []}

# Fungsi untuk menyimpan transaksi ke file
def save_transactions(transactions):
    try:
        with open(TRANSACTION_FILE, 'w') as f:
            json.dump(transactions, f, indent=4)
    except Exception as e:
        logging.error(f"Gagal menyimpan ke {TRANSACTION_FILE}: {str(e)}")

# Fungsi untuk simulasi pembelian per saham
async def buy_single_stock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    try:
        # Parse argumen
        args = context.args
        if not args or len(args) != 4:
            await update.message.reply_text(
                "Format perintah salah. Gunakan: /buys <ticker> <lot> <tahun1>-<bulan1>-<tanggal1> <tahun2>-<bulan2>-<tanggal2>\n"
                "Contoh: /buys TLKM 1 2025-06-05 2025-06-06",
                parse_mode="Markdown"
            )
            return

        ticker, lot_str, date1_str, date2_str = args
        ticker = ticker.upper()
        try:
            lot = int(lot_str)
            if lot <= 0:
                raise ValueError("Jumlah lot harus lebih dari 0")
        except ValueError:
            await update.message.reply_text(
                "Jumlah lot harus berupa angka positif.",
                parse_mode="Markdown"
            )
            return

        # Validasi tanggal
        try:
            date1 = date1_str
            date2 = date2_str
            if date2 <= date1:
                raise ValueError("Tanggal jual harus setelah tanggal beli")
        except ValueError as e:
            await update.message.reply_text(
                f"Format tanggal salah atau {str(e)}. Gunakan YYYY-MM-DD.",
                parse_mode="Markdown"
            )
            return

        # Cek apakah ticker valid (berdasarkan semua indeks)
        all_stocks = []
        for stocks in INDEX_STOCKS.values():
            all_stocks.extend(stocks)
        if ticker not in all_stocks:
            await update.message.reply_text(
                f"Ticker {ticker} tidak dikenal. Cek ticker yang tersedia di indeks LQ45, KOMPAS100, JII70, MBX, atau ISSI.",
                parse_mode="Markdown"
            )
            return

        # Hubungkan ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        try:
            # Ambil harga beli (cari tanggal terdekat sebelum atau pada date1)
            cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? AND Date <= ? ORDER BY Date DESC LIMIT 1", (ticker, date1))
            buy_data = cursor.fetchone()
            buy_price = float(buy_data[0]) if buy_data else None

            # Jika tidak ada data untuk date1, ambil harga terdekat sebelumnya
            if buy_price is None:
                cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? AND Date <= ? ORDER BY Date DESC", (ticker, date1))
                buy_data_list = cursor.fetchall()
                buy_price = float(buy_data_list[0][0]) if buy_data_list else 0

            # Hitung total beli (1 lot = 100 saham)
            total_buy = buy_price * (lot * 100)

            # Simpan transaksi pembelian
            transactions = load_transactions()
            transactions["buys"].append({
                "ticker": ticker,
                "lot": lot,
                "date_buy": date1,
                "price_buy": buy_price,
                "total_buy": total_buy
            })
            save_transactions(transactions)

            # Buat tabel
            table = "| Saham | Harga Beli (Rp) | Lot | Total Beli (Rp) | Tanggal Beli |\n"
            table += "|-------|-----------------|-----|-----------------|--------------|\n"
            table += f"| {ticker} | {buy_price:,.2f} | {lot * 100} | {total_buy:,.2f} | {date1} |\n"

            # Kirim tabel ke pengguna
            await update.message.reply_text(
                f"📊 *Simulasi Beli Saham ({ticker})*\n\n"
                f"Tanggal Beli: {date1}\n\n"
                f"{table}",
                parse_mode="Markdown"
            )

        except Exception as e:
            logging.error(f"Gagal mengambil data untuk {ticker} pada {date1}: {str(e)}")
            await update.message.reply_text(
                f"Terjadi kesalahan saat mengambil data untuk {ticker}. Silakan coba lagi. Error: {str(e)}",
                parse_mode="Markdown"
            )
        finally:
            conn.close()

    except Exception as e:
        logging.error(f"Error di buy_single_stock: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat melakukan simulasi. Silakan coba lagi atau periksa input Anda.",
            parse_mode="Markdown"
        )
        
# Pastikan file transactions.json ada dan valid
if not os.path.exists(TRANSACTIONS_FILE):
    with open(TRANSACTIONS_FILE, "w") as f:
        json.dump({}, f)  # Inisialisasi sebagai dictionary kosong untuk user_id

def get_user_transactions(user_id):
    """Ambil transaksi dari akun aktif pengguna"""
    try:
        account_file = get_user_account_file(user_id)
        if not os.path.exists(account_file):
            logger.info(f"Tidak ada file akun untuk user {user_id}")
            return []
        
        with file_lock:
            with open(account_file, "r", encoding="utf-8") as f:
                data = json.load(f)
        
        active_account = data.get("active_account", "account_1")
        if active_account not in data["accounts"]:
            logger.error(f"Akun aktif {active_account} tidak ditemukan untuk user {user_id}")
            return []
        
        transactions = data["accounts"][active_account].get("transactions", [])
        logger.info(f"Ditemukan {len(transactions)} transaksi untuk user {user_id} di akun {active_account}")
        for tx in transactions:
            if tx.get("status") == "open":
                logger.info(f"Transaksi open ditemukan: {tx['ticker']}, {tx['lot']} lot, harga beli Rp {tx['buy_price']:,.2f}")
        return transactions
    except Exception as e:
        logger.error(f"Error mengambil transaksi untuk user {user_id}: {str(e)}")
        return []


def save_user_transactions(user_id, transactions):
    try:
        # Load existing data, default to empty dict if file is invalid
        try:
            with open(TRANSACTIONS_FILE, "r") as f:
                data = json.load(f)
        except json.JSONDecodeError:
            data = {}

        data[str(user_id)] = transactions
        with open(TRANSACTIONS_FILE, "w") as f:
            json.dump(data, f, indent=4)
    except Exception as e:
        logging.error(f"Error saving transactions: {str(e)}")

