async def sell_stock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.message.from_user.id
    try:
        args = context.args
        if not args or len(args) != 2:
            await update.message.reply_text(
                "Format perintah salah. Gunakan: /jual <lot> <ticker>\n"
                "Contoh: /jual 1 BBRI",
                parse_mode="Markdown"
            )
            return

        lot, ticker = args
        try:
            lot = int(lot)
            if lot <= 0:
                raise ValueError("Lot harus lebih dari 0")
        except ValueError:
            await update.message.reply_text(
                "Lot harus berupa angka positif.",
                parse_mode="Markdown"
            )
            return

        ticker = ticker.upper()

        transactions = get_user_transactions(user_id)
        if not transactions:
            await update.message.reply_text(
                "Belum ada transaksi pembelian saham.",
                parse_mode="Markdown"
            )
            return

        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        cursor.execute("SELECT Close FROM stocks WHERE Ticker = ? ORDER BY Date DESC LIMIT 1", (ticker,))
        sell_data = cursor.fetchone()
        sell_price = float(sell_data[0]) if sell_data else 0

        if sell_price == 0:
            await update.message.reply_text(
                f"Tidak ada data harga terbaru untuk {ticker}.",
                parse_mode="Markdown"
            )
            conn.close()
            return

        total_pl = 0
        transaction_found = False
        updated_transactions = []

        for tx in transactions:
            if tx["status"] == "open" and tx["ticker"] == ticker:
                transaction_found = True
                current_lot = tx["lot"]
                buy_price = tx["buy_price"]

                if lot >= current_lot:
                    pl = (sell_price - buy_price) * current_lot * 100
                    total_pl += pl
                    tx["status"] = "closed"
                    updated_transactions.append(tx)
                    await update.message.reply_text(
                        f"✅ Penjualan {current_lot} lot {ticker} berhasil. Harga jual: Rp {sell_price:,.2f}, "
                        f"{'🟢 Keuntungan' if pl >= 0 else '🔴 Kerugian'}: Rp {abs(pl):,.2f}",
                        parse_mode="Markdown"
                    )
                else:
                    pl = (sell_price - buy_price) * lot * 100
                    total_pl += pl
                    tx["lot"] = current_lot - lot
                    updated_transactions.append(tx)
                    await update.message.reply_text(
                        f"✅ Penjualan {lot} lot {ticker} berhasil. Harga jual: Rp {sell_price:,.2f}, "
                        f"{'🟢 Keuntungan' if pl >= 0 else '🔴 Kerugian'}: Rp {abs(pl):,.2f}",
                        parse_mode="Markdown"
                    )
            else:
                updated_transactions.append(tx)

        if not transaction_found:
            await update.message.reply_text(
                f"Tidak ada transaksi terbuka untuk {ticker}.",
                parse_mode="Markdown"
            )
        else:
            save_user_transactions(user_id, updated_transactions)

        conn.close()

    except Exception as e:
        logging.error(f"Error di sell_stock: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat menjual saham. Silakan coba lagi.",
            parse_mode="Markdown"
        )

