async def analyze_report(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.message.from_user.id
    try:
        transactions = get_user_transactions(user_id)

        if not transactions:
            await update.message.reply_text(
                "Belum ada transaksi pembelian saham."
            )
            return

        conn = sqlite3.connect("stock_data.db")
        cursor = conn.cursor()

        ticker_summary = {}
        for tx in transactions:
            if tx["status"] == "open":
                ticker = tx["ticker"]
                if ticker not in ticker_summary:
                    ticker_summary[ticker] = {"total_lot": 0, "total_cost": 0}
                ticker_summary[ticker]["total_lot"] += tx["lot"]
                ticker_summary[ticker]["total_cost"] += tx["buy_price"] * tx["lot"] * 100

        table = "| Saham | Total Lot | Rata-rata Harga Beli (Rp) | Harga Sekarang (Rp) | Total P/L (Rp) |\n"
        table += "|-------|-----------|---------------------------|---------------------|-----------------|\n"

        total_pl = 0
        for ticker, data in ticker_summary.items():
            total_lot = data["total_lot"]
            total_cost = data["total_cost"]
            avg_buy_price = total_cost / (total_lot * 100)

            cursor.execute("SELECT Close FROM stocks WHERE symbol = ? ORDER BY Date DESC LIMIT 1", (ticker,))
            current_data = cursor.fetchone()
            current_price = float(current_data[0]) if current_data else avg_buy_price

            pl = (current_price - avg_buy_price) * total_lot * 100
            total_pl += pl
            pl_text = f"{'🟢 +' if pl >= 0 else '🔴 -'}Rp {abs(pl):,.2f}"

            table += f"| {ticker} | {total_lot} | {avg_buy_price:,.2f} | {current_price:,.2f} | {pl_text} |\n"

        conn.close()

        total_pl_text = f"{'🟢 Total Keuntungan' if total_pl >= 0 else '🔴 Total Kerugian'}: Rp {abs(total_pl):,.2f}"
        message = (
            f"📊 Analisa Laporan Konsolidasi\n\n"
            f"Per tanggal: {datetime.now(pytz.timezone('Asia/Jakarta')).strftime('%Y-%m-%d %H:%M WIB')}\n\n"
            f"{table}\n"
            f"{total_pl_text}"
        )

        await update.message.reply_text(message)

    except Exception as e:
        logging.error(f"Error di analyze_report: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat menghasilkan analisa laporan. Silakan coba lagi."
        )  
        
