async def top_gainers_by_volume(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan saham dengan kenaikan volume signifikan dan kenaikan harga."""
    try:
        # Parsing argumen
        args = context.args
        index_filter = None
        date_str = None

        if args:
            if args[0].lower() in ["kompas", "lq", "mbx", "issi"]:
                index_filter = args[0].lower()
                date_str = args[1] if len(args) > 1 else None
            else:
                date_str = args[0]

        # Validasi format tanggal
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        
        if date_str:
            try:
                end_date = datetime.strptime(date_str, "%Y-%m-%d")
            except ValueError:
                conn.close()
                await update.message.reply_text(
                    "Format tanggal tidak valid. Gunakan: /tgv [index] yyyy-mm-dd (contoh: /tgv 2025-04-25 atau /tgv kompas 2025-04-25).",
                    parse_mode="Markdown"
                )
                return
        else:
            cursor.execute("SELECT MAX(date) FROM stocks")
            latest_date = cursor.fetchone()[0]
            if not latest_date:
                conn.close()
                await update.message.reply_text("Data saham tidak ditemukan.", parse_mode="Markdown")
                return
            end_date = datetime.strptime(latest_date, "%Y-%m-%d")

        # Tentukan prev_day untuk perbandingan
        prev_day = end_date - timedelta(days=1)

        # Tentukan daftar saham berdasarkan indeks
        if index_filter == "kompas":
            stocks = KOMPAS100_STOCKS.keys()
        elif index_filter == "lq":
            stocks = LQ45_STOCKS.keys()
        elif index_filter == "mbx":
            stocks = MBX_STOCKS.keys()
        elif index_filter == "issi":
            stocks = ISSI_STOCKS.keys()
        else:
            stocks = set(list(LQ45_STOCKS.keys()) + list(KOMPAS100_STOCKS.keys()) + 
                         list(MBX_STOCKS.keys()) + list(ISSI_STOCKS.keys()))

        # Inisialisasi hasil
        results = []

        for ticker in stocks:
            try:
                # Ambil volume pada end_date dan prev_day
                cursor.execute(
                    """
                    SELECT volume FROM stocks 
                    WHERE ticker = ? AND date = ? 
                    LIMIT 1
                    """,
                    (ticker, end_date.strftime("%Y-%m-%d"))
                )
                current_volume = cursor.fetchone()
                cursor.execute(
                    """
                    SELECT volume FROM stocks 
                    WHERE ticker = ? AND date = ? 
                    LIMIT 1
                    """,
                    (ticker, prev_day.strftime("%Y-%m-%d"))
                )
                prev_volume = cursor.fetchone()

                # Ambil harga penutupan pada end_date dan prev_day
                cursor.execute(
                    """
                    SELECT close FROM stocks 
                    WHERE ticker = ? AND date = ? 
                    LIMIT 1
                    """,
                    (ticker, end_date.strftime("%Y-%m-%d"))
                )
                current_price = cursor.fetchone()
                cursor.execute(
                    """
                    SELECT close FROM stocks 
                    WHERE ticker = ? AND date = ? 
                    LIMIT 1
                    """,
                    (ticker, prev_day.strftime("%Y-%m-%d"))
                )
                prev_price = cursor.fetchone()

                if prev_volume and current_volume and current_price and prev_price and prev_volume[0] > 0:
                    prev_volume = float(prev_volume[0])
                    current_volume = float(current_volume[0])
                    current_price = float(current_price[0])
                    prev_price = float(prev_price[0])
                    volume_change = ((current_volume - prev_volume) / prev_volume) * 100
                    price_change = ((current_price - prev_price) / prev_price) * 100 if prev_price > 0 else 0
                    # Hanya simpan jika kenaikan volume signifikan (>5%)
                    if volume_change > 5:
                        # Hitung nilai transaksi
                        transaction_value = current_price * current_volume
                        # Konversi ke format singkat dan jelas
                        if transaction_value >= 1e12:  # Triliun
                            transaction_value_str = f"{transaction_value / 1e12:.1f}T"
                        elif transaction_value >= 1e9:  # Miliar
                            transaction_value_str = f"{transaction_value / 1e9:.1f}B"
                        elif transaction_value >= 1e6:  # Juta
                            transaction_value_str = f"{transaction_value / 1e6:.0f}M"
                        else:
                            transaction_value_str = f"{transaction_value:,.0f}"
                        results.append({
                            "ticker": ticker,
                            "volume_change": volume_change,
                            "price_change": price_change,
                            "end_price": current_price,
                            "transaction_value": transaction_value_str
                        })
                else:
                    logger.warning(f"Data volume atau harga tidak lengkap untuk {ticker} pada {end_date.strftime('%Y-%m-%d')}")

            except Exception as e:
                logger.warning(f"Gagal memproses {ticker}: {str(e)}")
                continue

        conn.close()

        if not results:
            index_name = index_filter.upper() if index_filter else "Semua Indeks"
            date_str = end_date.strftime('%Y-%m-%d')
            message = f"Tidak ada saham di {index_name} dengan kenaikan volume signifikan pada {date_str}."
            await update.message.reply_text(message, parse_mode="Markdown")
            return

        # Urutkan berdasarkan persentase kenaikan volume (descending)
        results.sort(key=lambda x: x["volume_change"], reverse=True)
        top_results = results[:30]  # Ambil top 30

        # Format output dalam tabel Markdown
        index_name = index_filter.upper() if index_filter else "Semua Indeks"
        date_str = end_date.strftime('%Y-%m-%d')
        message = f"📊 *Saham dengan Kenaikan Volume Signifikan ({index_name}, {date_str})*\n\n"
        message += "| Saham | Kenaikan Volume (%) | Kenaikan Harga (%) | Harga Akhir (Rp) | Nilai Transaksi |\n"
        message += "|-------|---------------------|--------------------|------------------|-----------------|\n"
        for result in top_results:
            ticker = result["ticker"]
            volume_change = result["volume_change"]
            price_change = result["price_change"]
            price = result["end_price"]
            transaction_value = result["transaction_value"]
            volume_change_emoji = "🟢" if volume_change >= 0 else "🔴"
            price_change_emoji = "🟢" if price_change >= 0 else "🔴"
            message += f"| {ticker:<5} | {volume_change_emoji} {volume_change:+.2f} | {price_change_emoji} {price_change:+.2f} | {price:,.0f} | {transaction_value} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"TGV untuk {index_name} pada {date_str} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in top_gainers_by_volume: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data. Silakan coba lagi.",
            parse_mode="Markdown"
        )
        
async def bottom_bollinger_bands(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan saham yang berada di dekat atau di bawah lower Bollinger Bands pada tanggal tertentu."""
    try:
        args = context.args
        index_filter = None
        date_str = None

        # Parsing argumen
        if args:
            if args[0].lower() in ["kompas", "lq", "mbx", "issi"]:
                index_filter = args[0].lower()
                date_str = args[1] if len(args) > 1 else None
            else:
                date_str = args[0]

        # Validasi format tanggal
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        
        if date_str:
            try:
                end_date = datetime.strptime(date_str, "%Y-%m-%d")
            except ValueError:
                conn.close()
                await update.message.reply_text(
                    "Format tanggal tidak valid. Gunakan: /bb [index] yyyy-mm-dd (contoh: /bb 2025-04-25 atau /bb kompas 2025-04-25).",
                    parse_mode="Markdown"
                )
                return
        else:
            cursor.execute("SELECT MAX(date) FROM stocks")
            latest_date = cursor.fetchone()[0]
            if not latest_date:
                conn.close()
                await update.message.reply_text("Data saham tidak ditemukan.", parse_mode="Markdown")
                return
            end_date = datetime.strptime(latest_date, "%Y-%m-%d")

        # Tentukan daftar saham berdasarkan indeks
        if index_filter == "kompas":
            stocks = KOMPAS100_STOCKS.keys()
        elif index_filter == "lq":
            stocks = LQ45_STOCKS.keys()
        elif index_filter == "mbx":
            stocks = MBX_STOCKS.keys()
        elif index_filter == "issi":
            stocks = ISSI_STOCKS.keys()
        else:
            stocks = set(list(LQ45_STOCKS.keys()) + list(KOMPAS100_STOCKS.keys()) + 
                         list(MBX_STOCKS.keys()) + list(ISSI_STOCKS.keys()))

        # Inisialisasi hasil
        results = []

        for ticker in stocks:
            try:
                # Ambil data harga 20 hari terakhir hingga end_date
                cursor.execute(
                    """
                    SELECT date, close FROM stocks 
                    WHERE ticker = ? AND date <= ? 
                    ORDER BY date DESC 
                    LIMIT 20
                    """,
                    (ticker, end_date.strftime("%Y-%m-%d"))
                )
                data = cursor.fetchall()
                if len(data) < 20:
                    logger.warning(f"Data tidak cukup untuk {ticker} pada {end_date.strftime('%Y-%m-%d')}")
                    continue

                # Buat DataFrame
                df = pd.DataFrame(data, columns=["date", "close"])
                df = df.sort_values("date")  # Urutkan ascending untuk perhitungan
                df["close"] = df["close"].astype(float)

                # Hitung Bollinger Bands (periode 20, deviasi 2)
                bb = ta.bbands(df["close"], length=20, std=2)
                if bb is None or bb.empty:
                    logger.warning(f"Gagal menghitung Bollinger Bands untuk {ticker}")
                    continue

                df = df.join(bb)
                latest_data = df.iloc[-1]
                close_price = latest_data["close"]
                lower_bb = latest_data["BBL_20_2.0"]
                upper_bb = latest_data["BBU_20_2.0"]

                # Cek apakah harga dekat atau di bawah lower Bollinger Band
                # Kriteria: harga <= lower BB atau dalam 5% dari lower BB
                if pd.notna(lower_bb) and pd.notna(close_price):
                    threshold = lower_bb * 1.05  # 5% di atas lower BB
                    if close_price <= threshold:
                        distance_to_lower = ((close_price - lower_bb) / lower_bb * 100) if lower_bb > 0 else 0
                        results.append({
                            "ticker": ticker,
                            "close_price": close_price,
                            "lower_bb": lower_bb,
                            "upper_bb": upper_bb,
                            "distance_to_lower": distance_to_lower
                        })

            except Exception as e:
                logger.warning(f"Gagal memproses {ticker}: {str(e)}")
                continue

        conn.close()

        if not results:
            index_name = index_filter.upper() if index_filter else "Semua Indeks"
            date_str = end_date.strftime('%Y-%m-%d')
            message = f"Tidak ada saham di {index_name} yang berada di dekat atau di bawah lower Bollinger Bands pada {date_str}."
            await update.message.reply_text(message, parse_mode="Markdown")
            return

        # Urutkan berdasarkan jarak ke lower BB (ascending, lebih dekat ke lower BB lebih diutamakan)
        results.sort(key=lambda x: x["distance_to_lower"])
        top_results = results[:30]  # Ambil top 30

        # Format output dalam tabel Markdown
        index_name = index_filter.upper() if index_filter else "Semua Indeks"
        date_str = end_date.strftime('%Y-%m-%d')
        message = f"📊 *Saham di Dekat atau di Bawah Lower Bollinger Bands ({index_name}, {date_str})*\n\n"
        message += "| Saham | Harga Penutupan (Rp) | Lower BB (Rp) | Upper BB (Rp) | Jarak ke Lower BB (%) |\n"
        message += "|-------|----------------------|---------------|---------------|-----------------------|\n"
        for result in top_results:
            ticker = result["ticker"]
            close_price = result["close_price"]
            lower_bb = result["lower_bb"]
            upper_bb = result["upper_bb"]
            distance = result["distance_to_lower"]
            emoji = "🔴" if distance <= 0 else "🟡"
            message += f"| {ticker:<5} | {close_price:,.0f} | {lower_bb:,.0f} | {upper_bb:,.0f} | {emoji} {distance:+.2f} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"Bottom Bollinger Bands untuk {index_name} pada {date_str} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in bottom_bollinger_bands: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data Bollinger Bands. Silakan coba lagi.",
            parse_mode="Markdown"
        )        
    
async def bottom_bollinger_with_green_candles(update: Update, context: ContextTypes.DEFAULT_TYPE, num_green_candles: int):
    """Menampilkan saham di dekat atau di bawah lower Bollinger Bands dengan jumlah candle hijau tertentu."""
    try:
        args = context.args
        index_filter = None
        date_str = None
        command = "bbh1" if num_green_candles == 1 else "bbh2"

        # Parsing argumen
        if args:
            if args[0].lower() in ["kompas", "lq", "mbx", "issi"]:
                index_filter = args[0].lower()
                date_str = args[1] if len(args) > 1 else None
            else:
                date_str = args[0]

        # Validasi format tanggal
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        if date_str:
            try:
                end_date = datetime.strptime(date_str, "%Y-%m-%d")
            except ValueError:
                conn.close()
                await update.message.reply_text(
                    f"Format tanggal tidak valid. Gunakan: /{command} [index] yyyy-mm-dd (contoh: /{command} 2025-06-13 atau /{command} kompas 2025-06-13).",
                    parse_mode="Markdown"
                )
                return
        else:
            cursor.execute("SELECT MAX(date) FROM stocks")
            latest_date = cursor.fetchone()[0]
            if not latest_date:
                conn.close()
                await update.message.reply_text("Data saham tidak ditemukan.", parse_mode="Markdown")
                return
            end_date = datetime.strptime(latest_date, "%Y-%m-%d")

        # Tentukan daftar saham berdasarkan indeks
        if index_filter == "kompas":
            stocks = KOMPAS100_STOCKS.keys()
        elif index_filter == "lq":
            stocks = LQ45_STOCKS.keys()
        elif index_filter == "mbx":
            stocks = MBX_STOCKS.keys()
        elif index_filter == "issi":
            stocks = ISSI_STOCKS.keys()
        else:
            stocks = set(list(LQ45_STOCKS.keys()) + list(KOMPAS100_STOCKS.keys()) +
                         list(MBX_STOCKS.keys()) + list(ISSI_STOCKS.keys()))

        # Inisialisasi hasil
        results = []

        for ticker in stocks:
            try:
                # Ambil data harga (22 hari untuk BB + candle hijau)
                cursor.execute(
                    """
                    SELECT date, open, close FROM stocks 
                    WHERE ticker = ? AND date <= ? 
                    ORDER BY date DESC 
                    LIMIT ?
                    """,
                    (ticker, end_date.strftime("%Y-%m-%d"), 20 + num_green_candles)
                )
                data = cursor.fetchall()
                if len(data) < 20 + num_green_candles:
                    logger.warning(f"Data tidak cukup untuk {ticker} pada {end_date.strftime('%Y-%m-%d')}")
                    continue

                # Buat DataFrame
                df = pd.DataFrame(data, columns=["date", "open", "close"])
                df = df.sort_values("date")  # Urutkan ascending
                df["close"] = df["close"].astype(float)
                if "open" in df.columns and df["open"].notna().any():
                    df["open"] = df["open"].astype(float)
                else:
                    df["open"] = np.nan  # Jika tidak ada data open

                # Hitung Bollinger Bands (periode 20, deviasi 2) untuk hari terakhir
                bb = ta.bbands(df["close"].iloc[-20:], length=20, std=2)
                if bb is None or bb.empty:
                    logger.warning(f"Gagal menghitung Bollinger Bands untuk {ticker}")
                    continue

                df_last_20 = df.iloc[-20:].copy()
                df_last_20 = df_last_20.join(bb)
                latest_data = df_last_20.iloc[-1]
                close_price = latest_data["close"]
                lower_bb = latest_data["BBL_20_2.0"]
                upper_bb = latest_data["BBU_20_2.0"]

                # Cek apakah harga dekat atau di bawah lower Bollinger Band
                if pd.notna(lower_bb) and pd.notna(close_price):
                    threshold = lower_bb * 1.05  # 5% di atas lower BB
                    if close_price > threshold:
                        continue  # Lewati jika tidak dekat lower BB

                    # Cek candle hijau
                    green_candles = 0
                    for i in range(1, num_green_candles + 1):
                        current_day = df.iloc[-i]
                        prev_day = df.iloc[-i - 1] if i < len(df) else None
                        if pd.notna(current_day["open"]):
                            if current_day["close"] > current_day["open"]:
                                green_candles += 1
                            else:
                                green_candles = 0
                                break
                        elif prev_day is not None:
                            if current_day["close"] > prev_day["close"]:
                                green_candles += 1
                            else:
                                green_candles = 0
                                break
                        else:
                            green_candles = 0
                            break

                    if green_candles == num_green_candles:
                        distance_to_lower = ((close_price - lower_bb) / lower_bb * 100) if lower_bb > 0 else 0
                        results.append({
                            "ticker": ticker,
                            "close_price": close_price,
                            "lower_bb": lower_bb,
                            "upper_bb": upper_bb,
                            "distance_to_lower": distance_to_lower
                        })

            except Exception as e:
                logger.warning(f"Gagal memproses {ticker}: {str(e)}")
                continue

        conn.close()

        if not results:
            index_name = index_filter.upper() if index_filter else "Semua Indeks"
            date_str = end_date.strftime("%Y-%m-%d")
            candle_str = "1 candle hijau" if num_green_candles == 1 else "2 candle hijau"
            message = f"Tidak ada saham di {index_name} yang berada di dekat atau di bawah lower Bollinger Bands dengan {candle_str} pada {date_str}."
            await update.message.reply_text(message, parse_mode="Markdown")
            return

        # Urutkan berdasarkan jarak ke lower BB
        results.sort(key=lambda x: x["distance_to_lower"])
        top_results = results[:30]  # Ambil top 30

        # Format output dalam tabel Markdown
        index_name = index_filter.upper() if index_filter else "Semua Indeks"
        date_str = end_date.strftime("%Y-%m-%d")
        candle_str = "1 Candle Hijau" if num_green_candles == 1 else "2 Candle Hijau"
        message = f"📊 *Saham di Dekat Lower Bollinger Bands dengan {candle_str} ({index_name}, {date_str})*\n\n"
        message += "| Saham | Harga Penutupan (Rp) | Lower BB (Rp) | Upper BB (Rp) | Jarak ke Lower BB (%) |\n"
        message += "|-------|----------------------|---------------|---------------|-----------------------|\n"
        for result in top_results:
            ticker = result["ticker"]
            close_price = result["close_price"]
            lower_bb = result["lower_bb"]
            upper_bb = result["upper_bb"]
            distance = result["distance_to_lower"]
            emoji = "🔴" if distance <= 0 else "🟡"
            message += f"| {ticker:<5} | {close_price:,.0f} | {lower_bb:,.0f} | {upper_bb:,.0f} | {emoji} {distance:+.2f} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"Saham dengan {candle_str.lower()} untuk {index_name} pada {date_str} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in bottom_bollinger_with_green_candles: {str(e)}")
        await update.message.reply_text(
            f"Terjadi kesalahan saat mengambil data untuk /{command}. Silakan coba lagi.",
            parse_mode="Markdown"
        )

async def bbh1(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler untuk /bbh1 (1 candle hijau)."""
    await bottom_bollinger_with_green_candles(update, context, num_green_candles=1)

async def bbh2(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler untuk /bbh2 (2 candle hijau)."""
    await bottom_bollinger_with_green_candles(update, context, num_green_candles=2)      
    
