async def idx_sector_performance(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan kenaikan dan penurunan indeks IDX per sektor berdasarkan Yahoo Finance."""
    logger.info(f"Perintah /idx_sector dipanggil oleh user {update.effective_user.id} dengan args: {context.args}")
    try:
        args = context.args
        index_filter = None

        # Parsing argumen untuk filter indeks
        if args:
            index_filter = args[0].lower()
            if index_filter not in ["kompas", "lq", "mbx", "issi"]:
                await update.message.reply_text(
                    "Indeks tidak valid. Gunakan: /idx_sector [kompas|lq|mbx|issi] (contoh: /idx_sector kompas)",
                    parse_mode="Markdown"
                )
                return

        # Tentukan daftar saham berdasarkan indeks
        if index_filter == "kompas":
            stocks = KOMPAS100_STOCKS.keys()
        elif index_filter == "lq":
            stocks = LQ45_STOCKS.keys()
        elif index_filter == "mbx":
            stocks = MBX_STOCKS.keys()
        elif index_filter == "issi":
            stocks = ISSI_STOCKS.keys()
        else:
            stocks = set(list(LQ45_STOCKS.keys()) + list(KOMPAS100_STOCKS.keys()) +
                         list(MBX_STOCKS.keys()) + list(ISSI_STOCKS.keys()))

        # Inisialisasi hasil per sektor
        sector_data = {sector: [] for sector in SECTORS.values()}

        # Ambil data harga dari yfinance dan kelompokkan berdasarkan sektor
        for ticker in stocks:
            try:
                ticker_data = yf.Ticker(ticker + ".JK")
                price_data = ticker_data.history (period="1d")
                if price_data.empty:
                    logger.warning(f"Tidak ada data harga untuk {ticker}.JK")
                    continue

                close_price = float(price_data["Close"].iloc[-1])
                open_price = float(price_data["Open"].iloc[-1])
                percent_change = ((close_price - open_price) / open_price * 100) if open_price > 0 else 0

                # Validasi harga realistis
                if close_price < 50 or close_price > 50000:
                    logger.warning(f"Harga tidak realistis untuk {ticker}.JK: Rp {close_price:,.2f}")
                    continue

                # Dapatkan sektor saham dari info yfinance
                info = ticker_data.info
                sector_key = info.get("sector", "").lower()
                sector_name = SECTORS.get(sector_key, "Lainnya")
                
                sector_data[sector_name].append({
                    "ticker": ticker,
                    "percent_change": percent_change
                })
            except Exception as e:
                logger.warning(f"Gagal memproses {ticker}: {str(e)}")
                continue

        # Hitung rata-rata perubahan per sektor
        sector_results = []
        for sector, data in sector_data.items():
            if data:
                avg_change = sum(item["percent_change"] for item in data) / len(data)
                sector_results.append({
                    "sector": sector,
                    "avg_change": avg_change,
                    "count": len(data)
                })

        if not sector_results:
            index_name = index_filter.upper() if index_filter else "Semua Indeks"
            await update.message.reply_text(
                f"Tidak ada data performa sektoral untuk {index_name} saat ini.",
                parse_mode="Markdown"
            )
            return

        # Urutkan berdasarkan rata-rata perubahan (descending)
        sector_results.sort(key=lambda x: x["avg_change"], reverse=True)

        # Format output dalam tabel Markdown
        index_name = index_filter.upper() if index_filter else "Semua Indeks"
        date_str = datetime.now(pytz.timezone('Asia/Jakarta')).strftime("Tanggal %Y-%m-%d %H:%M:%S")
        message = f"📈 *Performa Sektoral IDX ({index_name}, {date_str})*\n\n"
        message += "| Sektor | Rata-rata Perubahan (%) | Jumlah Saham |\n"
        message += "|--------|-------------------------|--------------|\n"
        for result in sector_results:
            sector = result["sector"]
            avg_change = result["avg_change"]
            count = result["count"]
            message += f"| {sector:<20} | {avg_change:+.2f} | {count:>2} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"Performa sektoral untuk {index_name} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in idx_sector_performance: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data performa sektoral. Silakan coba lagi.",
            parse_mode="Markdown"
        )

# Masukkan API Key Anda di sini
CMC_API_KEY = '318bf316-3933-4106-8405-3085972c7caf'

# Endpoint API CoinMarketCap
url = 'https://pro-api.coinmarketcap.com/v1/cryptocurrency/listings/latest'

# Header untuk autentikasi API
headers = {
    'Accepts': 'application/json',
    'X-CMC_PRO_API_KEY': CMC_API_KEY,
}

# Fungsi untuk mendapatkan data dari API
def get_crypto_data(start, limit):
    params = {
        'start': str(start),
        'limit': str(limit),
        'convert': 'USD'
    }
    response = requests.get(url, headers=headers, params=params)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Error fetching data at start={start}: {response.status_code}")
        return None

# Fungsi untuk memfilter koin naik dan turun
def filter_top_coins(all_coins):
    top_gainers = []
    top_losers = []

    for coin in all_coins:
        symbol = coin['symbol']
        name = coin['name']
        price = coin['quote']['USD']['price']
        percent_change_24h = coin['quote']['USD']['percent_change_24h']
        website = f"https://coinmarketcap.com/currencies/{coin['slug']}/"

        if percent_change_24h > 0:
            top_gainers.append({
                'Rank': len(top_gainers) + 1,
                'Symbol': symbol,
                'Name': name,
                'Price (USD)': price,
                '24h Change (%)': percent_change_24h,
                'Website': website
            })
        elif percent_change_24h < 0:
            top_losers.append({
                'Rank': len(top_losers) + 1,
                'Symbol': symbol,
                'Name': name,
                'Price (USD)': price,
                '24h Change (%)': percent_change_24h,
                'Website': website
            })

    # Urutkan dan ambil 50 teratas
    top_gainers = sorted(top_gainers, key=lambda x: x['24h Change (%)'], reverse=True)[:5000]
    top_losers = sorted(top_losers, key=lambda x: x['24h Change (%)'])[:5000]

    # Perbarui ranking setelah pengurutan
    for i, coin in enumerate(top_gainers, 1):
        coin['Rank'] = i
    for i, coin in enumerate(top_losers, 1):
        coin['Rank'] = i

    return top_gainers, top_losers

# Fungsi untuk menyimpan ke SQLite
def save_to_sqlite(db_name, total_coins, all_coins, top_gainers, top_losers):
    # Koneksi ke database SQLite
    conn = sqlite3.connect(db_name)
    cursor = conn.cursor()

    # Buat tabel metadata
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS metadata (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            description TEXT,
            value TEXT,
            timestamp TEXT
        )
    ''')

    # Buat tabel gainers
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS gainers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rank INTEGER,
            symbol TEXT,
            name TEXT,
            price_usd REAL,
            percent_change_24h REAL,
            website TEXT,
            timestamp TEXT
        )
    ''')

    # Buat tabel losers
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS losers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rank INTEGER,
            symbol TEXT,
            name TEXT,
            price_usd REAL,
            percent_change_24h REAL,
            website TEXT,
            timestamp TEXT
        )
    ''')

    # Tambahkan timestamp saat ini
    current_timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    # Simpan metadata
    metadata = [
        ('Total Coins in CMC', str(total_coins), current_timestamp),
        ('Total Coins Scanned', str(len(all_coins)), current_timestamp),
        ('Timestamp', current_timestamp, current_timestamp)
    ]
    cursor.executemany('INSERT INTO metadata (description, value, timestamp) VALUES (?, ?, ?)', metadata)

    # Simpan top gainers
    gainers_data = [
        (
            coin['Rank'],
            coin['Symbol'],
            coin['Name'],
            coin['Price (USD)'],
            coin['24h Change (%)'],
            coin['Website'],
            current_timestamp
        ) for coin in top_gainers
    ]
    cursor.executemany('''
        INSERT INTO gainers (rank, symbol, name, price_usd, percent_change_24h, website, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    ''', gainers_data)

    # Simpan top losers
    losers_data = [
        (
            coin['Rank'],
            coin['Symbol'],
            coin['Name'],
            coin['Price (USD)'],
            coin['24h Change (%)'],
            coin['Website'],
            current_timestamp
        ) for coin in top_losers
    ]
    cursor.executemany('''
        INSERT INTO losers (rank, symbol, name, price_usd, percent_change_24h, website, timestamp)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    ''', losers_data)

    # Commit dan tutup koneksi
    conn.commit()
    conn.close()

db_name = "cmc.db"
async def tgc_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # Koneksi ke database
    conn = sqlite3.connect('cmc.db')
    cursor = conn.cursor()
    
    # Query untuk mengambil 100 top gainer berdasarkan percent_change_24h
    cursor.execute("SELECT name, percent_change_24h, website FROM gainers ORDER BY percent_change_24h DESC LIMIT 100")
    rows = cursor.fetchall()
    
    # Membuat pesan respons
    message = "Top 100 Gainer Coins:\n\n"
    for i, (name, percent_change, website) in enumerate(rows, 1):
        # Menggunakan shortlink sederhana (misalnya t.me dengan parameter)
        shortlink = f"{website}"
        message += f"{i}. {name} - {percent_change:.2f}%\n   [Link]({shortlink})\n"
    
    # Mengirim pesan dengan markdown untuk mendukung link
    await update.message.reply_text(message, parse_mode='Markdown')
    
    # Menutup koneksi
    conn.close()

async def tgc_command_date(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # Get date from command arguments or use today if none provided
    date_str = context.args[0] if context.args else datetime.now().strftime('%Y-%m-%d')
    
    try:
        # Validate date format
        datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        await update.message.reply_text("Invalid date format. Please use YYYY-MM-DD")
        return

    # Connect to database
    conn = sqlite3.connect('cmc.db')
    cursor = conn.cursor()
    
    # Query to get top 100 gainers for the specified date (using timestamp)
    cursor.execute(
        "SELECT name, percent_change_24h, website, timestamp FROM gainers WHERE substr(timestamp, 1, 10) = ? ORDER BY percent_change_24h DESC LIMIT 200",
        (date_str,)
    )
    rows = cursor.fetchall()
    
    # Create response message
    if not rows:
        await update.message.reply_text(f"No data available for {date_str}")
        conn.close()
        return

    # Split into chunks of 50 to avoid message length limit
    chunk_size = 50
    for i in range(0, len(rows), chunk_size):
        chunk = rows[i:i + chunk_size]
        message = f"Top 100 Gainer Coins for {date_str} (Part {i//chunk_size + 1}):\n\n"
        for j, (name, percent_change, website, timestamp) in enumerate(chunk, 1):
            shortlink = f"{website}"
            message += f"{i + j}. {name} - {percent_change:.2f}% (at {timestamp})\n   [Link]({shortlink})\n"
        
        # Send message with markdown for link support
        await update.message.reply_text(message, parse_mode='Markdown')
    
    # Close connection
    conn.close()    

