async def high_volume_breakout_by_date(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Menampilkan saham dengan High Volume Breakout berdasarkan IHSG untuk tanggal tertentu dari stock_data.db."""
    logger.info(f"Perintah /hvbd dipanggil oleh user {update.effective_user.id} dengan args: {context.args}")
    try:
        # Cek apakah ada argumen tanggal
        if not context.args or len(context.args) != 1:
            await update.message.reply_text(
                "Silakan masukkan tanggal dalam format YYYY-MM-DD, contoh: /hvbd 2025-06-24",
                parse_mode="Markdown"
            )
            return

        # Parse tanggal dari argumen
        target_date_str = context.args[0]
        try:
            target_date = datetime.strptime(target_date_str, "%Y-%m-%d").date()
            wib_timezone = pytz.timezone('Asia/Jakarta')
            current_date = datetime.now(wib_timezone).date()
            if target_date > current_date:
                await update.message.reply_text(
                    "Tanggal tidak boleh lebih dari hari ini. Gunakan tanggal hingga 25-06-2025.",
                    parse_mode="Markdown"
                )
                return
        except ValueError:
            await update.message.reply_text(
                "Format tanggal salah. Gunakan format YYYY-MM-DD, contoh: /hvbd 2025-06-24",
                parse_mode="Markdown"
            )
            return

        # Tentukan daftar saham dari IHSG (aproksimasi)
        stocks = set(list(LQ45_STOCKS.keys()) + list(KOMPAS100_STOCKS.keys()) +
                     list(MBX_STOCKS.keys()) + list(ISSI_STOCKS.keys()))

        # Inisialisasi hasil
        results = []

        # Hubungkan ke database
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()

        # Ambil data dari stock_data.db
        for ticker in stocks:
            try:
                # Ambil data untuk target_date (gunakan 'vol' sebagai placeholder untuk volume)
                cursor.execute(
                    "SELECT Volume, close FROM stock_data WHERE symbol = ? AND date = ?",  # Ganti 'vol' dan 'close' jika salah
                    (ticker, target_date_str)
                )
                target_row = cursor.fetchone()
                if not target_row:
                    logger.warning(f"Tidak ada data untuk {ticker} pada {target_date_str}")
                    continue

                current_volume, current_price = target_row
                transaction_value = current_volume * current_price

                # Hitung Volume MA 20
                start_date = (target_date - timedelta(days=19)).strftime("%Y-%m-%d")
                cursor.execute(
                    "SELECT Volume FROM stock_data WHERE symbol = ? AND date BETWEEN ? AND ?",  # Ganti 'vol' jika salah
                    (ticker, start_date, target_date_str)
                )
                ma20_data = cursor.fetchall()
                if len(ma20_data) >= 20:
                    volume_ma20 = sum(row[0] for row in ma20_data) / 20
                    if (current_volume > 2 * volume_ma20 and
                        current_volume <= 100000 and
                        transaction_value > 100000):  # Rp1 miliar
                        results.append({
                            "ticker": ticker,
                            "current_volume": current_volume,
                            "volume_ma20": volume_ma20,
                            "current_price": current_price,
                            "transaction_value": transaction_value
                        })
                else:
                    logger.warning(f"Data MA20 tidak cukup untuk {ticker} pada {target_date_str}")
                    continue

            except sqlite3.OperationalError as e:
                logger.warning(f"Gagal memproses {ticker} pada {target_date_str}: {str(e)}")
                continue

        conn.close()

        if not results:
            await update.message.reply_text(
                f"Tidak ada saham yang memenuhi kriteria High Volume Breakout untuk IHSG pada {target_date_str}.",
                parse_mode="Markdown"
            )
            return

        # Urutkan berdasarkan volume (descending) dan ambil top 10
        results.sort(key=lambda x: x["current_volume"], reverse=True)
        top_results = results[:10]

        # Format output dalam tabel Markdown
        date_str = target_date.strftime("%Y-%m-%d")
        message = f"📈 *High Volume Breakout by Date (IHSG, {date_str})*\n\n"
        message += "| Saham | Volume | Volume MA20 | Harga (Rp) | Nilai Transaksi (Rp) |\n"
        message += "|-------|--------|------------|------------|---------------------|\n"
        for result in top_results:
            ticker = result["ticker"]
            current_volume = result["current_volume"]
            volume_ma20 = result["volume_ma20"]
            current_price = result["current_price"]
            transaction_value = result["transaction_value"]
            message += f"| {ticker:<5} | {current_volume:,.0f} | {volume_ma20:,.0f} | {current_price:,.0f} | {transaction_value:,.0f} |\n"

        await update.message.reply_text(message, parse_mode="Markdown")
        logger.info(f"High Volume Breakout by Date untuk {date_str} dikirim ke user {update.effective_user.id}")

    except Exception as e:
        logger.error(f"Error in high_volume_breakout_by_date: {str(e)}")
        await update.message.reply_text(
            "Terjadi kesalahan saat mengambil data High Volume Breakout by Date. Silakan coba lagi.",
            parse_mode="Markdown"
        )
        
