def extract_pdf_data(pdf_path):
    """Mengekstrak data dari laporan PDF dan mengembalikan list of dictionaries."""
    try:
        with pdfplumber.open(pdf_path) as pdf:
            table = pdf.pages[0].extract_table()
            if not table:
                logger.error(f"Tidak ada tabel ditemukan di {pdf_path}")
                return []

            daily_data = []
            for row in table[1:]:  # Lewati header
                if len(row) < 5:
                    continue  # Lewati baris yang tidak lengkap
                keterangan = row[1].replace("\n", " ").strip()
                current_month = row[3].replace(",", "").replace("$", "").strip()
                
                # Konversi ke float, tangani nilai kosong
                try:
                    realisasi = float(current_month) / 1_000_000  # Konversi ke jutaan Rp
                except (ValueError, TypeError):
                    logger.warning(f"Nilai CURRENT MONTH tidak valid untuk {keterangan}: {current_month}")
                    continue

                # Petakan keterangan
                mapped_keterangan = KETERANGAN_MAPPING.get(keterangan, keterangan)
                daily_data.append({"keterangan": mapped_keterangan, "realisasi": realisasi})

            logger.info(f"Berhasil mengekstrak {len(daily_data)} entri dari {pdf_path}")
            return daily_data
    except Exception as e:
        logger.error(f"Error saat mengekstrak PDF {pdf_path}: {str(e)}")
        return []

def update_daily_achievement(data_list, date):
    """Memperbarui tabel goal_setting dengan data laba rugi harian."""
    try:
        conn = sqlite3.connect(DATABASE_PATHS)
        cursor = conn.cursor()

        for row in data_list:
            keterangan = row.get("keterangan")
            realisasi = row.get("realisasi")
            target = row.get("target")

            # Ambil target dari tahun_proyeksi jika tidak diberikan
            if target is None:
                cursor.execute("""
                    SELECT tahun_proyeksi FROM goal_setting 
                    WHERE keterangan = ? AND tanggal = '2023-12-31'
                """, (keterangan,))
                result = cursor.fetchone()
                target = result[0] if result and result[0] is not None else 0.0

            # Tentukan status berdasarkan pencapaian
            status = "Kuning"  # Default: kuning untuk data tidak lengkap
            if realisasi is not None and target is not None:
                status = "Hijau" if realisasi >= target else "Kuning"

            # Cek apakah data untuk keterangan dan tanggal sudah ada
            cursor.execute("""
                SELECT id FROM goal_setting WHERE keterangan = ? AND tanggal = ?
            """, (keterangan, date))
            existing = cursor.fetchone()

            if existing:
                # Update data jika sudah ada
                cursor.execute("""
                    UPDATE goal_setting
                    SET target = ?, realisasi = ?, status = ?
                    WHERE keterangan = ? AND tanggal = ?
                """, (target, realisasi, status, keterangan, date))
            else:
                # Insert data baru
                cursor.execute("""
                    INSERT INTO goal_setting (keterangan, tahun_proyeksi, target, realisasi, status, tanggal)
                    VALUES (?, ?, ?, ?, ?, ?)
                """, (keterangan, None, target, realisasi, status, date))

        conn.commit()
        logger.info(f"Data laba rugi harian untuk {date} berhasil diperbarui.")
    except Exception as e:
        logger.error(f"Error saat memperbarui data harian: {str(e)}")
        raise
    finally:
        conn.close()

def get_achievement_data(start_date=None, end_date=None):
    """Mengambil data pencapaian harian atau per periode."""
    try:
        conn = sqlite3.connect(DATABASE_PATHS)
        query = """
            SELECT keterangan, target, realisasi, status, tanggal 
            FROM goal_setting 
            WHERE target IS NOT NULL AND realisasi IS NOT NULL
        """
        params = []
        if start_date and end_date:
            query += " AND tanggal BETWEEN ? AND ?"
            params.extend([start_date, end_date])
        elif start_date:
            query += " AND tanggal = ?"
            params.append(start_date)

        df = pd.read_sql_query(query, conn, params=params)
        conn.close()
        return df
    except Exception as e:
        logger.error(f"Error saat mengambil data pencapaian: {str(e)}")
        return pd.DataFrame()

async def view_achievement(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan pencapaian harian atau per periode sebagai tabel gambar."""
    logger.info(f"Perintah /view_achievement dipanggil oleh user {update.effective_user.id}")
    try:
        # Ambil argumen tanggal dari perintah
        args = context.args
        if len(args) == 1:
            start_date = args[0]
            end_date = None
        elif len(args) == 2:
            start_date, end_date = args
        else:
            start_date = datetime.now(pytz.timezone('Asia/Jakarta')).strftime("%Y-%m-%d")
            end_date = None

        # Ambil data pencapaian
        df = get_achievement_data(start_date, end_date)
        if df.empty:
            await update.message.reply_text(
                "Tidak ada data pencapaian untuk periode tersebut.",
                parse_mode="Markdown"
            )
            return

        # Siapkan data untuk tabel
        table_data = []
        for _, row in df.iterrows():
            keterangan = row["keterangan"]
            target = f"{row['target']:,.2f}" if pd.notnull(row["target"]) else "-"
            realisasi = f"{row['realisasi']:,.2f}" if pd.notnull(row["realisasi"]) else "-"
            status = "🟢" if row["status"] == "Hijau" else "🟡"
            tanggal = row["tanggal"]
            table_data.append([keterangan, target, realisasi, status, tanggal])

        # Hitung total
        total_target = df["target"].sum() if not df.empty else 0
        total_realisasi = df["realisasi"].sum() if not df.empty else 0
        total_status = "🟢" if total_realisasi >= total_target else "🟡"

        # Buat gambar tabel
        headers = ["Keterangan", "Target (Juta Rp)", "Realisasi (Juta Rp)", "Status", "Tanggal"]
        img = create_table_image(headers, table_data, total_lots=None, avg_buy_price=None, avg_curr_price=None,
                                total_buy=total_target, total_val=total_realisasi, selisih_total=total_realisasi - total_target,
                                total_perf=None)

        # Simpan gambar ke buffer
        buffer = io.BytesIO()
        img.save(buffer, format="PNG")
        buffer.seek(0)

        # Kirim gambar ke Telegram
        current_time = datetime.now(pytz.timezone('Asia/Jakarta')).strftime("%Y-%m-%d %H:%M WIB")
        caption = f"📊 *Laporan Pencapaian*\nPer tanggal: {current_time}"
        if start_date and end_date:
            caption += f"\nPeriode: {start_date} s.d. {end_date}"
        elif start_date:
            caption += f"\nTanggal: {start_date}"
        await update.message.reply_photo(
            photo=buffer,
            caption=caption,
            parse_mode="Markdown"
        )
        logger.info(f"Laporan pencapaian berhasil dikirim untuk user {update.effective_user.id}")
    except Exception as e:
        logger.error(f"Error di view_achievement: {str(e)}")
        await update.message.reply_text(
            f"Terjadi kesalahan: {str(e)}",
            parse_mode="Markdown"
        )

def process_latest_pdf():
    """Memproses file PDF terbaru di direktori reports."""
    try:
        # Cari file PDF terbaru
        pdf_files = glob.glob(os.path.join(PDF_DIR, "rptProfitStatement - *.pdf"))
        if not pdf_files:
            logger.error(f"Tidak ada file PDF ditemukan di {PDF_DIR}")
            return

        # Ambil file terbaru berdasarkan nama (mengandung tanggal)
        latest_pdf = max(pdf_files, key=os.path.getmtime)
        logger.info(f"Memproses file PDF terbaru: {latest_pdf}")

        # Ekstrak tanggal dari nama file
        match = re.search(r'(\d{4}-\d{2}-\d{2})', latest_pdf)
        if not match:
            logger.error(f"Tidak dapat mengekstrak tanggal dari nama file: {latest_pdf}")
            return
        report_date = match.group(1)

        # Ekstrak data dari PDF
        daily_data = extract_pdf_data(latest_pdf)

        # Perbarui database
        update_daily_achievement(daily_data, report_date)
    except Exception as e:
        logger.error(f"Error saat memproses PDF terbaru: {str(e)}")
        raise
 

def init_db():
    try:
        if not DATABASE_PATH:
            raise ValueError("DATABASE_PATH tidak didefinisikan atau kosong")
        conn = sqlite3.connect(DATABASE_PATH)
        cursor = conn.cursor()
        # Buat tabel stock_data
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS stock_data (
                symbol TEXT,
                date TEXT,
                close REAL,
                prev_close REAL,
                prev_week_close REAL,
                sma20 REAL,
                sma50 REAL,
                rsi REAL,
                pe_ratio REAL,
                pb_ratio REAL,
                volatility REAL
            )
        ''')
        # Buat tabel lain (sesuaikan dengan kebutuhan)
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS feedback (
                user_id INTEGER,
                feedback TEXT,
                timestamp TEXT
            )
        ''')
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS watchlist (
                user_id INTEGER,
                symbol TEXT,
                PRIMARY KEY (user_id, symbol)
            )
        ''')
        conn.commit()
        logger.info("Database berhasil diinisialisasi")
    except Exception as e:
        logger.error(f"Gagal menginisialisasi database: {str(e)}")
        raise
    finally:
        if 'conn' in locals():
            conn.close()

async def shutdown():
    logger.info("Menutup koneksi database")
    DB_CONNECTION.close()   

import logging
import asyncio
from telegram.ext import Application, CommandHandler, MessageHandler, CallbackQueryHandler, filters, ContextTypes
from telegram import Update

# Konfigurasi logging dengan encoding UTF-8
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("bot.log", encoding="utf-8"),
        logging.StreamHandler(),
    ],
)
logger = logging.getLogger(__name__)

# Fungsi untuk logging aman
def safe_log(message):
    return message.encode("utf-8", errors="ignore").decode("utf-8")

# Debug handler untuk mencatat semua callback
async def debug_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if query:
        callback_data = query.data
        user_id = query.from_user.id
        chat_id = query.message.chat_id
        message_id = query.message.message_id
        logger.info(safe_log(f"Debug callback diterima: callback_data={callback_data}, user_id={user_id}, chat_id={chat_id}, message_id={message_id}"))
        await query.answer()
        await query.message.reply_text(f"Callback diterima: {callback_data}")
    else:
        logger.warning(safe_log(f"Debug callback diterima tanpa query: update={update.to_dict()}"))
    return

# Fallback handler untuk update yang tidak ditangani
async def fallback_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    logger.warning(safe_log(f"Update tidak ditangani: {update.to_dict()}"))
    if update.message:
        await update.message.reply_text("Perintah tidak dikenali. Coba /start atau /menu.")

async def main():
    global application
    init_db()
    ensure_database()

    application = Application.builder().token(TOKEN).build()
    application.job_queue.run_once(on_startup, 0)
    application.job_queue.run_repeating(update_all_news, interval=86400)
    application.add_error_handler(error_handler)
    application.job_queue.run_repeating(update_crypto_data, interval=21600)

    # Prioritaskan CallbackQueryHandler
    application.add_handler(CallbackQueryHandler(debug_callback))
    application.add_handler(CallbackQueryHandler(button_callback))
    application.add_handler(CallbackQueryHandler(handle_chart_button, pattern="^show_chart_"))
    application.add_handler(CallbackQueryHandler(pg_callback, pattern="^pg_period:"))
